// Punishment Watch — single-file Worker for the Cloudflare dashboard.
// Paste this whole file into the Worker's code editor and deploy.
// Settings > Variables and Secrets: LEAGUE_ID (text), SEASON (text, 2027),
// ESPN_S2 and ESPN_SWID (secrets, optional if the league is public), HIDE_TEAMS (text, optional).
// Generated by scripts/build-dashboard.mjs — edit the source files, not this one.

// ESPN proxy shared by every deploy style (Cloudflare Worker, local Node server, snapshot builder).
// Cookies stay server-side and are optional: leave them out if the league manager has made the
// league viewable to the public. Responses are streamed without parsing to stay under the free
// Cloudflare plan's 10 ms CPU limit.

const ESPN = 'https://lm-api-reads.fantasy.espn.com/apis/v3/games/fba/seasons';
const VIEWS = new Set(['mSettings', 'mTeam', 'mRoster', 'mMatchup', 'mMatchupScore', 'mStatus', 'mScoreboard', 'mStandings', 'mTransactions2']);
const LIVE_TTL = 90;
const PAST_TTL = 12 * 3600;
const SCHEDULE_TTL = 6 * 3600;
const SCOREBOARD = 'https://site.api.espn.com/apis/site/v2/sports/basketball/nba/scoreboard';
const INJURIES = 'https://site.api.espn.com/apis/site/v2/sports/basketball/nba/injuries';

// Stand-in for the Workers Cache API when running under Node.
const memory = new Map();
const memoryCache = {
  async match(key) {
    const hit = memory.get(key.url);
    if (!hit || hit.expires < Date.now()) return undefined;
    return new Response(hit.body, hit.init);
  },
  async put(key, res) {
    const maxAge = Number(/max-age=(\d+)/.exec(res.headers.get('cache-control') || '')?.[1] ?? 60);
    memory.set(key.url, { expires: Date.now() + maxAge * 1000, body: await res.arrayBuffer(), init: { status: res.status, headers: [...res.headers] } });
    while (memory.size > 40) memory.delete(memory.keys().next().value);
  },
};

// Cookies as typed into a settings box: tolerate quotes, a pasted "name=" prefix and URL-encoded braces.
function cookieHeader(env) {
  const clean = (v) => String(v ?? '').replace(/[\r\n]/g, '').trim().replace(/^(["'])(.*)\1$/, '$2').trim();
  const s2 = clean(env.ESPN_S2).replace(/^espn_s2=/i, '');
  let swid = clean(env.ESPN_SWID).replace(/^swid=/i, '');
  if (/%7B/i.test(swid)) swid = decodeURIComponent(swid);
  if (swid) swid = `{${swid.replace(/[{}]/g, '')}}`;
  return s2 && swid ? `espn_s2=${s2}; SWID=${swid}` : '';
}

// ESPN names NBA seasons by the year they end (2026-27 = 2027).
function defaultSeason(now = new Date()) {
  return now.getUTCFullYear() + (now.getUTCMonth() >= 7 ? 1 : 0);
}

// Fresh data (the Refresh button, `fresh=1`) is limited to once every REFRESH_SECONDS (default 5) for each route,
// per signed-in team, or per device when nobody is signed in. Over the limit it is not an error: the request is
// answered from the cache, which is at most a minute or two old, and the response says so (x-refresh-limited).
async function handleApi(request, env, ctx) {
  const state = { limited: false };
  const res = await handle(request, env, ctx, state);
  if (!state.limited) return res;
  const out = new Response(res.body, res); // cached responses have read-only headers
  out.headers.set('x-refresh-limited', '1');
  return out;
}

async function handle(request, env, ctx, state) {
  const url = new URL(request.url);
  const signIn = url.pathname === '/api/login' || url.pathname === '/api/logout';
  const board = url.pathname === '/api/board';
  const allowed = signIn ? ['POST'] : board ? ['GET', 'POST'] : ['GET'];
  if (!allowed.includes(request.method)) return json({ error: signIn ? 'Use POST to sign in.' : 'Only GET is supported.' }, 405);
  const season = Number(env.SEASON) || defaultSeason();
  const leagueId = String(env.LEAGUE_ID || '').trim();
  const cookie = cookieHeader(env);
  const refreshSeconds = env.REFRESH_SECONDS == null || env.REFRESH_SECONDS === '' ? 5 : Number(env.REFRESH_SECONDS);
  // true when this request may bypass the cache (it asked for fresh data and is within its allowance)
  const wantFresh = async (route) => {
    if (url.searchParams.get('fresh') !== '1') return false;
    if (!(refreshSeconds > 0)) return true;
    if (await refreshLimited(request, env, route, refreshSeconds)) {
      state.limited = true;
      return false;
    }
    return true;
  };

  try {
    if (url.pathname === '/api/config') {
      return json({
        configured: Boolean(leagueId),
        hasCookies: Boolean(cookie),
        leagueId: leagueId || null,
        season,
        platform: env.PLATFORM || 'cloudflare',
        weekStart: env.WEEK_START || null,
        timezone: env.TIMEZONE || null,
        pins: pinsOf(env).size > 0, // whether team PINs are switched on; the PINs themselves never leave the server
        hideTeams: String(env.HIDE_TEAMS || '').split(',').map((s) => s.trim()).filter(Boolean),
      });
    }

    // The trade block: each team's block, targets, untouchables and notes, readable by everyone, editable by that team
    if (board) return request.method === 'POST' ? await saveBoard(request, env, leagueId) : await readBoard(request, env, leagueId);

    // Team PINs: optional, and only a speed bump among friends (see README). Set TEAM_PINS="1=482913,2=193846".
    if (url.pathname === '/api/me') return json({ pins: pinsOf(env).size > 0, teamId: await teamFromCookie(request, env) });
    if (url.pathname === '/api/logout') return json({ teamId: null }, 200, { 'set-cookie': sessionCookie('', 0, url) });
    if (url.pathname === '/api/login') return await login(request, env, url);

    if (url.pathname === '/api/pro-schedule') {
      return await proxy(`${ESPN}/${season}?view=proTeamSchedules_wl`, { ctx, ttl: SCHEDULE_TTL, fresh: false, what: 'schedule', season });
    }

    // Which games are scheduled, in play or final on a US date. No login needed; trimmed to what the page reads.
    if (url.pathname === '/api/scoreboard') {
      const date = url.searchParams.get('date') || '';
      if (!/^\d{8}$/.test(date)) return json({ error: 'date must look like 20261028.' }, 400);
      return trimmed(`scoreboard-${date}`, 30, ctx, await wantFresh('scoreboard'), async () => {
        const res = await fetch(`${SCOREBOARD}?dates=${date}`, { headers: { Accept: 'application/json' } });
        if (!res.ok) return json({ error: `ESPN’s scoreboard returned HTTP ${res.status}.` }, 502);
        const body = await res.json();
        return { events: (body.events || []).map((e) => ({ id: e.id, date: e.date, status: { type: { state: e.status?.type?.state, detail: e.status?.type?.detail } } })) };
      });
    }

    // Who is hurt and when ESPN expects them back. Trimmed to what the page reads (the raw feed is about 1 MB).
    if (url.pathname === '/api/injuries') {
      return trimmed('injuries', 1800, ctx, await wantFresh('injuries'), async () => {
        const res = await fetch(INJURIES, { headers: { Accept: 'application/json' } });
        if (!res.ok) return json({ error: `ESPN’s injury report returned HTTP ${res.status}.` }, 502);
        const players = [];
        for (const team of (await res.json()).injuries || []) {
          for (const i of team.injuries || []) {
            const playerId = Number(/\/id\/(\d+)/.exec(i.athlete?.links?.find((l) => l.rel?.includes('playercard'))?.href || '')?.[1]);
            if (!playerId) continue;
            // No timetable in the write-up means the date is ESPN's placeholder, not a real estimate
            const guess = /timetable|indefinite/i.test(`${i.shortComment || ''} ${i.longComment || ''}`);
            players.push({ playerId, status: i.status, returnDate: i.details?.returnDate || null, guess, type: i.details?.type || null, detail: i.details?.detail || null, comment: String(i.shortComment || '').slice(0, 180) });
          }
        }
        return { players };
      });
    }

    // Best players nobody owns, for working out what a replacement is worth. Trimmed to what the page reads.
    if (url.pathname === '/api/free-agents') {
      if (!leagueId) return json({ error: 'LEAGUE_ID is not set.' }, 500);
      const filter = {
        players: {
          filterStatus: { value: ['FREEAGENT', 'WAIVERS'] },
          limit: 60,
          sortAppliedStatTotal: { sortAsc: false, sortPriority: 1, value: `10${season}` }, // by preseason projection
          filterStatsForTopScoringPeriodIds: { value: 5, additionalValue: [`00${season}`, `10${season}`] },
        },
      };
      const target = `${ESPN}/${season}/segments/0/leagues/${leagueId}?view=kona_player_info`;
      return trimmed('free-agents', 600, ctx, await wantFresh('free-agents'), async () => {
        const res = await proxy(target, { cookie, ctx, ttl: 1, fresh: true, what: 'league', season, leagueId, headers: { 'x-fantasy-filter': JSON.stringify(filter) }, variant: '#fa' });
        if (!res.ok) return res;
        const stat = (p, id) => p.stats?.find((s) => s.id === id);
        return {
          players: ((await res.json()).players || []).map((e) => ({
            playerId: e.player.id,
            name: e.player.fullName,
            proTeamId: e.player.proTeamId,
            injury: e.player.injuryStatus || 'ACTIVE',
            seasonGP: stat(e.player, `00${season}`)?.stats?.['42'] ?? 0,
            seasonAvg: stat(e.player, `00${season}`)?.appliedAverage ?? 0,
            projAvg: stat(e.player, `10${season}`)?.appliedAverage ?? 0,
            eligibleSlots: e.player.eligibleSlots || [],
          })),
        };
      });
    }

    if (url.pathname === '/api/league') {
      if (!leagueId) return json({ error: 'LEAGUE_ID is not set.' }, 500);
      if (!/^\d{1,10}$/.test(leagueId) || Number(leagueId) > 2147483647) {
        return json({ error: `LEAGUE_ID “${leagueId}” isn’t a valid league number. It is the digits after leagueId= in your ESPN league link, like 12345678.` }, 500);
      }
      const views = url.searchParams.getAll('view').filter((v) => VIEWS.has(v));
      if (!views.length) return json({ error: 'Ask for at least one ESPN view.' }, 400);
      const q = new URLSearchParams();
      for (const v of views) q.append('view', v);
      const sp = url.searchParams.get('scoringPeriodId');
      if (sp) {
        if (!/^\d{1,3}$/.test(sp)) return json({ error: 'scoringPeriodId must be a number.' }, 400);
        q.set('scoringPeriodId', sp);
      }
      const target = `${ESPN}/${season}/segments/0/leagues/${leagueId}?${q}`;
      const past = url.searchParams.get('past') === '1';
      return await proxy(target, { cookie, ctx, ttl: past ? PAST_TTL : LIVE_TTL, fresh: await wantFresh('league'), what: 'league', season, leagueId });
    }

    return json({ error: 'Not found.' }, 404);
  } catch (err) {
    return json({ error: `Couldn’t reach ESPN: ${err.message}` }, 502);
  }
}

// Cache the trimmed answer, not ESPN's big one: parsing a megabyte of JSON on every request would eat the
// Cloudflare free plan's 10 ms of CPU, but it costs nothing when the cached answer is served as it is.
// `make` returns the object to send, or a Response (an error) which is passed through uncached.
async function trimmed(name, ttl, ctx, fresh, make) {
  const cache = globalThis.caches?.default ?? memoryCache;
  const key = new Request(`https://espn-cache.invalid/trimmed/${name}`);
  if (!fresh) {
    const hit = await cache.match(key).catch(() => null);
    if (hit) return hit;
  }
  const made = await make();
  if (made instanceof Response) return made;
  const out = new Response(JSON.stringify(made), { headers: { 'content-type': 'application/json; charset=utf-8', 'cache-control': `public, max-age=${ttl}` } });
  ctx.waitUntil(cache.put(key, out.clone()).catch(() => {}));
  return out;
}

async function proxy(target, { cookie = '', ctx, ttl, fresh, what, season, leagueId, headers: extra = {}, variant = '' }) {
  const cache = globalThis.caches?.default ?? memoryCache;
  const key = new Request(`https://espn-cache.invalid/${encodeURIComponent(target)}${variant}`);
  if (!fresh) {
    const hit = await cache.match(key).catch(() => null);
    if (hit) return hit;
  }

  const headers = { Accept: 'application/json', 'User-Agent': 'Mozilla/5.0 (fantasy-punishment-tracker)', ...extra };
  if (cookie) headers.Cookie = cookie;

  const res = await fetch(target, { headers, redirect: 'manual' });
  const type = res.headers.get('content-type') || '';
  const failure = res.ok && type.includes('json') ? null : explain(res, { cookie, what, season, leagueId, type });
  if (failure) return json({ error: failure.error }, failure.status);

  const out = new Response(res.body, {
    status: 200,
    headers: { 'content-type': 'application/json; charset=utf-8', 'cache-control': `public, max-age=${ttl}` },
  });
  ctx.waitUntil(cache.put(key, out.clone()).catch(() => {}));
  return out;
}

// Plain-language reason for a failed ESPN response.
function explain(res, { cookie, what, season, leagueId, type }) {
  const s = res.status;
  if ((s >= 300 && s < 400) || s === 401 || s === 403 || (res.ok && !type.includes('json'))) {
    return {
      status: 401,
      error: cookie
        ? 'ESPN won’t show this league to the saved login. The cookies have probably expired (logging out of ESPN or changing your password kills them), or that ESPN account isn’t a member of the league. Copy espn_s2 and SWID again from a browser that is logged in and update them.'
        : 'This league is private and no ESPN login is set. Add your espn_s2 and SWID cookies, or ask the league manager to turn on “Make league viewable to public” in league settings.',
    };
  }
  if (s === 404) {
    return what === 'schedule'
      ? { status: 404, error: `ESPN has no NBA schedule for season ${season}. SEASON should be the year the season ends (2026-27 is 2027).` }
      : { status: 404, error: `ESPN couldn’t find league ${leagueId} in the ${season} season. Check LEAGUE_ID (the digits after leagueId= in your league link) and SEASON (the year the season ends, so 2026-27 is 2027).` };
  }
  if (s === 400) return { status: 400, error: 'ESPN didn’t accept the request. Check that LEAGUE_ID is only digits and SEASON is a year like 2027.' };
  if (s === 429) return { status: 502, error: 'ESPN is limiting requests right now. Wait a few minutes and try again.' };
  if (s >= 500) return { status: 502, error: `ESPN is having problems (HTTP ${s}). Try again in a few minutes.` };
  return { status: 502, error: `ESPN returned an unexpected response (HTTP ${s}).` };
}

function json(body, status = 200, headers = {}) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store', ...headers },
  });
}

/* ---------- Refresh limit ---------- */

// Who is asking: a signed-in team, else the device (its IP address as the host reports it).
async function identityOf(request, env) {
  const team = await teamFromCookie(request, env);
  if (team != null) return `team:${team}`;
  const h = request.headers;
  return `ip:${h.get('cf-connecting-ip') || h.get('x-real-ip') || String(h.get('x-forwarded-for') || '').split(',')[0].trim() || 'unknown'}`;
}

// True if this identity already refreshed this route within `seconds`. The marker lives in the same cache as the
// ESPN responses (shared between the copies of a Worker in one data centre), so the limit holds across requests.
async function refreshLimited(request, env, route, seconds) {
  const cache = globalThis.caches?.default ?? memoryCache;
  const key = new Request(`https://espn-cache.invalid/refresh-limit/${encodeURIComponent(`${await identityOf(request, env)}|${route}`)}`);
  if (await cache.match(key).catch(() => null)) return true;
  await cache.put(key, new Response('1', { headers: { 'cache-control': `public, max-age=${Math.max(1, Math.ceil(seconds))}` } })).catch(() => {});
  return false;
}

/* ---------- Trade block ---------- */

const BOARD_LIMITS = { block: 10, targets: 10, untouchables: 3, positions: 5, note: 140 };
const POSITIONS = ['PG', 'SG', 'SF', 'PF', 'C'];
const boardKey = (leagueId, teamId) => `board:${leagueId}:${teamId}`;

// Who may edit: the signed-in team when PINs are on; on the PC version (nobody else can reach it) any team.
async function boardEditor(request, env, body) {
  if (pinsOf(env).size) return { teamId: await teamFromCookie(request, env), why: 'Sign in with your team PIN to edit your trade block.' };
  if (env.PLATFORM === 'local') {
    const id = Number(body?.teamId);
    return { teamId: Number.isInteger(id) && id > 0 ? id : null, why: 'Say which team this is for.' };
  }
  return { teamId: null, why: 'Turn on team PINs (TEAM_PINS) so each manager can edit only their own trade block.' };
}

async function readBoard(request, env, leagueId) {
  const editor = await boardEditor(request, env, null);
  const base = { enabled: Boolean(env.BOARD), canEdit: Boolean(env.BOARD) && (editor.teamId != null || env.PLATFORM === 'local'), teamId: editor.teamId, limits: BOARD_LIMITS, teams: {} };
  if (!env.BOARD || !leagueId) return json(base);
  const listed = await env.BOARD.list({ prefix: `board:${leagueId}:` });
  await Promise.all((listed.keys || []).map(async ({ name }) => {
    const raw = await env.BOARD.get(name);
    if (raw) base.teams[name.split(':').pop()] = JSON.parse(raw);
  }));
  return json(base);
}

// Whole numbers only, no repeats, capped
const ids = (list, max) => [...new Set((Array.isArray(list) ? list : []).map(Number).filter((n) => Number.isInteger(n) && n > 0))].slice(0, max);

async function saveBoard(request, env, leagueId) {
  if (!env.BOARD) return json({ error: 'The trade block needs somewhere to store its lists, and that is not switched on for this site yet. See the README (Trade block).' }, 503);
  if (!leagueId) return json({ error: 'LEAGUE_ID is not set.' }, 500);
  const text = await request.text();
  if (text.length > 4096) return json({ error: 'That is too much to save.' }, 413);
  let body;
  try {
    body = JSON.parse(text);
  } catch {
    return json({ error: 'That did not look right. Try again.' }, 400);
  }
  const { teamId, why } = await boardEditor(request, env, body);
  if (teamId == null) return json({ error: why }, pinsOf(env).size ? 401 : 403);
  if (await refreshLimited(request, env, 'board-save', 1)) return json({ error: 'Slow down: one save a second.' }, 429);
  const untouchables = ids(body.untouchables, BOARD_LIMITS.untouchables);
  const record = {
    teamId,
    untouchables,
    block: ids(body.block, BOARD_LIMITS.block).filter((id) => !untouchables.includes(id)), // not both
    targets: ids(body.targets, BOARD_LIMITS.targets),
    positions: [...new Set((Array.isArray(body.positions) ? body.positions : []).filter((p) => POSITIONS.includes(p)))].slice(0, BOARD_LIMITS.positions),
    note: String(body.note ?? '').replace(/[\u0000-\u001f\u007f]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, BOARD_LIMITS.note),
    updatedAt: Date.now(),
  };
  await env.BOARD.put(boardKey(leagueId, teamId), JSON.stringify(record));
  return json(record);
}

/* ---------- Team PINs ---------- */

const SESSION_DAYS = 90;
const COOKIE = 'pw_team';
const attempts = new Map(); // teamId -> recent failures (per server instance, so a best-effort limit only)

// TEAM_PINS="1=482913, 2=193846"  ->  Map(1 -> '482913', 2 -> '193846')
function pinsOf(env) {
  const out = new Map();
  for (const part of String(env.TEAM_PINS || '').split(',')) {
    const m = /^\s*(\d+)\s*=\s*(\S+)\s*$/.exec(part);
    if (m) out.set(Number(m[1]), m[2]);
  }
  return out;
}

const hex = (buf) => [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, '0')).join('');
async function hmac(env, text) {
  const key = await crypto.subtle.importKey('raw', new TextEncoder().encode(`pw|${env.SESSION_SECRET || env.TEAM_PINS}`), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  return hex(await crypto.subtle.sign('HMAC', key, new TextEncoder().encode(text)));
}

// Compare without stopping at the first difference
function sameText(a, b) {
  let diff = a.length ^ b.length;
  for (let i = 0; i < Math.max(a.length, b.length); i++) diff |= (a.charCodeAt(i) || 0) ^ (b.charCodeAt(i) || 0);
  return diff === 0;
}

const sessionCookie = (value, seconds, url) => `${COOKIE}=${value}; Path=/; Max-Age=${seconds}; HttpOnly; SameSite=Lax${url.protocol === 'https:' ? '; Secure' : ''}`;

// The team named by a valid, unexpired session cookie (and only while that team still has a PIN), else null.
async function teamFromCookie(request, env) {
  if (!pinsOf(env).size) return null;
  const raw = /(?:^|;\s*)pw_team=([^;]+)/.exec(request.headers.get('cookie') || '')?.[1];
  const [teamId, expires, sig] = String(raw || '').split('.');
  if (!sig || Number(expires) * 1000 < Date.now() || !pinsOf(env).has(Number(teamId))) return null;
  return sameText(sig, await hmac(env, `${teamId}.${expires}`)) ? Number(teamId) : null;
}

async function login(request, env, url) {
  const pins = pinsOf(env);
  if (!pins.size) return json({ error: 'Team PINs are not switched on for this site.' }, 400);
  const body = await request.json().catch(() => null);
  const teamId = Number(body?.teamId);
  const pin = String(body?.pin ?? '').trim();
  const recent = (attempts.get(teamId) || []).filter((t) => Date.now() - t < 10 * 60_000);
  if (recent.length >= 5) return json({ error: 'Too many wrong PINs for that team. Wait ten minutes and try again.' }, 429);
  if (!pins.has(teamId)) return json({ error: 'That team doesn’t have a PIN yet. Ask the league organiser to add one.' }, 403);
  if (!sameText(pin, pins.get(teamId))) {
    attempts.set(teamId, [...recent, Date.now()]);
    await new Promise((r) => setTimeout(r, 400)); // slows down guessing
    return json({ error: 'That PIN isn’t right for that team.' }, 401);
  }
  attempts.delete(teamId);
  const expires = Math.floor(Date.now() / 1000) + SESSION_DAYS * 86400;
  return json({ teamId }, 200, { 'set-cookie': sessionCookie(`${teamId}.${expires}.${await hmac(env, `${teamId}.${expires}`)}`, SESSION_DAYS * 86400, url) });
}

const FILES = {"/account.js":["text/javascript; charset=utf-8","// Who is using the site. With team PINs on, the server remembers the team (signed cookie); without them the\n// choice is just remembered in this browser. Pages ask `team()` and re-render when `onChange` fires.\nexport function createAccount({ data }) {\n  const st = { me: null, pins: false, pending: null, pinError: '' };\n  const listeners = new Set();\n  const league = () => data().ctx.league;\n  const known = (id) => league().teams.some((t) => t.id === id);\n  const key = () => `pw:me:${data().ctx.cfg.leagueId ?? 'site'}`;\n  const changed = () => listeners.forEach((fn) => fn(st.me));\n\n  async function serverMe() {\n    try {\n      const id = (await (await fetch('api/me', { cache: 'no-store' })).json()).teamId;\n      return known(id) ? id : null;\n    } catch {\n      return null;\n    }\n  }\n\n  function localMe() {\n    try {\n      const id = Number(localStorage.getItem(key()));\n      return known(id) ? id : null;\n    } catch {\n      return null;\n    }\n  }\n\n  function setMe(id) {\n    st.me = id;\n    try {\n      if (id == null) localStorage.removeItem(key());\n      else localStorage.setItem(key(), String(id));\n    } catch {}\n    changed();\n  }\n\n  return {\n    state: st,\n    team: () => (st.me == null || !data().ctx ? null : league().teams.find((t) => t.id === st.me) ?? null),\n    onChange: (fn) => listeners.add(fn),\n    // Called after every (re)load of the league\n    async reset(pins) {\n      const before = st.me;\n      st.pins = Boolean(pins);\n      st.me = st.pins ? await serverMe() : localMe();\n      if (st.me !== before) changed();\n    },\n    // A team was chosen: with PINs ask for the PIN first, otherwise sign in straight away\n    choose(id) {\n      if (st.pins) {\n        st.pending = id;\n        st.pinError = '';\n        changed();\n      } else setMe(id);\n    },\n    async signInWithPin(id, pin) {\n      st.pinError = '';\n      try {\n        const res = await fetch('api/login', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ teamId: id, pin }) });\n        const body = await res.json().catch(() => ({}));\n        if (!res.ok) st.pinError = body.error || 'Couldn’t sign in. Try again.';\n        else {\n          st.pending = null;\n          st.me = id;\n        }\n      } catch {\n        st.pinError = 'Couldn’t reach the server. Try again.';\n      }\n      changed();\n    },\n    async signOut() {\n      if (st.pins) await fetch('api/logout', { method: 'POST' }).catch(() => {});\n      st.pending = null;\n      st.pinError = '';\n      setMe(null);\n    },\n  };\n}\n"],"/app.js":["text/javascript; charset=utf-8","// The shell: loads the league, owns shared state, draws the frame and hands each route to a page in pages/.\nimport { buildModel, dayInfo, etDateKey, validTimeZone } from './logic.js';\nimport { loadLeague, loadSeasonDays } from './pipeline.js';\nimport { createAccount } from './account.js';\nimport { createTradeUI } from './trade-ui.js';\nimport { createApiSource, createSnapshotSource, checkSnapshot, fetchScoreboard } from './sources.js';\nimport { PAGES } from './pages/index.js';\nimport { ago, clock, esc, fmt, plural, stamp } from './ui/dom.js';\nimport { link, onRoute, parseHash } from './ui/router.js';\nimport { renderAccount, renderNav, renderSubnav } from './ui/shell.js';\n\nconst HOUR = 3_600_000;\nconst params = new URLSearchParams(location.search);\nconst DEMO = params.has('demo');\nconst FORCE_ROSTER = params.get('source') === 'roster';\nconst DAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];\nconst REFRESH_COOLDOWN = 5000; // the Refresh button works once every 5 seconds (the server enforces the same)\nconst STATIC_POLL = 10 * 60_000;\nconst STALE_AFTER = 3 * HOUR;\nconst BOARD_POLL = 3 * 60_000;\n\nconst $ = (id) => document.getElementById(id);\n\n/* ---------- Shared state: pages read this ---------- */\n\nconst app = {\n  demo: DEMO,\n  model: null,\n  ctx: null,\n  src: null,\n  board: null,\n  check: null,\n  seasonLoaded: false,\n  tz: 'Australia/Melbourne',\n  route: parseHash(),\n  limited: false,\n  refreshAt: null,\n  updated: 0,\n  tried: 0,\n  busy: false,\n  boardDone: () => boardDone(),\n  loadSeason: () => loadSeason(),\n  rerender: () => show(),\n};\nconst data = () => ({ ctx: app.ctx, src: app.src, now: app.src?.now?.(), dayDone: boardDone() });\napp.account = createAccount({ data });\napp.trade = createTradeUI({ data, account: app.account });\napp.account.onChange(() => app.ctx && (renderAccount($('account'), app.account.team()), show()));\n\n/* ---------- Data source ---------- */\n\nasync function apiGet(path, { fresh } = {}) {\n  let res;\n  try {\n    res = await fetch(path, fresh ? { cache: 'no-store' } : undefined);\n    if (res.headers.get('x-refresh-limited')) app.limited = true;\n  } catch {\n    throw new Error('Couldn’t reach the server. Check your connection, or that the local server is still running.');\n  }\n  const body = await res.json().catch(() => null);\n  if (!res.ok) throw new Error(body?.error || `Request failed (${res.status}).`);\n  if (body == null) throw new Error('The server sent something unexpected. Try again.');\n  return body;\n}\n\n// A server with /api (local or Cloudflare) wins; otherwise this is the static GitHub Pages site.\nasync function pickSource({ fresh }) {\n  if (DEMO) return (await import('./demo.js')).createDemo();\n  let hasApi = false;\n  const staticSite = document.querySelector('meta[name=pw-mode]')?.content === 'static';\n  if (!staticSite) {\n    try {\n      const res = await fetch('api/config', { cache: 'no-store' });\n      hasApi = (res.headers.get('content-type') || '').includes('json');\n    } catch {}\n  }\n  if (hasApi) return createApiSource(apiGet);\n\n  let res;\n  try {\n    res = await fetch('data/snapshot.json', { cache: fresh ? 'reload' : 'no-cache' });\n  } catch {\n    throw new Error('Couldn’t reach the server. Check your connection and try again.');\n  }\n  if (res.status === 404) {\n    const err = new Error('No data snapshot has been published yet.');\n    err.setup = 'snapshot';\n    throw err;\n  }\n  const snap = await res.json().catch(() => null);\n  return createSnapshotSource(checkSnapshot(snap));\n}\n\n// Finished days are final after a day, so keep them in the browser for 12 hours.\nconst dayCache = (cfg) => ({\n  key: (sp) => `pw:${cfg.leagueId}:${cfg.season}:${sp}`,\n  get(sp) {\n    if (DEMO || cfg.platform === 'static') return null;\n    try {\n      const hit = JSON.parse(localStorage.getItem(this.key(sp)));\n      if (hit && Date.now() - hit.t < 12 * HOUR) return new Map(hit.d);\n    } catch {}\n    return null;\n  },\n  set(sp, dayMap) {\n    if (DEMO || cfg.platform === 'static') return;\n    try {\n      localStorage.setItem(this.key(sp), JSON.stringify({ t: Date.now(), d: [...dayMap] }));\n    } catch {}\n  },\n});\n\n/* ---------- Load ---------- */\n\nasync function load({ fresh = false } = {}) {\n  if (app.busy) return;\n  app.tried = Date.now();\n  app.limited = false;\n  setBusy(true);\n  try {\n    const src = await pickSource({ fresh });\n    const cfg = await src.config();\n    if (!cfg.configured) return renderSetup(cfg);\n\n    const ctx = await loadLeague(src, { forceRoster: FORCE_ROSTER, fresh, cache: dayCache(cfg) });\n    app.src = src;\n    app.ctx = ctx;\n    app.trade.reset();\n    await app.account.reset(cfg.pins);\n    app.tz = validTimeZone(cfg.timezone) ? cfg.timezone : 'Australia/Melbourne';\n    app.model = buildModel({ ...ctx, now: src.now(), dayDone: boardDone() });\n    app.updated = Date.now();\n    app.check = null;\n    app.seasonLoaded = false;\n    if (src.offline) await loadSeason(); // history is already in the snapshot\n    show();\n    refreshBoard();\n    app.trade.prefetch();\n  } catch (err) {\n    renderError(err);\n  } finally {\n    setBusy(false);\n  }\n}\n\n// Pull every finished day so we can fill the punishments history and compare with ESPN's totals.\nasync function loadSeason() {\n  const { shame, check } = await loadSeasonDays(app.ctx, app.src, { cache: dayCache(app.ctx.cfg) });\n  app.model.shame = shame;\n  app.check = check;\n  app.seasonLoaded = true;\n}\n\n/* ---------- Refresh button ---------- */\n\nfunction setBusy(on) {\n  app.busy = on;\n  updateRefreshButton();\n}\n\n// \"Refresh\", \"Refreshing…\", or \"Refresh in 3s\" while the 5-second limit is running (it survives a page reload)\nlet coolTimer = null;\nfunction updateRefreshButton() {\n  const b = $('refresh');\n  const left = cooldownLeft();\n  b.disabled = app.busy || left > 0;\n  b.textContent = app.busy ? 'Refreshing…' : left > 0 ? `Refresh in ${Math.ceil(left / 1000)}s` : 'Refresh';\n  clearTimeout(coolTimer);\n  if (left > 0) coolTimer = setTimeout(updateRefreshButton, Math.min(left, 250));\n}\n\nfunction cooldownLeft() {\n  let at = app.refreshAt;\n  if (at == null) {\n    try {\n      at = Number(localStorage.getItem('pw:refreshAt')) || 0;\n    } catch {\n      at = 0;\n    }\n    app.refreshAt = at;\n  }\n  return Math.max(0, at + REFRESH_COOLDOWN - Date.now());\n}\n\nfunction startRefresh() {\n  if (app.busy || cooldownLeft() > 0) return;\n  app.refreshAt = Date.now();\n  try {\n    localStorage.setItem('pw:refreshAt', String(app.refreshAt));\n  } catch {}\n  load({ fresh: true });\n}\n\n/* ---------- Render ---------- */\n\nfunction pageFor(route) {\n  return PAGES.find((p) => p.id === route.section) || PAGES[0];\n}\n\nfunction show() {\n  const m = app.model;\n  if (!m) return;\n  const route = app.route;\n  const page = pageFor(route);\n  if (page.id !== route.section) return void (location.hash = link(page.id)); // unknown route -> dashboard\n\n  $('league-name').textContent = m.leagueName;\n  $('week-label').textContent = `Week ${m.week.id}, day ${m.week.dayNumber} of ${m.week.days}. ${m.week.label}`;\n  const snap = app.src.generatedAt;\n  $('updated').textContent = snap\n    ? `Data from ${stamp(snap)} (${ago(snap)}). Checked ${clock(app.updated)}.`\n    : `Updated ${clock(app.updated)}. Next ${clock(app.updated + HOUR)}.${app.limited ? ' You refreshed a moment ago, so this is the latest available right now.' : ''}`;\n  document.title = `${m.loser?.name ?? 'Punishment Watch'} on track for the punishment`;\n\n  const banner = $('banner');\n  const stale = snap && Date.now() - snap > STALE_AFTER;\n  banner.hidden = !DEMO && !stale;\n  if (DEMO) banner.innerHTML = 'Demo data. <a href=\"./\">Open your league</a> once the ESPN cookies are set.';\n  else if (stale) banner.textContent = `This data is ${ago(snap).replace(' ago', '')} old. The hourly GitHub job may be failing: open the repo’s Actions tab to see why.`;\n\n  $('mainnav').hidden = false;\n  renderNav(PAGES, route, $('mainnav'));\n  renderSubnav(page, route, $('subnav'), $('subnav-in'));\n  renderAccount($('account'), app.account.team());\n  document.body.classList.toggle('wide', page.id === 'transactions');\n  if (page.id !== 'transactions') document.body.classList.remove('trading');\n\n  const view = $('view');\n  view.onclick = null;\n  page.render(app, view, route);\n  $('foot').innerHTML = renderFoot(m);\n  if (!show.lastKey || show.lastKey !== route.path) window.scrollTo(0, 0);\n  show.lastKey = route.path;\n}\n\nfunction renderFoot(m) {\n  const how = m.source === 'schedule' ? 'ESPN’s day-by-day team scores' : 'each day’s ESPN lineup and player stats';\n  const weeks = m.weeksSource === 'espn' ? 'Weeks follow ESPN’s matchup periods.' : `Weeks run ${DAYS[m.weekStart]} to ${DAYS[(m.weekStart + 6) % 7]}, US Eastern time.`;\n  const refresh = app.src.kind === 'static' ? 'The data updates about hourly from a GitHub job; Refresh reloads the latest snapshot.' : 'Auto-refreshes hourly.';\n  let check = '<button type=\"button\" class=\"link\" data-action=\"check\">Check against ESPN season totals</button>';\n  if (app.check) {\n    const bad = app.check.filter((c) => !c.ok);\n    check = bad.length\n      ? `<p class=\"warn\">${plural(bad.length, 'team')} don’t match ESPN’s season total: ${bad.map((b) => `${esc(b.name)} (ESPN ${fmt(b.espn)}, rebuilt ${fmt(b.ours)})`).join('; ')}. Try <a href=\"?source=roster\">roster mode</a>.</p>`\n      : `<p class=\"ok\">Every team’s rebuilt total matches ESPN’s season total${app.check.every((c) => c.basis === 'finished days') ? ' (ESPN counts finished days only, so today isn’t in it)' : ''}.</p>`;\n  }\n  return `<p>Weekly points are rebuilt from ${how}, so they start at 0 each week no matter what ESPN’s season total says. Dates are US game days. ${weeks} ${refresh}</p>${check}`;\n}\n\nconst SETUP = {\n  local: `<p>This is the local server. Open the <code>.env</code> file in the project folder (copy <code>.env.example</code> if it isn’t there) and set:</p>\n      <ol>\n        <li><code>LEAGUE_ID</code>: the number after <code>leagueId=</code> in your ESPN league link.</li>\n        <li><code>SEASON</code>: <code>2027</code> for the 2026-27 season.</li>\n        <li><code>ESPN_S2</code> and <code>ESPN_SWID</code>: your ESPN login cookies, unless the league is viewable to the public.</li>\n      </ol>\n      <p>Stop the server, run <code>npm start</code> again, then reload this page.</p>`,\n  cloudflare: `<p>In Cloudflare, open this Worker’s settings, then Variables and Secrets, and add:</p>\n      <ol>\n        <li><code>LEAGUE_ID</code> as text: the number after <code>leagueId=</code> in your ESPN league link.</li>\n        <li><code>SEASON</code> as text: <code>2027</code> for the 2026-27 season.</li>\n        <li><code>ESPN_S2</code> and <code>ESPN_SWID</code> as secrets, unless the league is viewable to the public.</li>\n      </ol>\n      <p>Deploy, then reload this page.</p>`,\n  snapshot: `<p>This site shows a data snapshot that a GitHub Action builds every hour, and the first one hasn’t been published yet. In the repository:</p>\n      <ol>\n        <li>Settings, then Secrets and variables, then Actions: add the secrets <code>ESPN_S2</code> and <code>ESPN_SWID</code> and the variables <code>LEAGUE_ID</code> and <code>SEASON</code>.</li>\n        <li>Settings, then Pages: set Source to <b>GitHub Actions</b>.</li>\n        <li>Actions tab, then <b>Build and deploy</b>, then <b>Run workflow</b>.</li>\n      </ol>\n      <p>Reload this page when the run finishes.</p>`,\n};\n\nfunction hideChrome() {\n  $('mainnav').hidden = true;\n  $('subnav').hidden = true;\n  $('account').hidden = true;\n}\n\nfunction renderSetup(cfg, kind = cfg?.platform === 'local' ? 'local' : 'cloudflare') {\n  hideChrome();\n  $('view').innerHTML = `<div class=\"setup\">\n      <h2>${kind === 'snapshot' ? 'Waiting for the first data snapshot' : 'Connect your ESPN league'}</h2>\n      ${SETUP[kind]}\n      <p><a href=\"?demo\">Preview with demo data</a></p>\n    </div>`;\n}\n\nfunction renderError(err) {\n  if (err.setup) return renderSetup(null, err.setup);\n  if (app.model) hideChrome();\n  $('view').innerHTML = `<div class=\"error\" role=\"alert\">\n      <h2>Couldn’t load the league</h2>\n      <p>${esc(err.message)}</p>\n      <button type=\"button\" class=\"btn primary\" data-action=\"retry\">Try again</button>\n    </div>`;\n}\n\n/* ---------- Game-day scoreboard ---------- */\n\n// True/false once the live scoreboard covers today's slate, otherwise undefined (the clock decides).\n// A snapshot's numbers can be older than the scoreboard, so the snapshot keeps using the clock.\nfunction boardDone() {\n  if (!app.ctx || app.src?.kind === 'static') return undefined;\n  const info = dayInfo(app.ctx.pro, app.ctx.league.currentSP, Date.now(), app.board);\n  return info && !info.estimated ? info.state === 'done' : undefined;\n}\n\n// Ask ESPN's scoreboard how today's games are going. Quietly skipped if it can't be reached.\nasync function refreshBoard() {\n  if (DEMO || !app.ctx) return;\n  const { league, pro } = app.ctx;\n  const info = dayInfo(pro, league.currentSP, Date.now());\n  const key = etDateKey(pro, league.currentSP);\n  if (!info || !key || info.firstTip - Date.now() > 3 * HOUR) return; // nothing to watch yet\n  const before = boardDone();\n  // Through our own server when there is one (no browser restrictions), otherwise straight from ESPN\n  const viaServer = app.src?.kind === 'api' ? await fetchScoreboard(league.currentSP, key, () => fetch(`api/scoreboard?date=${key}`)) : null;\n  const board = viaServer || (await fetchScoreboard(league.currentSP, key));\n  if (!board) return;\n  app.board = board;\n  if (pageFor(app.route).id === 'dashboard') show();\n  // The day just finished: reload so the recap and standings use the final numbers\n  if (boardDone() === true && before !== true && app.src?.kind !== 'static') load({ fresh: true });\n}\n\n/* ---------- Events ---------- */\n\ndocument.addEventListener('click', async (e) => {\n  const action = e.target.closest('[data-action]')?.dataset.action;\n  if (!action) return;\n  if (action === 'retry') return load({ fresh: true });\n  const btn = e.target.closest('button');\n  btn.disabled = true;\n  btn.textContent = 'Loading…';\n  try {\n    await loadSeason();\n    show();\n  } catch (err) {\n    btn.textContent = `Couldn’t load: ${err.message}`;\n  }\n});\n\n$('account').addEventListener('click', () => (location.hash = link('transactions', 'trade')));\n\n// A snapshot site checks for a new file every few minutes; a live site refreshes hourly.\nconst interval = () => (app.src?.kind === 'static' ? STATIC_POLL : HOUR);\n$('refresh').addEventListener('click', startRefresh);\nupdateRefreshButton();\nsetInterval(() => app.ctx && pageFor(app.route).id === 'dashboard' && show(), 60_000);\nsetInterval(refreshBoard, BOARD_POLL);\nsetInterval(() => {\n  if (Date.now() - app.tried >= interval() - 1000) load();\n}, 60_000);\ndocument.addEventListener('visibilitychange', () => {\n  if (document.visibilityState === 'visible' && app.tried && Date.now() - app.tried > interval()) load();\n});\n\nonRoute((route) => {\n  app.route = route;\n  show();\n});\nload();\n"],"/css/base.css":["text/css; charset=utf-8","*, *::before, *::after { box-sizing: border-box; }\nhtml { color-scheme: dark; }\nbody {\n  margin: 0;\n  background: radial-gradient(1200px 500px at 70% -10%, #1a1f27 0%, transparent 60%), var(--bg);\n  color: var(--text);\n  font: 400 13px/1.45 var(--font-body);\n  -webkit-font-smoothing: antialiased;\n  min-height: 100vh;\n}\na { color: inherit; text-decoration: none; }\na:hover { color: var(--accent); }\nbutton { font: inherit; color: inherit; }\nh1, h2, h3, h4, p { margin: 0; }\n:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }\n::selection { background: var(--accent); color: var(--on-accent); }\n.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }\n[hidden] { display: none !important; }\n.num { font-variant-numeric: tabular-nums; }\n.muted { color: var(--muted); }\n.dim { color: var(--text-2); }\n.pos-text { color: var(--pos); }\n.neg-text { color: var(--neg); }\n.accent-text { color: var(--accent); }\n/* thin scrollbars to match the dense look */\n* { scrollbar-width: thin; scrollbar-color: #3a424e transparent; }\n::-webkit-scrollbar { width: 8px; height: 8px; }\n::-webkit-scrollbar-thumb { background: #3a424e; }\n@media (prefers-reduced-motion: reduce) { * { transition: none !important; animation: none !important; } }\n"],"/css/components.css":["text/css; charset=utf-8","/* Reusable components: buttons, panels, tables, badges, bars, forms, slots. Pages only combine these. */\n\n/* ---- buttons ---- */\n.btn, .action {\n  display: inline-flex; align-items: center; justify-content: center; gap: 6px;\n  min-height: 30px; padding: 0 14px;\n  background: transparent; color: var(--text);\n  border: 1px solid var(--line); border-radius: var(--radius);\n  font: 600 12px/1 var(--font-body); letter-spacing: 0.04em; text-transform: uppercase;\n  cursor: pointer; transition: background var(--ease), border-color var(--ease), color var(--ease);\n  white-space: nowrap;\n}\n.btn:hover, .action:hover { border-color: var(--accent); color: var(--accent); }\n.btn.primary { background: var(--accent); color: var(--on-accent); border-color: var(--accent); }\n.btn.primary:hover { background: var(--accent-2); border-color: var(--accent-2); color: var(--on-accent); }\n.btn.ghost, .action.ghost { border-color: transparent; }\n.btn.ghost:hover, .action.ghost:hover { border-color: var(--line); }\n.btn.on, .action.on { border-color: var(--accent); color: var(--accent); }\n.btn:disabled, .action:disabled { opacity: 0.4; cursor: not-allowed; border-color: var(--line); color: var(--text-2); }\n.btn.sm { min-height: 24px; padding: 0 9px; font-size: 11px; }\n.link { background: none; border: 0; padding: 0; color: var(--accent); cursor: pointer; font: inherit; font-weight: 600; text-decoration: underline; text-underline-offset: 3px; }\n.link:hover { color: var(--accent-2); }\n\n/* ---- panels ---- */\n.panel { background: var(--bg-2); border: 1px solid var(--line); border-radius: var(--radius); min-width: 0; }\n.panel-h { display: flex; align-items: center; justify-content: space-between; gap: var(--s3); padding: 0 var(--s4); min-height: 38px; border-bottom: 1px solid var(--line); background: linear-gradient(#1c212a, #181c23); }\n.panel-h h2, .panel-h h3 { font: 700 15px/1 var(--font-head); letter-spacing: 0.08em; text-transform: uppercase; color: var(--text); display: flex; align-items: center; gap: 8px; }\n.panel-h h2::before { content: ''; width: 3px; height: 14px; background: var(--accent); }\n.panel-tools { display: flex; align-items: center; gap: var(--s2); flex-wrap: wrap; }\n.panel-b { padding: var(--s4); }\n.panel.flush .panel-b { padding: 0; }\n.panel.elev { background: var(--panel); }\n.lede { color: var(--text-2); margin: 0 0 var(--s3); max-width: 70ch; }\n.empty { color: var(--text-2); padding: var(--s4); max-width: 60ch; }\n.note { color: var(--text-2); font-size: 12px; }\n.warn { color: var(--neg); font-weight: 600; }\n.ok { color: var(--pos); font-weight: 600; }\n.est { color: var(--muted); }\n\n/* ---- tables (the one dense table style) ---- */\n.tbl-wrap { overflow: auto; max-width: 100%; }\n.tbl { width: 100%; border-collapse: separate; border-spacing: 0; background: var(--table); font-variant-numeric: tabular-nums; font-size: 13px; }\n.tbl th, .tbl td { padding: 0 10px; height: 34px; text-align: left; border-bottom: 1px solid var(--line-soft); white-space: nowrap; }\n.tbl thead th { position: sticky; top: 0; z-index: 2; background: var(--table-head); color: var(--muted); font: 600 11px/1 var(--font-body); letter-spacing: 0.08em; text-transform: uppercase; height: 30px; border-bottom: 1px solid var(--line); }\n.tbl th.num, .tbl td.num { text-align: right; }\n.tbl tbody th { font-weight: 600; color: var(--text); }\n.tbl tbody tr:hover { background: var(--table-row-hover); }\n.tbl tbody tr[data-href], .tbl tbody tr[data-row] { cursor: pointer; }\n.tbl tbody tr.sel { background: var(--accent); color: var(--on-accent); }\n.tbl tbody tr.sel td, .tbl tbody tr.sel th, .tbl tbody tr.sel a { color: var(--on-accent); }\n.tbl tbody tr.last, .tbl tr.last { background: rgba(217, 98, 90, 0.12); box-shadow: inset 3px 0 0 var(--neg); }\n.tbl tbody tr.me { box-shadow: inset 3px 0 0 var(--accent); }\n.tbl.sortable thead th[data-sort] { cursor: pointer; user-select: none; }\n.tbl.sortable thead th[data-sort]:hover { color: var(--text); }\n.tbl.sortable thead th[aria-sort] { color: var(--accent); }\n.tbl.sortable thead th[aria-sort='ascending']::after { content: ' ▲'; font-size: 8px; }\n.tbl.sortable thead th[aria-sort='descending']::after { content: ' ▼'; font-size: 8px; }\n.tbl.sticky-first th:first-child, .tbl.sticky-first td:first-child { position: sticky; left: 0; background: inherit; z-index: 1; }\n.strong { font-weight: 700; }\ntr.last th { color: var(--neg); }\n\n/* ---- badges, chips, movement ---- */\n.badge { display: inline-block; padding: 2px 6px; border: 1px solid var(--line); border-radius: var(--radius); color: var(--text-2); font: 600 10px/1.2 var(--font-body); letter-spacing: 0.06em; text-transform: uppercase; vertical-align: middle; }\n.badge.accent { border-color: var(--accent); color: var(--accent); }\n.badge.bad, .inj { border-color: rgba(217, 98, 90, 0.6); color: var(--neg); }\n.badge.good { border-color: rgba(82, 183, 136, 0.6); color: var(--pos); }\n.badge.warn { border-color: rgba(217, 164, 65, 0.6); color: var(--warn); }\n.inj { display: inline-block; padding: 1px 5px; border: 1px solid; border-radius: var(--radius); font: 700 10px/1.3 var(--font-body); letter-spacing: 0.06em; text-transform: uppercase; }\n.chip { display: inline-block; font: 700 10px/1 var(--font-body); letter-spacing: 0.08em; text-transform: uppercase; padding: 4px 7px; border-radius: var(--radius); border: 1px solid var(--line); color: var(--text-2); margin-right: 4px; }\n.chip.live { background: var(--neg); border-color: var(--neg); color: #fff; }\n.chip.done { border-color: var(--pos); color: var(--pos); }\n.chip.soon { border-color: var(--accent); color: var(--accent); }\n.youtag { display: inline-block; padding: 2px 6px; background: var(--accent); color: var(--on-accent); font: 700 10px/1.2 var(--font-body); letter-spacing: 0.08em; text-transform: uppercase; }\n.lastchip { margin-left: 6px; padding: 1px 5px; background: var(--neg); color: #fff; font: 700 10px/1.3 var(--font-body); letter-spacing: 0.06em; text-transform: uppercase; }\n.move { font-size: 11px; font-weight: 700; margin-left: 6px; }\n.move.up, .up { color: var(--pos); }\n.move.down, .down { color: var(--neg); }\n.move.flat, .flat { color: var(--muted); }\n.pos-text, b.pos { color: var(--pos); }\n.neg-text, b.neg { color: var(--neg); }\n\n/* ---- bars ---- */\n.meter { height: 6px; background: #2a313b; border-radius: 1px; overflow: hidden; }\n.meter > span { display: block; height: 100%; background: var(--accent); }\n.meter.bad > span { background: var(--neg); }\n.meter.good > span { background: var(--pos); }\n\n/* ---- stars ---- */\n.stars { letter-spacing: 0.06em; font-size: 18px; vertical-align: middle; }\n.star { color: #333a45; }\n.star.on { color: var(--accent); }\n.star.half { background: linear-gradient(90deg, var(--accent) 50%, #333a45 50%); -webkit-background-clip: text; background-clip: text; color: transparent; }\n\n/* ---- forms ---- */\ninput[type='text'], input[type='search'], input[type='password'], input[type='number'], select, textarea {\n  background: var(--table); color: var(--text); border: 1px solid var(--line); border-radius: var(--radius);\n  font: 500 13px/1.2 var(--font-body); min-height: 30px; padding: 0 10px;\n}\ntextarea { padding: 8px 10px; min-height: 60px; resize: vertical; }\nselect { padding-right: 4px; }\ninput::placeholder { color: var(--muted); }\ninput:focus, select:focus, textarea:focus { border-color: var(--accent); outline: none; }\ninput[type='checkbox'], input[type='radio'] { accent-color: var(--accent); }\nlabel.field { display: grid; gap: 4px; font: 600 10px/1 var(--font-body); letter-spacing: 0.08em; text-transform: uppercase; color: var(--muted); }\nlabel.field > :not(span) { text-transform: none; letter-spacing: normal; }\n\n/* ---- segmented control / filter chips ---- */\n.seg { display: inline-flex; border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden; }\n.seg button { background: transparent; border: 0; color: var(--text-2); font: 600 11px/1 var(--font-body); letter-spacing: 0.06em; text-transform: uppercase; padding: 9px 12px; cursor: pointer; }\n.seg button + button { border-left: 1px solid var(--line); }\n.seg button:hover { color: var(--text); }\n.seg button[aria-pressed='true'] { background: var(--accent); color: var(--on-accent); }\n\n/* ---- stat tile ---- */\n.stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(110px, 1fr)); gap: 1px; background: var(--line); border: 1px solid var(--line); }\n.stat { background: var(--bg-2); padding: 10px 12px; min-width: 0; }\n.stat span { display: block; font: 600 10px/1 var(--font-body); letter-spacing: 0.08em; text-transform: uppercase; color: var(--muted); }\n.stat b { display: block; margin-top: 6px; font: 700 26px/1 var(--font-head); letter-spacing: 0.02em; font-variant-numeric: tabular-nums; }\n.stat small { display: block; margin-top: 4px; color: var(--text-2); font-size: 11px; }\n.stat.accent b { color: var(--accent); }\n\n/* ---- headshots and logos ---- */\n.shot { width: 36px; height: 26px; object-fit: cover; object-position: top; background: #262c36; border-radius: 1px; flex: 0 0 auto; }\n.logo { width: 20px; height: 20px; object-fit: contain; flex: 0 0 auto; }\n\n/* ---- 2K style slots ---- */\n.slot { display: grid; place-items: center; min-height: 64px; border: 1px dashed #454d5a; background: rgba(255, 255, 255, 0.02); color: var(--muted); font: 700 12px/1 var(--font-head); letter-spacing: 0.1em; text-transform: uppercase; cursor: pointer; }\n.slot:hover { border-color: var(--accent); color: var(--accent); }\n.slot.filled { display: flex; place-items: initial; align-items: center; gap: 10px; border-style: solid; border-color: var(--line); background: var(--panel); color: var(--text); text-align: left; padding: 6px 10px; letter-spacing: normal; text-transform: none; cursor: default; }\n\n/* ---- sign in ---- */\n.picks { display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 8px; margin-top: 12px; }\n.team-pick { display: flex; justify-content: space-between; gap: 12px; align-items: baseline; text-align: left; padding: 10px 12px; border: 1px solid var(--line); border-radius: var(--radius); background: var(--table); color: var(--text); cursor: pointer; font: inherit; }\n.team-pick:hover, .team-pick.picked { border-color: var(--accent); }\n.team-pick.picked { background: var(--accent); color: var(--on-accent); }\n.team-pick span { color: var(--text-2); font-size: 12px; }\n.team-pick.picked span { color: var(--on-accent); }\n.pin { display: grid; gap: 8px; max-width: 320px; margin-top: 16px; padding: 12px; border: 1px solid var(--line); background: var(--panel); }\n.pin input { font-size: 22px; letter-spacing: 0.3em; min-height: 40px; }\n.pin .warn { margin: 0; }\n\n.panel.flush .lede { padding: 12px 16px 4px; margin: 0; }\n@media (max-width: 760px) { .hide-sm { display: none; } }\n"],"/css/pages.css":["text/css; charset=utf-8","/* Page-specific layout. Dashboard, week board, recap, league, trade workspace. */\n\n/* ---- dashboard hero ---- */\n.hero { display: grid; grid-template-columns: minmax(0, 1.3fr) minmax(0, 1fr); gap: 1px; background: var(--line); border: 1px solid var(--line); }\n.hero > div { background: var(--bg-2); padding: 18px 20px; min-width: 0; }\n.hero .kicker { font: 600 11px/1 var(--font-body); letter-spacing: 0.12em; text-transform: uppercase; color: var(--accent); }\n.hero h2 { font: 800 clamp(34px, 5vw, 56px)/0.95 var(--font-head); letter-spacing: 0.02em; text-transform: uppercase; margin: 10px 0 4px; overflow-wrap: anywhere; }\n.hero .owner { color: var(--text-2); }\n.hero .line { margin-top: 10px; color: var(--text-2); max-width: 60ch; }\n.final-banner { padding: 10px 14px; background: var(--panel); border-left: 3px solid var(--accent); font-weight: 600; }\n\n.gauges { display: grid; gap: 16px; align-content: start; }\n.gauge-h { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; }\n.gauge-h span { font: 600 11px/1 var(--font-body); letter-spacing: 0.1em; text-transform: uppercase; color: var(--muted); }\n.gauge-h b { font: 800 34px/1 var(--font-head); letter-spacing: 0.02em; font-variant-numeric: tabular-nums; }\n.gauge-h b small { font: 600 11px/1 var(--font-body); color: var(--text-2); margin-left: 6px; letter-spacing: 0.06em; text-transform: uppercase; }\n.segbar { display: grid; grid-template-columns: repeat(10, 1fr); gap: 3px; margin: 8px 0 6px; }\n.segbar i { height: 10px; background: #2a313b; }\n.segbar i.on { background: var(--accent); }\n.segbar.heat i.on:nth-child(n+4) { background: var(--warn); }\n.segbar.heat i.on:nth-child(n+7) { background: var(--neg); }\n.gauge .why { font-size: 12px; color: var(--text-2); }\n.gauge details summary { cursor: pointer; color: var(--muted); font-size: 11px; }\n.gauge details p { margin-top: 6px; font-size: 12px; color: var(--text-2); }\n\n/* ---- game day ---- */\n.gameday-b p { margin: 2px 0; }\n.gameday-b .times { color: var(--text-2); }\n.gameday-b p + p:not(.times) { margin-top: 10px; padding-top: 10px; border-top: 1px dashed var(--line); }\n\n/* ---- week board (dense table with a bar) ---- */\n.board-bar { display: block; width: 100%; min-width: 90px; }\n.risk-hot { color: var(--neg); font-weight: 700; }\n.who-cell b { display: block; font-weight: 600; }\n.who-cell small { color: var(--muted); font-size: 11px; }\n.tbl tr.sel .who-cell small, .tbl tr.sel .muted { color: var(--on-accent); opacity: 0.75; }\n\n/* ---- recap ---- */\n.movers { margin: 0 0 12px; padding-left: 18px; max-width: 70ch; }\n.movers li { margin: 4px 0; }\n.movers li::marker { color: var(--accent); }\n.duo { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 12px; margin-top: 12px; }\n.duo p { padding: 10px 12px; background: var(--panel); border-left: 3px solid var(--accent); }\n.duo .tag { display: block; color: var(--muted); font: 600 10px/1 var(--font-body); letter-spacing: 0.1em; text-transform: uppercase; margin-bottom: 4px; }\n.duo b { font: 700 18px/1.1 var(--font-head); letter-spacing: 0.03em; }\n\n/* ---- punishments ---- */\n.tally { list-style: none; padding: 0; margin: 0; display: grid; grid-template-columns: repeat(auto-fill, minmax(210px, 1fr)); gap: 8px; }\n.tally li { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; padding: 8px 12px; background: var(--panel); border-left: 3px solid var(--neg); }\n.tally span { font: 800 24px/1 var(--font-head); color: var(--neg); }\n.shame { list-style: none; padding: 0; margin: 0; }\n.shame li { padding: 12px 0; border-bottom: 1px solid var(--line-soft); }\n.wk { font: 600 11px/1 var(--font-body); letter-spacing: 0.1em; text-transform: uppercase; color: var(--muted); display: flex; gap: 12px; flex-wrap: wrap; }\n.who-lost { font: 800 26px/1.05 var(--font-head); letter-spacing: 0.02em; text-transform: uppercase; color: var(--neg); margin: 4px 0; }\n\n/* ---- setup and errors ---- */\n.setup, .error { max-width: 640px; margin: 24px auto; padding: 20px; border: 1px solid var(--line); background: var(--bg-2); }\n.setup h2, .error h2 { font: 800 30px/1 var(--font-head); text-transform: uppercase; letter-spacing: 0.04em; margin-bottom: 12px; }\n.setup ol { padding-left: 20px; }\n.setup li { margin: 6px 0; }\n.setup p + ol, .setup ol + p, .error p + button { margin-top: 12px; }\ncode { font-size: 0.9em; background: #262c36; padding: 1px 5px; overflow-wrap: anywhere; }\n\n/* ---- trade workspace (the existing builder, restyled) ---- */\nbody.trading .topbar, body.trading .subnav, body.trading .foot { display: none; }\nbody.trading .frame { padding-top: 8px; }\n.fit { height: var(--fit, 80vh); min-height: 340px; display: flex; flex-direction: column; gap: 8px; }\n.who { margin: 0; font-size: 12px; color: var(--text-2); flex: 0 0 auto; }\n.split { flex: 1; min-height: 0; display: grid; grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr); gap: 12px; }\n.col, .tcol { min-width: 0; min-height: 0; display: flex; flex-direction: column; padding: 8px 10px; border: 1px solid var(--line); background: var(--bg-2); }\n.col h3, .tcol h3 { flex: 0 0 auto; font: 700 15px/1 var(--font-head); letter-spacing: 0.08em; text-transform: uppercase; margin: 0 0 6px; display: flex; flex-wrap: wrap; gap: 8px; align-items: center; }\n.tcol h3 select { max-width: 100%; }\n.tcol.mine, .col.mine { border-color: var(--accent); }\n.cols { flex: 1; min-height: 0; display: grid; grid-template-columns: repeat(var(--n), minmax(0, 1fr)); gap: 12px; }\n.rfit { list-style: none; margin: 0; padding: 0; flex: 1; min-height: 0; display: flex; flex-direction: column; font-size: clamp(11px, 2vh, 14px); }\n.rfit > li { flex: 1 1 0; min-height: 0; display: flex; flex-direction: column; justify-content: center; }\n.rfit > li.grp { flex: 0 0 auto; font: 700 0.8em/1 var(--font-head); text-transform: uppercase; letter-spacing: 0.12em; color: var(--muted); padding: 4px 4px 2px; }\n.rfit > li.prow.picked { flex: 0 0 auto; }\n.pl { display: flex; align-items: center; gap: 8px; margin: 1px 0; padding: 0 8px; min-height: 1.5em; border: 1px solid transparent; background: var(--table); cursor: pointer; }\n.pl:hover { background: var(--table-row-hover); }\n.pl.static { cursor: default; }\n.prow.picked .pl { background: var(--accent); color: var(--on-accent); }\n.prow.picked .pl .pv small { color: var(--on-accent); }\n.pl input { flex: 0 0 auto; width: 1.05em; height: 1.05em; margin: 0; }\n.pn { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-weight: 600; }\n.pv { flex: 0 0 auto; font-weight: 700; font-variant-numeric: tabular-nums; }\n.pv small.pct { font-weight: 500; color: var(--muted); font-size: 0.8em; }\n.dest { display: flex; align-items: center; gap: 4px; padding: 0 8px 2px 24px; font-size: 0.85em; color: var(--text-2); }\n.dest select { flex: 1; min-width: 0; min-height: 22px; }\n.cards { flex: 1; min-height: 0; display: grid; grid-template-rows: repeat(var(--rows, 5), minmax(0, 1fr)); gap: 6px; }\n.team-card { display: flex; flex-direction: column; justify-content: center; gap: 1px; min-height: 0; overflow: hidden; text-align: left; font: inherit; padding: 4px 12px; border: 1px solid var(--line); background: var(--table); color: var(--text); cursor: pointer; }\n.team-card:hover, .team-card:focus-visible { border-color: var(--accent); }\n.team-card b { font-size: clamp(12px, 2.2vh, 15px); }\n.team-card span, .team-card small { color: var(--text-2); font-size: clamp(10px, 1.7vh, 12px); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n.tbar { flex: 0 0 auto; padding: 8px 10px; border: 1px solid var(--accent); background: var(--panel); }\n.topline { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }\nselect.multi { max-width: 180px; }\n.vline { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 12px; margin-top: 6px; font-size: 13px; }\n.vline .hint { color: var(--text-2); }\n.vline .stars { font-size: 17px; }\n.vlabel { font-weight: 700; }\n.vgain small { color: var(--muted); }\n.vline .link.why { font-size: 11px; }\n.simline { margin-top: 6px; padding-top: 6px; border-top: 1px dashed var(--line); font-size: 13px; font-weight: 600; }\n.sheet { position: fixed; z-index: 60; left: 8px; right: 8px; top: var(--bar-bottom, 120px); max-height: calc(100dvh - var(--bar-bottom, 120px) - 10px); overflow: auto; border: 1px solid var(--accent); background: var(--bg-2); box-shadow: 0 16px 40px rgba(0, 0, 0, 0.6); }\n@media (min-width: 900px) { .sheet { left: 50%; right: auto; width: min(760px, calc(100vw - 16px)); transform: translateX(-50%); } }\n.closer { position: sticky; top: 0; float: right; margin: 6px 8px 0 0; z-index: 1; font: 700 11px/1 var(--font-body); padding: 6px 10px; border: 1px solid var(--line); background: var(--panel); color: var(--text); cursor: pointer; text-transform: uppercase; }\n.closer:hover { border-color: var(--accent); }\n.verdict { padding: 14px 16px; }\n.verdict h3 { font: 800 26px/1 var(--font-head); text-transform: uppercase; letter-spacing: 0.03em; margin: 0 0 6px; }\n.verdict h4 { font: 700 15px/1 var(--font-head); letter-spacing: 0.08em; text-transform: uppercase; color: var(--accent); margin: 16px 0 4px; }\n.verdict p { margin: 6px 0; }\n.verdict .headline { font-weight: 600; }\n.verdict summary { cursor: pointer; font-weight: 600; margin-top: 8px; color: var(--text-2); }\n.verdict .why p { font-size: 13px; color: var(--text-2); }\n.verdict .scroll { overflow-x: auto; }\n.verdict .split-gain { margin: 8px 0; padding: 6px 10px; border-left: 3px solid var(--accent); background: var(--panel); font-size: 13px; }\n.verdict .split-gain p { margin: 2px 0; }\n.gains { display: grid; gap: 2px; margin: 8px 0; }\n.gains p { margin: 0; display: flex; gap: 8px; align-items: baseline; }\n.gains span { min-width: 120px; color: var(--text-2); }\n.gains b { font-size: 18px; }\n.actions { margin: 8px 0 4px; }\ntable.odds { width: 100%; border-collapse: collapse; font-size: 13px; }\ntable.odds th, table.odds td { padding: 5px 8px; border-bottom: 1px solid var(--line-soft); text-align: left; }\ntable.odds th[scope='col'] { font: 600 10px/1.2 var(--font-body); text-transform: uppercase; letter-spacing: 0.08em; color: var(--muted); }\ntable.odds .num { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }\ntable.odds .strong { font-weight: 800; }\ntable.odds .dim { color: var(--muted); font-size: 0.85em; }\ntable.odds tr.last { background: rgba(217, 98, 90, 0.12); }\ntable.whytable th small, table.whytable td small { display: block; font-weight: 500; color: var(--muted); font-size: 11px; }\ntable.whytable th[scope='col'] { white-space: normal; max-width: 112px; }\n@media (max-width: 720px) {\n  .split { grid-template-columns: minmax(0, 1fr); }\n  .inj .when { display: none; }\n  .cols.many { grid-template-columns: none; grid-auto-flow: column; grid-auto-columns: minmax(240px, 82%); overflow-x: auto; scroll-snap-type: x proximity; }\n  .cols.many .tcol { scroll-snap-align: start; }\n  .pv small.pct { display: none; }\n  table.odds .dim { display: none; }\n  .hero { grid-template-columns: minmax(0, 1fr); }\n}\n"],"/css/shell.css":["text/css; charset=utf-8","/* App shell: top bar, primary navigation, contextual tabs, page frame, footer. */\n.topbar { position: sticky; top: 0; z-index: 40; background: rgba(16, 18, 22, 0.96); backdrop-filter: blur(6px); border-bottom: 1px solid var(--line); }\n.topbar-in { max-width: 1480px; margin: 0 auto; padding: 0 16px; height: var(--top-h); display: flex; align-items: center; gap: 16px; }\n.brand { display: flex; align-items: center; gap: 10px; min-width: 0; }\n.mark { width: 28px; height: 28px; display: grid; place-items: center; background: var(--accent); color: var(--on-accent); font: 800 15px/1 var(--font-head); letter-spacing: 0.02em; flex: 0 0 auto; }\n.brand h1 { font: 700 20px/1 var(--font-head); letter-spacing: 0.06em; text-transform: uppercase; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n.brand .sub { display: block; margin-top: 3px; font: 500 11px/1 var(--font-body); color: var(--text-2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n.top-tools { margin-left: auto; display: flex; align-items: center; gap: 10px; }\n.updated { color: var(--muted); font-size: 11px; text-align: right; line-height: 1.3; max-width: 260px; }\n.acct { display: inline-flex; align-items: center; gap: 8px; min-height: 30px; padding: 0 10px; border: 1px solid var(--line); background: var(--bg-2); color: var(--text); font: 600 12px/1 var(--font-body); cursor: pointer; max-width: 220px; }\n.acct:hover { border-color: var(--accent); color: var(--text); }\n.acct b { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-weight: 600; }\n.acct i { font-style: normal; color: var(--muted); font-size: 10px; letter-spacing: 0.08em; text-transform: uppercase; }\n\n.mainnav { max-width: 1480px; margin: 0 auto; padding: 0 16px; height: var(--nav-h); display: flex; gap: 2px; overflow-x: auto; scrollbar-width: none; }\n.mainnav::-webkit-scrollbar { display: none; }\n.mainnav a { display: flex; align-items: center; padding: 0 16px; font: 600 16px/1 var(--font-head); letter-spacing: 0.1em; text-transform: uppercase; color: var(--text-2); border-bottom: 3px solid transparent; white-space: nowrap; }\n.mainnav a:hover { color: var(--text); }\n.mainnav a[aria-current='page'] { color: var(--accent); border-bottom-color: var(--accent); }\n\n.subnav { background: var(--bg-2); border-bottom: 1px solid var(--line); }\n.subnav-in { max-width: 1480px; margin: 0 auto; padding: 0 16px; display: flex; gap: 4px; overflow-x: auto; scrollbar-width: none; min-height: 38px; align-items: stretch; }\n.subnav a { display: flex; align-items: center; padding: 0 12px; font: 600 11px/1 var(--font-body); letter-spacing: 0.08em; text-transform: uppercase; color: var(--text-2); border-bottom: 2px solid transparent; white-space: nowrap; }\n.subnav a:hover { color: var(--text); }\n.subnav a[aria-current='page'] { color: var(--text); border-bottom-color: var(--accent); }\n\n.banner { max-width: 1480px; margin: 12px auto 0; padding: 8px 12px; background: var(--panel); border-left: 3px solid var(--warn); color: var(--text); font-weight: 600; }\n.frame { max-width: 1480px; margin: 0 auto; padding: 16px; display: grid; gap: 16px; }\n.frame.wide { max-width: none; }\n.grid { display: grid; gap: 16px; }\n.grid.cols-2 { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n.grid.cols-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }\n.grid.main-side { grid-template-columns: minmax(0, 1fr) 340px; align-items: start; }\n.grid.side-main { grid-template-columns: 340px minmax(0, 1fr); align-items: start; }\n.foot { max-width: 1480px; margin: 8px auto 0; padding: 16px 16px 40px; color: var(--muted); font-size: 12px; border-top: 1px solid var(--line-soft); }\n.foot p + * { margin-top: 8px; }\n.foot .ok { color: var(--pos); }\n.loading { padding: 48px 16px; text-align: center; color: var(--text-2); font: 600 14px/1 var(--font-head); letter-spacing: 0.12em; text-transform: uppercase; }\n\n@media (max-width: 1100px) {\n  .grid.main-side, .grid.side-main, .grid.cols-3 { grid-template-columns: minmax(0, 1fr); }\n  .grid.cols-3.keep { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n}\n@media (max-width: 760px) {\n  .updated { display: none; }\n  .grid.cols-2, .grid.cols-3.keep { grid-template-columns: minmax(0, 1fr); }\n  .topbar-in { gap: 10px; padding: 0 12px; }\n  .brand .sub { display: none; }\n  .frame { padding: 12px; gap: 12px; }\n  .mainnav a { padding: 0 12px; font-size: 15px; }\n  .acct i { display: none; }\n}\n"],"/css/tokens.css":["text/css; charset=utf-8","/* Design tokens. One place for colour, type, spacing, so every page looks like the same product. */\n:root {\n  /* surfaces */\n  --bg: #101216;\n  --bg-2: #181c23;\n  --panel: #202630;\n  --table: #171b22;\n  --table-head: #12151b;\n  --table-row-hover: #1d232c;\n  /* accent: selection, active navigation, key numbers, progress, primary actions, focus */\n  --accent: #e8f02a;\n  --accent-2: #c8d51e;\n  --on-accent: #101216;\n  /* text */\n  --text: #f5f6f7;\n  --text-2: #a0a7b2;\n  --muted: #69717d;\n  /* lines */\n  --line: #303741;\n  --line-soft: #20262f;\n  /* signals (restrained) */\n  --pos: #52b788;\n  --neg: #d9625a;\n  --warn: #d9a441;\n  /* type */\n  --font-head: 'Barlow Condensed', 'Roboto Condensed', 'Arial Narrow', 'Helvetica Neue', Arial, sans-serif;\n  --font-body: 'Inter', 'IBM Plex Sans', system-ui, -apple-system, 'Segoe UI', Roboto, Arial, sans-serif;\n  /* space and shape */\n  --s1: 4px;\n  --s2: 8px;\n  --s3: 12px;\n  --s4: 16px;\n  --s5: 24px;\n  --radius: 2px;\n  --nav-h: 44px;\n  --top-h: 52px;\n  --ease: 140ms ease;\n}\n"],"/demo.js":["text/javascript; charset=utf-8","// Fake league shaped like ESPN's API responses. Used for ?demo and the tests.\n\nconst SEASON = 2027;\nconst CURRENT_SP = 10;\nconst FINAL_SP = 170;\nconst DAY = 86_400_000;\nconst OPENER = Date.UTC(2026, 9, 20, 23, 30); // Tue 20 Oct 2026, 7:30pm ET\n\nconst PRO = ['ATL', 'BOS', 'NOP', 'CHI', 'CLE', 'DAL', 'DEN', 'DET', 'GSW', 'HOU', 'IND', 'LAC', 'LAL', 'MIA', 'MIL', 'MIN', 'BKN', 'NYK', 'ORL', 'PHI', 'PHX', 'POR', 'SAC', 'SAS', 'OKC', 'UTA', 'WAS', 'TOR', 'MEM', 'CHA'];\nconst TEAMS = [\n  ['Free Throw', 'Merchants', 'Liam'], ['Glass', 'Cleaners', 'Noah'], ['Tank', 'Commanders', 'Jack'],\n  ['Box Out', 'Bandits', 'Oliver'], ['Fadeaway', 'Frauds', 'Ethan'], ['Air Ball', 'Society', 'Mason'],\n  ['Paint', 'Protectors', 'Lucas'], ['Bench', 'Mob', 'Cooper'], ['Pick and', 'Pray', 'Hugo'], ['Load', 'Managers', 'Archie'],\n];\nconst FIRST = ['Darnell', 'Tyrese', 'Marcus', 'Jalen', 'Andre', 'Kofi', 'Mateo', 'Luka', 'Dante', 'Isaiah', 'Theo', 'Malik', 'Rui', 'Cade', 'Bennett', 'Omari', 'Viktor', 'Jonah', 'Caleb', 'Xavier'];\nconst LAST = ['Whitlock', 'Okafor', 'Brennan', 'Castillo', 'Hale', 'Mbeki', 'Novak', 'Reyes', 'Sutton', 'Vance', 'Adeyemi', 'Kerr', 'Lindqvist', 'Marsh', 'Prior', 'Quinlan', 'Rook', 'Tate', 'Usher', 'Yates'];\nconst ACTIVE_SLOTS = [0, 1, 2, 3, 4, 5, 6, 11, 11, 11];\n// Lineup slots each position may fill (ESPN ids: PG 0, SG 1, SF 2, PF 3, C 4, G 5, F 6, SG/SF 7, G/F 8, PF/C 9, F/C 10, UTIL 11, bench 12, IR 13)\nconst ELIGIBLE = [[0, 5, 8, 11, 12, 13], [1, 5, 7, 8, 11, 12, 13], [2, 6, 7, 8, 10, 11, 12, 13], [3, 6, 9, 10, 11, 12, 13], [4, 9, 10, 11, 12, 13]];\n\nfunction rng(seed) {\n  return () => {\n    seed = (seed + 0x6d2b79f5) | 0;\n    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);\n    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;\n    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;\n  };\n}\n\nexport function createDemo({ withSchedule = false } = {}) {\n  const rand = rng(2027);\n  const gauss = () => Math.sqrt(-2 * Math.log(rand() || 1e-9)) * Math.cos(2 * Math.PI * rand());\n  const half = (v) => Math.round(v * 2) / 2;\n  const tip = (sp) => OPENER + (sp - 1) * DAY + (sp >= 13 ? 3_600_000 : 0); // DST ends 1 Nov\n  const now = tip(CURRENT_SP) + 80 * 60_000;\n\n  // Pro schedule\n  const proGames = new Map(PRO.map((_, i) => [i + 1, {}]));\n  for (let sp = 1; sp <= FINAL_SP; sp++) {\n    const ids = PRO.map((_, i) => i + 1).sort(() => rand() - 0.5);\n    const count = 4 + Math.floor(rand() * 5);\n    for (let g = 0; g < count; g++) {\n      const home = ids[g * 2];\n      const away = ids[g * 2 + 1];\n      const game = { id: sp * 100 + g, date: tip(sp) + [0, 0, 30, 60, 90, 180][g % 6] * 60_000, homeProTeamId: home, awayProTeamId: away, scoringPeriodId: sp };\n      proGames.get(home)[sp] = [game];\n      proGames.get(away)[sp] = [game];\n    }\n  }\n  const proRaw = {\n    settings: {\n      proTeams: [{ id: 0, abbrev: 'FA', proGamesByScoringPeriod: {} }, ...PRO.map((abbrev, i) => ({ id: i + 1, abbrev, proGamesByScoringPeriod: proGames.get(i + 1) }))],\n    },\n  };\n\n  // Players\n  let pid = 1000;\n  const teams = TEAMS.map(([location, nickname, owner], ti) => {\n    const players = Array.from({ length: 14 }, (_, k) => {\n      const mu = Math.max(12, 52 - k * 2.6 + gauss() * 5);\n      return {\n        id: ++pid,\n        fullName: `${FIRST[(pid * 7) % FIRST.length]} ${LAST[(pid * 13) % LAST.length]}`,\n        proTeamId: 1 + Math.floor(rand() * 30),\n        mu,\n        eligibleSlots: ELIGIBLE[pid % 5],\n        injuryStatus: k === 13 ? 'OUT' : rand() < 0.06 ? 'DAY_TO_DAY' : 'ACTIVE',\n        projAvg: mu * (0.85 + rand() * 0.3),\n        games: {},\n      };\n    });\n    return { id: ti + 1, location, nickname, owner, lazy: rand() * 0.3, players, slots: {}, daily: {} };\n  });\n\n  // Simulate days 1..CURRENT_SP: points + daily lineups\n  for (const t of teams) {\n    let prev = null;\n    for (let sp = 1; sp <= CURRENT_SP; sp++) {\n      const healthy = t.players.filter((p) => p.injuryStatus !== 'OUT');\n      let active;\n      if (prev && rand() < t.lazy) active = prev;\n      else {\n        const plays = (p) => Boolean(proGames.get(p.proTeamId)[sp]);\n        active = [...healthy].sort((a, b) => plays(b) - plays(a) || b.mu - a.mu).slice(0, 10).map((p) => p.id);\n      }\n      prev = active;\n      const slots = {};\n      let i = 0;\n      for (const p of t.players) slots[p.id] = p.injuryStatus === 'OUT' ? 13 : active.includes(p.id) ? ACTIVE_SLOTS[i++] : 12;\n      t.slots[sp] = slots;\n\n      let total = 0;\n      for (const p of t.players) {\n        const g = proGames.get(p.proTeamId)[sp]?.[0];\n        if (!g || p.injuryStatus === 'OUT') continue;\n        if (p.injuryStatus === 'DAY_TO_DAY' && rand() < 0.3) continue;\n        let pts = Math.max(0, p.mu + gauss() * 0.32 * p.mu);\n        if (sp === CURRENT_SP) {\n          if (g.date > now) continue;\n          pts *= Math.min(1, (now - g.date) / (150 * 60_000));\n        }\n        p.games[sp] = half(pts);\n        if (slots[p.id] <= 11) total += p.games[sp];\n      }\n      t.daily[sp] = Math.round(total * 10) / 10;\n    }\n    t.points = Math.round(Object.values(t.daily).reduce((a, b) => a + b, 0) * 10) / 10;\n  }\n\n  const matchupPeriods = { 1: [1, 2, 3, 4, 5, 6] };\n  for (let start = 7, id = 2; start <= FINAL_SP; start += 7, id++) {\n    matchupPeriods[id] = Array.from({ length: Math.min(7, FINAL_SP - start + 1) }, (_, i) => start + i);\n  }\n\n  function playerStats(p, sp) {\n    const played = Object.entries(p.games).filter(([s]) => +s < CURRENT_SP).map(([, v]) => v);\n    const gp = played.length;\n    const total = played.reduce((a, b) => a + b, 0);\n    const stats = [\n      { id: `00${SEASON}`, seasonId: SEASON, scoringPeriodId: 0, statSourceId: 0, statSplitTypeId: 0, appliedTotal: total, appliedAverage: gp ? total / gp : 0, stats: { 42: gp } },\n      { id: `02${SEASON}`, seasonId: SEASON, scoringPeriodId: 0, statSourceId: 0, statSplitTypeId: 2, appliedTotal: total, appliedAverage: gp ? total / gp : 0 },\n      { id: `10${SEASON}`, seasonId: SEASON, scoringPeriodId: 0, statSourceId: 1, statSplitTypeId: 0, appliedTotal: p.projAvg * 72, appliedAverage: p.projAvg },\n    ];\n    if (p.games[sp] !== undefined) {\n      // Real per-game rows are keyed by ESPN game id, and last season's games come along too.\n      const gameId = proGames.get(p.proTeamId)[sp][0].id;\n      stats.push({ id: `05${gameId}`, seasonId: SEASON, scoringPeriodId: sp, statSourceId: 0, statSplitTypeId: 5, appliedTotal: p.games[sp] });\n    }\n    stats.push({ id: `054018${sp}`, seasonId: SEASON - 1, scoringPeriodId: sp, statSourceId: 0, statSplitTypeId: 5, appliedTotal: 77.7 });\n    stats.push({ id: `00${SEASON - 1}`, seasonId: SEASON - 1, scoringPeriodId: 0, statSourceId: 0, statSplitTypeId: 0, appliedTotal: 3000, appliedAverage: 40, stats: { 42: 75 } });\n    return stats;\n  }\n\n  function league(views, { sp } = {}) {\n    const period = sp || CURRENT_SP;\n    const v = new Set(views);\n    const raw = {\n      gameId: 1,\n      id: 424242,\n      seasonId: SEASON,\n      scoringPeriodId: period,\n      segmentId: 0,\n      status: { currentMatchupPeriod: 2, firstScoringPeriod: 1, finalScoringPeriod: FINAL_SP, latestScoringPeriod: CURRENT_SP, isActive: true },\n      teams: teams.map((t) => {\n        const out = { id: t.id };\n        if (v.has('mTeam')) {\n          Object.assign(out, {\n            abbrev: t.nickname.slice(0, 4).toUpperCase(),\n            location: t.location,\n            nickname: t.nickname,\n            name: `${t.location} ${t.nickname}`,\n            owners: [`{M${t.id}}`],\n            points: t.points,\n            record: { overall: { pointsFor: t.points, wins: 0, losses: 0, ties: 0 } },\n          });\n        }\n        if (v.has('mRoster')) {\n          const slots = t.slots[Math.min(period, CURRENT_SP)];\n          out.roster = {\n            entries: t.players.map((p) => ({\n              playerId: p.id,\n              lineupSlotId: slots[p.id],\n              playerPoolEntry: { id: p.id, player: { id: p.id, fullName: p.fullName, proTeamId: p.proTeamId, injuryStatus: p.injuryStatus, eligibleSlots: p.eligibleSlots, stats: playerStats(p, period) } },\n            })),\n          };\n        }\n        return out;\n      }),\n    };\n    if (v.has('mTeam')) raw.members = teams.map((t) => ({ id: `{M${t.id}}`, firstName: t.owner, displayName: t.owner.toLowerCase() }));\n    if (v.has('mSettings')) {\n      raw.settings = {\n        name: 'Courtside Consequences',\n        rosterSettings: { lineupSlotCounts: { 0: 1, 1: 1, 2: 1, 3: 1, 4: 1, 5: 1, 6: 1, 11: 3, 12: 3, 13: 1 } },\n        scheduleSettings: { matchupPeriods },\n        scoringSettings: { scoringType: 'TOTAL_POINTS' },\n      };\n    }\n    raw.schedule = withSchedule\n      ? teams.map((t) => ({ matchupPeriodId: 1, home: { teamId: t.id, pointsByScoringPeriod: Object.fromEntries(Object.entries(t.daily)) } }))\n      : [];\n    return raw;\n  }\n\n  return {\n    config: async () => ({ configured: true, demo: true, leagueId: 'demo', season: SEASON }),\n    league: async (views, opts) => structuredClone(league(views, opts)),\n    pro: async () => structuredClone(proRaw),\n    freeAgents: async () => Array.from({ length: 14 }, (_, i) => ({ playerId: 9000 + i, name: `${FIRST[i]} ${LAST[(i * 3) % LAST.length]}`, proTeamId: 1 + ((i * 7) % 30), injury: i === 2 ? 'OUT' : 'ACTIVE', seasonGP: 9, seasonAvg: 27 - i * 0.7, projAvg: 28 - i * 0.6, eligibleSlots: ELIGIBLE[i % 5] })),\n    now: () => now,\n    truth: { teams, CURRENT_SP },\n  };\n}\n"],"/index.html":["text/html; charset=utf-8","<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Punishment Watch</title>\n  <meta name=\"description\" content=\"Fantasy basketball front office: weekly punishment odds, players, trades and league tools.\">\n  <meta name=\"theme-color\" content=\"#101216\">\n  <link rel=\"icon\" href=\"data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'><rect width='64' height='64' fill='%23e8f02a'/><path d='M3 32h58M32 3v58M12 10c10 10 10 34 0 44M52 10c-10 10-10 34 0 44' stroke='%23101216' stroke-width='3' fill='none'/></svg>\">\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800&family=Inter:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n  <link rel=\"stylesheet\" href=\"css/tokens.css\">\n  <link rel=\"stylesheet\" href=\"css/base.css\">\n  <link rel=\"stylesheet\" href=\"css/components.css\">\n  <link rel=\"stylesheet\" href=\"css/shell.css\">\n  <link rel=\"stylesheet\" href=\"css/pages.css\">\n</head>\n<body>\n  <header class=\"topbar\">\n    <div class=\"topbar-in\">\n      <div class=\"brand\">\n        <span class=\"mark\" aria-hidden=\"true\">PW</span>\n        <div>\n          <h1 id=\"league-name\">Punishment Watch</h1>\n          <span id=\"week-label\" class=\"sub\"></span>\n        </div>\n      </div>\n      <div class=\"top-tools\">\n        <span id=\"updated\" class=\"updated\" aria-live=\"polite\"></span>\n        <button id=\"account\" type=\"button\" class=\"acct\" hidden></button>\n        <button id=\"refresh\" type=\"button\" class=\"btn\">Refresh</button>\n      </div>\n    </div>\n    <nav id=\"mainnav\" class=\"mainnav\" aria-label=\"Main\"></nav>\n  </header>\n  <nav id=\"subnav\" class=\"subnav\" aria-label=\"Section\" hidden><div class=\"subnav-in\" id=\"subnav-in\"></div></nav>\n\n  <p id=\"banner\" class=\"banner\" hidden></p>\n  <main id=\"view\" class=\"frame\" aria-live=\"polite\"><p class=\"loading\">Loading league…</p></main>\n  <footer id=\"foot\" class=\"foot\"></footer>\n\n  <script type=\"module\" src=\"app.js\"></script>\n</body>\n</html>\n"],"/logic.js":["text/javascript; charset=utf-8","// Pure scoring/projection logic. No DOM — runs in the browser and in Node tests.\n\nexport const ACTIVE_MAX_SLOT = 11; // ESPN basketball lineup slots 0–11 score; 12 = bench, 13 = IR\nexport const IR_SLOT = 13;\nconst ET = 'America/New_York';\nconst DAY_MS = 86_400_000;\n\nexport const num = (v) => (typeof v === 'number' && Number.isFinite(v) ? v : Number(v) || 0);\nexport const r1 = (v) => Math.round(v * 10) / 10;\n\n/* ---------- ESPN parsing ---------- */\n\nexport function parseEntry(e, season) {\n  const p = e.playerPoolEntry?.player || e.player || {};\n  const stats = (p.stats || []).filter((s) => s.seasonId == null || s.seasonId === season);\n  const agg = (prefix) => stats.find((s) => String(s.id).startsWith(prefix) && !(s.scoringPeriodId > 0));\n  const total = agg('00');\n  const last15 = agg('02');\n  const proj = agg('10');\n\n  const bySP = {};\n  for (const s of stats) {\n    if (!(s.scoringPeriodId > 0)) continue;\n    const source = s.statSourceId ?? (String(s.id)[0] === '1' ? 1 : 0);\n    if (source === 0) bySP[s.scoringPeriodId] = num(s.appliedTotal);\n  }\n\n  const seasonAvg = num(total?.appliedAverage);\n  const gp = num(total?.stats?.['42']) || (seasonAvg ? Math.round(num(total.appliedTotal) / seasonAvg) : 0);\n\n  return {\n    playerId: p.id ?? e.playerId,\n    name: p.fullName || 'Unknown player',\n    proTeamId: p.proTeamId,\n    slot: e.lineupSlotId,\n    injury: p.injuryStatus || 'ACTIVE',\n    seasonAvg,\n    seasonGP: gp,\n    eligibleSlots: p.eligibleSlots || [],\n    last15Avg: num(last15?.appliedAverage),\n    projAvg: num(proj?.appliedAverage),\n    bySP,\n  };\n}\n\nexport function parseLeague(raw, fallbackSeason) {\n  const season = raw.seasonId ?? fallbackSeason;\n  const members = new Map((raw.members || []).map((m) => [m.id, m]));\n  const settings = raw.settings || {};\n  const slotCounts = settings.rosterSettings?.lineupSlotCounts || {};\n  let activeSlots = 0;\n  const slotIds = []; // one entry per starting slot, e.g. [0, 1, 2, 3, 4, 5, 6, 11, 11, 11]\n  let rosterLimit = 0;\n  for (const [slot, count] of Object.entries(slotCounts)) {\n    rosterLimit += num(count);\n    if (Number(slot) > ACTIVE_MAX_SLOT) continue;\n    activeSlots += num(count);\n    for (let i = 0; i < num(count); i++) slotIds.push(Number(slot));\n  }\n\n  const teams = (raw.teams || []).map((t) => {\n    const owner = members.get((t.owners || [])[0]);\n    return {\n      id: t.id,\n      name: (t.name || `${t.location ?? ''} ${t.nickname ?? ''}`).trim() || `Team ${t.id}`,\n      abbrev: t.abbrev || '',\n      logo: t.logo || null,\n      owner: owner ? owner.firstName || owner.displayName || '' : '',\n      seasonTotal: num(t.points ?? t.record?.overall?.pointsFor), // finished days only\n      seasonLive: t.pointsLive == null ? null : num(t.pointsLive), // also counts today's games in progress\n      roster: (t.roster?.entries || []).map((e) => parseEntry(e, season)),\n    };\n  });\n\n  return {\n    season,\n    currentSP: raw.scoringPeriodId,\n    firstSP: raw.status?.firstScoringPeriod ?? 1,\n    finalSP: raw.status?.finalScoringPeriod ?? null,\n    name: settings.name || 'Fantasy league',\n    activeSlots: activeSlots || 10,\n    slotIds: slotIds.length ? slotIds : [0, 1, 2, 3, 4, 5, 6, 11, 11, 11],\n    rosterLimit: rosterLimit || 23,\n    matchupPeriods: settings.scheduleSettings?.matchupPeriods || null,\n    schedule: raw.schedule || [],\n    teams,\n  };\n}\n\n// ESPN's injury report as a map by player id: { status, returnMs (UTC midnight of the expected return date),\n// guess (ESPN gives no timetable, so the date is a placeholder), type, detail }.\nexport function injuryMap(list) {\n  const out = new Map();\n  for (const i of list || []) {\n    const m = /^(\\d{4})-(\\d{2})-(\\d{2})/.exec(i.returnDate || '');\n    out.set(Number(i.playerId), { status: i.status, returnMs: m ? Date.UTC(+m[1], +m[2] - 1, +m[3]) : null, guess: Boolean(i.guess), type: i.type || null, detail: i.detail || null, comment: i.comment || '' });\n  }\n  return out;\n}\n\nexport function parseProSchedule(raw) {\n  const games = new Map(); // proTeamId -> Map(sp -> game)\n  const spDate = new Map(); // sp -> earliest tip-off (ms)\n  const spLast = new Map(); // sp -> latest tip-off (ms)\n  const spSlate = new Map(); // sp -> tip-off time of every game that day (ms, sorted)\n  const abbrev = new Map();\n  for (const t of raw?.settings?.proTeams || []) {\n    abbrev.set(t.id, t.abbrev || '');\n    if (!t.id) continue;\n    const bySP = new Map();\n    for (const [key, list] of Object.entries(t.proGamesByScoringPeriod || {})) {\n      if (!list?.length) continue;\n      const g = list[0];\n      const sp = Number(key);\n      bySP.set(sp, { date: num(g.date), opp: g.homeProTeamId === t.id ? g.awayProTeamId : g.homeProTeamId, home: g.homeProTeamId === t.id });\n      if (!spDate.has(sp) || g.date < spDate.get(sp)) spDate.set(sp, num(g.date));\n      if (!spLast.has(sp) || g.date > spLast.get(sp)) spLast.set(sp, num(g.date));\n      if (g.homeProTeamId === t.id) spSlate.set(sp, [...(spSlate.get(sp) || []), num(g.date)]); // count each game once, from the home side\n    }\n    games.set(t.id, bySP);\n  }\n  for (const [sp, times] of spSlate) spSlate.set(sp, times.sort((a, b) => a - b));\n  return { games, spDate, spLast, spSlate, abbrev, dayOffset: spDayOffset(spDate) };\n}\n\n// ESPN scoring period N is one US Eastern calendar day, with no period at all on days with no games.\n// So (ET date in days) - N is constant; take the most common value and derive every period's date from it.\nfunction spDayOffset(spDate) {\n  const counts = new Map();\n  for (const [sp, ms] of spDate) {\n    const off = etDayNumber(ms) - sp;\n    counts.set(off, (counts.get(off) || 0) + 1);\n  }\n  let best = null;\n  for (const [off, n] of counts) if (!best || n > best[1]) best = [off, n];\n  return best ? best[0] : null;\n}\n\nconst GAME_LENGTH = 3.5 * 3_600_000; // tip-off to final buzzer, with overtime and delays to spare\n\n// ESPN keeps a scoring period \"current\" for hours after its last game ends. Once every game that day\n// has had time to finish, the day is done and belongs in the recap, whatever ESPN's counter says.\nexport function isDayDone(pro, sp, now) {\n  const last = pro.spLast?.get(sp);\n  return last != null && now >= last + GAME_LENGTH;\n}\n\n// The last scoring period whose results are final.\n// `dayDone`: true/false when the live scoreboard says whether today's games are all final; undefined falls back to the clock.\nexport const finishedThrough = (league, pro, now, dayDone) => ((dayDone ?? isDayDone(pro, league.currentSP, now)) ? league.currentSP : league.currentSP - 1);\n\n// UTC midnight (ms) of the ET calendar date for scoring period `sp`, or null if unknown.\nexport function spDay(pro, sp) {\n  return pro.dayOffset == null ? null : (pro.dayOffset + sp) * DAY_MS;\n}\n\n/* ---------- Slimming (static snapshot) ---------- */\n\n// Same shape as ESPN's response but only what the parsers read, so a snapshot stays small.\n// `sp`: the one day whose per-game stat is kept. `full: false` also drops team info, settings and\n// season aggregates, which is all a per-day roster needs.\nfunction slimStat(s) {\n  const out = { id: s.id, seasonId: s.seasonId, scoringPeriodId: s.scoringPeriodId, statSourceId: s.statSourceId, statSplitTypeId: s.statSplitTypeId, appliedTotal: s.appliedTotal, appliedAverage: s.appliedAverage };\n  if (s.stats?.['42'] != null) out.stats = { 42: s.stats['42'] };\n  return out;\n}\n\nexport function slimLeague(raw, season, { sp, full = true }) {\n  const keepStat = (s) => {\n    if (s.seasonId != null && s.seasonId !== season) return false;\n    if (s.scoringPeriodId > 0) return s.scoringPeriodId === sp && (s.statSourceId ?? (String(s.id)[0] === '1' ? 1 : 0)) === 0;\n    return full; // aggregates are only needed for projections\n  };\n  const out = {\n    seasonId: raw.seasonId,\n    scoringPeriodId: raw.scoringPeriodId,\n    teams: (raw.teams || []).map((t) => {\n      const team = { id: t.id };\n      if (full) {\n        Object.assign(team, { name: t.name, location: t.location, nickname: t.nickname, abbrev: t.abbrev, logo: t.logo, owners: (t.owners || []).slice(0, 1), points: t.points, pointsLive: t.pointsLive });\n        if (t.record?.overall?.pointsFor != null) team.record = { overall: { pointsFor: t.record.overall.pointsFor } };\n      }\n      if (t.roster) {\n        team.roster = {\n          entries: (t.roster.entries || []).map((e) => {\n            const p = e.playerPoolEntry?.player || e.player || {};\n            return {\n              playerId: e.playerId ?? p.id,\n              lineupSlotId: e.lineupSlotId,\n              playerPoolEntry: { player: { id: p.id, fullName: p.fullName, proTeamId: p.proTeamId, injuryStatus: p.injuryStatus, eligibleSlots: p.eligibleSlots, stats: (p.stats || []).filter(keepStat).map(slimStat) } },\n            };\n          }),\n        };\n      }\n      return team;\n    }),\n  };\n  if (!full) return out;\n  if (raw.members) out.members = raw.members.map((m) => ({ id: m.id, firstName: m.firstName, displayName: m.displayName }));\n  if (raw.status) {\n    const { firstScoringPeriod, finalScoringPeriod, latestScoringPeriod, currentMatchupPeriod } = raw.status;\n    out.status = { firstScoringPeriod, finalScoringPeriod, latestScoringPeriod, currentMatchupPeriod };\n  }\n  const st = raw.settings;\n  if (st) {\n    out.settings = {\n      name: st.name,\n      rosterSettings: { lineupSlotCounts: st.rosterSettings?.lineupSlotCounts },\n      scheduleSettings: { matchupPeriods: st.scheduleSettings?.matchupPeriods },\n      scoringSettings: { scoringType: st.scoringSettings?.scoringType },\n    };\n  }\n  out.schedule = (raw.schedule || [])\n    .filter((m) => m.home?.pointsByScoringPeriod || m.away?.pointsByScoringPeriod)\n    .map((m) => ({\n      matchupPeriodId: m.matchupPeriodId,\n      home: { teamId: m.home?.teamId, pointsByScoringPeriod: m.home?.pointsByScoringPeriod },\n      ...(m.away ? { away: { teamId: m.away.teamId, pointsByScoringPeriod: m.away.pointsByScoringPeriod } } : {}),\n    }));\n  return out;\n}\n\nexport function slimPro(raw) {\n  return {\n    settings: {\n      proTeams: (raw?.settings?.proTeams || []).map((t) => ({\n        id: t.id,\n        abbrev: t.abbrev,\n        proGamesByScoringPeriod: Object.fromEntries(\n          Object.entries(t.proGamesByScoringPeriod || {}).map(([sp, list]) => [sp, list.map((g) => ({ date: g.date, homeProTeamId: g.homeProTeamId, awayProTeamId: g.awayProTeamId }))]),\n        ),\n      })),\n    },\n  };\n}\n\n/* ---------- Daily points ---------- */\n\n// Per-team daily points straight from ESPN's matchup feed (when the league has one).\nexport function dailyFromSchedule(league) {\n  const daily = new Map();\n  for (const m of league.schedule) {\n    for (const side of ['home', 'away']) {\n      const s = m[side];\n      if (!s?.teamId || !s.pointsByScoringPeriod) continue;\n      if (!daily.has(s.teamId)) daily.set(s.teamId, new Map());\n      for (const [sp, pts] of Object.entries(s.pointsByScoringPeriod)) daily.get(s.teamId).set(Number(sp), num(pts));\n    }\n  }\n  return daily;\n}\n\nexport function scheduleCovers(daily, league, pro, sps) {\n  if (!league.teams.every((t) => daily.has(t.id))) return false;\n  return sps.every((sp) => !pro.spDate.has(sp) || league.teams.some((t) => daily.get(t.id).has(sp)));\n}\n\n// One day's points per team from a roster response requested with scoringPeriodId=sp.\n// Only players in scoring slots (not bench/IR) that day count.\nexport function dayFromRoster(raw, sp, fallbackSeason) {\n  const season = raw.seasonId ?? fallbackSeason;\n  const out = new Map();\n  for (const t of raw.teams || []) {\n    let pts = 0;\n    const players = [];\n    for (const e of t.roster?.entries || []) {\n      const p = parseEntry(e, season);\n      const v = p.bySP[sp];\n      if (v === undefined) continue;\n      const active = p.slot <= ACTIVE_MAX_SLOT;\n      if (active) pts += v;\n      players.push({ name: p.name, pts: v, active, proTeamId: p.proTeamId });\n    }\n    out.set(t.id, { pts: r1(pts), players });\n  }\n  return out;\n}\n\n/* ---------- Weeks ---------- */\n\nconst etParts = new Intl.DateTimeFormat('en-US', { timeZone: ET, year: 'numeric', month: 'numeric', day: 'numeric' });\nconst dayLabelFmt = new Intl.DateTimeFormat('en-AU', { timeZone: 'UTC', weekday: 'short', day: 'numeric', month: 'short' });\n\n// Whole days since 1970-01-01 of the ET calendar date containing `ms`.\nfunction etDayNumber(ms) {\n  const p = Object.fromEntries(etParts.formatToParts(ms).map((x) => [x.type, x.value]));\n  return Date.UTC(+p.year, +p.month - 1, +p.day) / DAY_MS;\n}\n\n// The scoring period for a moment in time (the US Eastern calendar day it falls on), or null if unknown.\nexport function spOnDate(pro, ms) {\n  return pro.dayOffset == null ? null : etDayNumber(ms) - pro.dayOffset;\n}\n\nexport function dayLabel(pro, sp) {\n  const ms = spDay(pro, sp);\n  return ms == null ? `Day ${sp}` : dayLabelFmt.format(ms).replace(',', '');\n}\n\n// ESPN's own matchup periods, only if they look like weeks. A season-long points league can report\n// one giant period (or none), which would make \"this week\" the whole season.\nfunction espnWeeks(league) {\n  const mp = league.matchupPeriods;\n  if (!mp || !Object.keys(mp).length) return null;\n  const weeks = Object.entries(mp)\n    .map(([id, sps]) => ({ id: Number(id), sps: (Array.isArray(sps) ? sps : []).map(Number).sort((a, b) => a - b) }))\n    .filter((w) => w.sps.length)\n    .sort((a, b) => a.id - b.id);\n  if (weeks.length < 2) return null;\n  const lens = weeks.map((w) => w.sps.length).sort((a, b) => a - b);\n  const median = lens[Math.floor(lens.length / 2)];\n  return median >= 5 && median <= 9 && lens.at(-1) <= 21 ? weeks : null;\n}\n\nexport const DEFAULT_WEEK_START = 2; // Tuesday: this league's weeks run Tuesday to Monday (US Eastern)\n\n// 'Tue', 'tuesday', 2 -> 2 (JS weekday, Sunday = 0). Anything unrecognised gives the default.\nexport function parseWeekStart(v) {\n  const i = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'].indexOf(String(v ?? '').trim().slice(0, 3).toLowerCase());\n  return i >= 0 ? i : DEFAULT_WEEK_START;\n}\n\n// Weeks follow ESPN's matchup periods when they exist; otherwise 7-day weeks starting on `weekStart`\n// (US Eastern calendar days). `weeks.source` says which.\nexport function buildWeeks(league, pro, { weekStart = DEFAULT_WEEK_START } = {}) {\n  const fromEspn = espnWeeks(league);\n  if (fromEspn) return Object.assign(fromEspn, { source: 'espn' });\n\n  const groups = [];\n  const sps = [...pro.spDate.keys()];\n  const last = Math.max(0, ...sps);\n  const first = Math.min(league.firstSP || 1, ...sps);\n  let key = null;\n  for (let sp = first; sp <= last; sp++) {\n    const day = spDay(pro, sp);\n    if (day == null) break;\n    const start = day - ((new Date(day).getUTCDay() - weekStart + 7) % 7) * DAY_MS;\n    if (start !== key) groups.push([]), (key = start);\n    groups.at(-1).push(sp);\n  }\n  // A short opening stub (season starts late in the week) joins week 1.\n  if (groups.length > 1 && groups[0].length < 4) groups.splice(0, 2, [...groups[0], ...groups[1]]);\n  return Object.assign(groups.map((g, i) => ({ id: i + 1, sps: g })), { source: 'calendar', weekStart });\n}\n\nexport const weekOf = (weeks, sp) => weeks.find((w) => w.sps.includes(sp)) || null;\n\nexport function currentWeek(weeks, sp) {\n  return weekOf(weeks, sp) || weeks.find((w) => w.sps[0] > sp) || weeks[weeks.length - 1];\n}\n\nexport function weekLabel(pro, week) {\n  return `${dayLabel(pro, week.sps[0])} to ${dayLabel(pro, week.sps[week.sps.length - 1])}`;\n}\n\n/* ---------- Game day schedule ---------- */\n\nconst LIKELY_GAME = 2.5 * 3_600_000; // a typical NBA game, tip-off to final buzzer\n\nexport function validTimeZone(tz) {\n  try {\n    new Intl.DateTimeFormat('en-AU', { timeZone: tz });\n    return Boolean(tz);\n  } catch {\n    return false;\n  }\n}\n\n// \"Thu 10:00 am\" in the given time zone (en-AU, 12-hour).\nexport function localTime(ms, tz) {\n  const p = Object.fromEntries(new Intl.DateTimeFormat('en-AU', { timeZone: tz, weekday: 'short', hour: 'numeric', minute: '2-digit', hour12: true }).formatToParts(ms).map((x) => [x.type, x.value]));\n  return `${p.weekday} ${p.hour}:${p.minute} ${String(p.dayPeriod).toLowerCase()}`;\n}\n\nexport const zoneName = (ms, tz) => new Intl.DateTimeFormat('en-AU', { timeZone: tz, timeZoneName: 'short' }).formatToParts(ms).find((x) => x.type === 'timeZoneName')?.value || tz;\n\n// \"2h 15m\" / \"40m\"\nexport function duration(ms) {\n  const m = Math.max(0, Math.round(ms / 60_000));\n  return m >= 60 ? `${Math.floor(m / 60)}h ${String(m % 60).padStart(2, '0')}m` : `${m}m`;\n}\n\n// ESPN's scoreboard asks for the US Eastern date as YYYYMMDD.\nexport function etDateKey(pro, sp) {\n  const day = spDay(pro, sp);\n  return day == null ? null : new Date(day).toISOString().slice(0, 10).replace(/-/g, '');\n}\n\n// One game day: when it starts, when it likely ends, and where it is now.\n// `board` is the live scoreboard for that day ({ sp, games: [{ state: 'pre' | 'in' | 'post' }] }); without it\n// the state is estimated from the clock.\nexport function dayInfo(pro, sp, now, board = null) {\n  const slate = pro.spSlate?.get(sp);\n  if (!slate?.length) return null;\n  const firstTip = slate[0];\n  const lastTip = slate.at(-1);\n  const live = board && board.sp === sp && board.games.length >= slate.length ? board.games : null;\n  let state;\n  let final = null;\n  if (live) {\n    final = live.filter((g) => g.state === 'post').length;\n    const playing = live.filter((g) => g.state === 'in').length;\n    state = final === live.length ? 'done' : final + playing > 0 ? 'live' : 'upcoming';\n  } else {\n    state = now < firstTip ? 'upcoming' : now >= lastTip + GAME_LENGTH ? 'done' : 'live';\n  }\n  return { sp, games: slate.length, firstTip, lastTip, likelyEnd: lastTip + LIKELY_GAME, state, final, estimated: !live };\n}\n\n// Today's slate and, once it is over (or there is none), the next one.\nexport function gameDays(pro, cur, now, board = null) {\n  const today = dayInfo(pro, cur, now, board);\n  let next = null;\n  for (let sp = cur + 1; sp <= cur + 14 && !next; sp++) next = dayInfo(pro, sp, now);\n  return { today, next };\n}\n\n/* ---------- Standings ---------- */\n\n// Weekly points from 0, summing days in the week up to and including `upto`.\nexport function standings(teams, daily, sps, upto = Infinity) {\n  const rows = teams.map((t) => {\n    let pts = 0;\n    for (const sp of sps) if (sp <= upto) pts += daily.get(t.id)?.get(sp) ?? 0;\n    return { id: t.id, pts: r1(pts) };\n  });\n  rows.sort((a, b) => b.pts - a.pts);\n  rows.forEach((r, i) => (r.rank = i > 0 && r.pts === rows[i - 1].pts ? rows[i - 1].rank : i + 1));\n  return new Map(rows.map((r) => [r.id, r]));\n}\n\n/* ---------- Projections ---------- */\n\n// Points per game we expect from a player when he plays: his games so far, pulled toward ESPN's preseason\n// projection as if it were 16 games of evidence. Fitted on last season's game logs (see README, Trade stars):\n// this predicted the rest of the season better than the raw average or the old average + last-15 blend.\nexport function expectedPerGame(p) {\n  const prior = p.projAvg || p.seasonAvg || 0;\n  return ((p.seasonGP || 0) * (p.seasonAvg || 0) + 16 * prior) / ((p.seasonGP || 0) + 16);\n}\n\n/* ---------- Week simulation ---------- */\n\n// Fitted on a real week (see test/backtest). Players miss games, and a miss tends to repeat.\nexport const MODEL = {\n  gameCV: 0.4, // spread of a player's points in a game he plays, as a share of his average (measured: 0.40)\n  base: 0.035, // chance a healthy player sits out after playing; with `persist` this settles at ~8% of games missed (measured: 9%)\n  persist: 0.6, // chance he also misses the next one, once he has missed\n  outPersist: 0.9, // same, for a player ESPN lists as out\n  levelSd: 0.2, // uncertainty in a player's true average before any games (shrinks as games are played)\n  levelFloor: 0.05, // role and usage can change, whatever the sample\n  later: 0.97, // days not yet set: managers miss slots, positions don't line up\n  returnMiss: 0.4, // chance a player misses his first game back from an injury (an assumption: not testable yet)\n  teamSd: 0.07, // how well a manager sets lineups all week (teams scored 85-96% of their best lineup)\n};\n\n// Chance a player misses his next game, from ESPN's injury status.\nexport function missChance(status) {\n  switch (String(status || 'ACTIVE').toUpperCase()) {\n    case 'OUT':\n    case 'SUSPENSION':\n    case 'INJURY_RESERVE':\n      return 1;\n    case 'DOUBTFUL':\n      return 0.85;\n    case 'QUESTIONABLE':\n      return 0.45;\n    case 'DAY_TO_DAY':\n    case 'GTD':\n      return 0.35;\n    default:\n      return MODEL.base;\n  }\n}\n\n// Relative uncertainty in a player's true scoring level: the prior, shrunk by the games he has played.\nexport const levelSd = (gp) => Math.sqrt(1 / (1 / MODEL.levelSd ** 2 + gp / MODEL.gameCV ** 2) + MODEL.levelFloor ** 2);\n\n// What a team can still score this week. Today uses the lineup as set (games not yet started); later\n// days assume the best `activeSlots` players by expected points get started, chosen before knowing who sits.\n// Returns the expected points plus the plan the simulation draws from.\nexport function projectTeam(team, { week, currentSP, pro, now, activeSlots }) {\n  const days = week.sps.filter((sp) => sp >= currentSP);\n  const cands = [];\n  for (const p of team.roster) {\n    if (p.slot === IR_SLOT) continue;\n    const mu = expectedPerGame(p);\n    if (mu <= 0) continue;\n    const persist = missChance(p.injury) >= 1 && p.returnMs == null ? MODEL.outPersist : MODEL.persist;\n    // With an expected return date from ESPN's injury report: certainly out before it, shaky just after it.\n    // Without one, ESPN's status gives the chance and a miss tends to repeat.\n    const dated = p.returnMs != null;\n    let miss = dated ? MODEL.returnMiss : missChance(p.injury);\n    let anchored = true; // the chain starts here (first game, or the first game back)\n    const games = [];\n    for (const sp of days) {\n      const g = pro.games.get(p.proTeamId)?.get(sp);\n      if (!g || (sp === currentSP && g.date <= now)) continue; // no game, or already played (its points are in the total)\n      if (dated && spDay(pro, sp) < p.returnMs) {\n        games.push({ sp, miss: 1, forced: true, picked: false, today: false });\n        miss = MODEL.returnMiss;\n        anchored = true;\n        continue;\n      }\n      games.push({ sp, miss, anchor: anchored, picked: false, today: sp === currentSP && p.slot <= ACTIVE_MAX_SLOT });\n      anchored = false;\n      miss = miss * persist + (1 - miss) * MODEL.base;\n    }\n    if (games.length) cands.push({ p, mu, persist, games });\n  }\n\n  for (const sp of days) {\n    const here = cands.map((c) => ({ c, g: c.games.find((x) => x.sp === sp) })).filter((x) => x.g && x.g.miss < 0.999);\n    if (sp === currentSP) {\n      for (const { g } of here) g.picked = g.today; // the lineup as set\n    } else {\n      here.sort((a, b) => b.c.mu * (1 - b.g.miss) - a.c.mu * (1 - a.g.miss));\n      for (const { g } of here.slice(0, activeSlots)) g.picked = true;\n    }\n  }\n\n  let mean = 0;\n  let games = 0;\n  const players = new Set();\n  const plan = [];\n  for (const c of cands) {\n    if (!c.games.some((g) => g.picked)) continue;\n    plan.push({ mu: c.mu, levelSd: levelSd(c.p.seasonGP), persist: c.persist, games: c.games.map((g) => ({ ...g, w: g.sp === currentSP ? 1 : MODEL.later })) });\n    for (const g of c.games) {\n      if (!g.picked) continue;\n      mean += c.mu * (1 - g.miss) * (g.sp === currentSP ? 1 : MODEL.later);\n      if (g.miss < 0.5) {\n        games += 1; // \"games left\" counts games he is likely to play; a long shot still adds to the mean\n        players.add(c.p.playerId);\n      }\n    }\n  }\n  return { mean: r1(mean), games, players: players.size, plan };\n}\n\nfunction mulberry32(seed) {\n  return () => {\n    seed |= 0;\n    seed = (seed + 0x6d2b79f5) | 0;\n    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);\n    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;\n    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;\n  };\n}\n\n// Plays the rest of the week many times: each player gets a true level (uncertain), then a chain of\n// played/missed games, then a noisy score per game he plays. Returns each team's chance of finishing last\n// and the spread of its remaining points. Seeded so the numbers don't jitter between renders.\n// A number for any team id (numbers as they are, anything else hashed)\nconst idHash = (id) => (Number.isFinite(Number(id)) ? Number(id) : [...String(id)].reduce((h, c) => (Math.imul(h, 31) + c.charCodeAt(0)) | 0, 7));\n\n// Each team in each simulation gets its own random stream (from `seed`, the simulation number and the team), so a team\n// whose roster has not changed plays out identically between two runs. That makes a before/after comparison show the\n// effect of the change instead of random noise. `seed` defaults to one derived from the rows. The result's `.seed`\n// is the one used, to pass back in for the \"after\" run. `reuse` (the previous run's `.cache`) lets teams whose\n// inputs are unchanged skip the work and keep their earlier results exactly.\nexport function simulateWeek(rows, sims = 4000, seed = null, reuse = null) {\n  let derived = 7;\n  for (const r of rows) derived = (Math.imul(derived, 31) + Math.round(r.current * 10 + r.mean * 7)) | 0;\n  const base = seed ?? derived;\n  const stream = (sim, id) => {\n    const rand = mulberry32((base ^ Math.imul(sim + 1, 0x9e3779b1) ^ Math.imul(idHash(id) + 7, 0x85ebca6b)) | 0);\n    rand();\n    rand();\n    return { rand, gauss: () => Math.sqrt(-2 * Math.log(rand() || 1e-12)) * Math.cos(2 * Math.PI * rand()) };\n  };\n  const sigma2 = Math.log(1 + MODEL.gameCV ** 2);\n  const sigma = Math.sqrt(sigma2);\n  const hits = new Map(rows.map((r) => [r.id, 0]));\n  const sum = new Map(rows.map((r) => [r.id, 0]));\n  const sumSq = new Map(rows.map((r) => [r.id, 0]));\n  const usable = reuse && reuse.base === base && reuse.sims === sims;\n  const teams = new Map(\n    rows.map((r) => {\n      const sig = JSON.stringify([r.current, r.plan || []]);\n      const old = usable ? reuse.teams.get(r.id) : null;\n      return [r.id, old && old.sig === sig ? { sig, rests: old.rests, reused: true } : { sig, rests: new Float64Array(sims), reused: false }];\n    }),\n  );\n  for (let i = 0; i < sims; i++) {\n    let min = Infinity;\n    let losers = [];\n    for (const r of rows) {\n      const mine = teams.get(r.id);\n      let rest = 0;\n      if (mine.reused) rest = mine.rests[i];\n      else {\n        const { rand, gauss } = stream(i, r.id);\n        const manager = Math.exp(MODEL.teamSd * gauss() - (MODEL.teamSd * MODEL.teamSd) / 2);\n        for (const pl of r.plan || []) {\n          const level = Math.exp(pl.levelSd * gauss() - (pl.levelSd * pl.levelSd) / 2);\n          let missed = false;\n          for (const g of pl.games) {\n            if (g.forced) {\n              missed = true; // ESPN says he is still out\n              continue;\n            }\n            missed = rand() < (g.anchor ? g.miss : missed ? pl.persist : MODEL.base);\n            if (!missed && g.picked) rest += pl.mu * level * g.w * Math.exp(sigma * gauss() - sigma2 / 2);\n          }\n        }\n        rest *= manager;\n        mine.rests[i] = rest;\n      }\n      sum.set(r.id, sum.get(r.id) + rest);\n      sumSq.set(r.id, sumSq.get(r.id) + rest * rest);\n      const v = r.current + rest;\n      if (v < min - 1e-9) (min = v), (losers = [r.id]);\n      else if (Math.abs(v - min) <= 1e-9) losers.push(r.id);\n    }\n    for (const id of losers) hits.set(id, hits.get(id) + 1 / losers.length);\n  }\n  const out = new Map(rows.map((r) => {\n    const m = sum.get(r.id) / sims;\n    return [r.id, { odds: hits.get(r.id) / sims, mean: m, sd: Math.sqrt(Math.max(0, sumSq.get(r.id) / sims - m * m)) }];\n  }));\n  out.seed = base;\n  out.cache = { base, sims, teams };\n  return out;\n}\n\n/* ---------- Model for the UI ---------- */\n\nexport function buildModel({ league, pro, weeks, daily, dayDetail, now, source, dayDone, seed = null, reuse = null }) {\n  const cur = league.currentSP;\n  const week = currentWeek(weeks, cur);\n  const teamById = new Map(league.teams.map((t) => [t.id, t]));\n  const nowSt = standings(league.teams, daily, week.sps, cur);\n  const prevSt = week.sps.includes(cur - 1) ? standings(league.teams, daily, week.sps, cur - 1) : null;\n  const through = finishedThrough(league, pro, now, dayDone);\n\n  const rows = league.teams.map((t) => {\n    const st = nowSt.get(t.id);\n    const proj = projectTeam(t, { week, currentSP: cur, pro, now, activeSlots: league.activeSlots });\n    return {\n      id: t.id,\n      name: t.name,\n      owner: t.owner,\n      logo: t.logo,\n      seasonTotal: t.seasonTotal,\n      weekPts: st.pts,\n      rank: st.rank,\n      prevRank: prevSt?.get(t.id).rank ?? null,\n      todayPts: r1(daily.get(t.id)?.get(cur) ?? 0),\n      projRemaining: proj.mean,\n      projFinal: r1(st.pts + proj.mean),\n      plan: proj.plan,\n      gamesLeft: proj.games,\n      playersLeft: proj.players,\n    };\n  });\n\n  const sim = simulateWeek(rows.map((r) => ({ id: r.id, current: r.weekPts, mean: r.projRemaining, plan: r.plan })), 4000, seed, reuse);\n  for (const r of rows) {\n    r.odds = sim.get(r.id).odds;\n    r.sd = sim.get(r.id).sd;\n    delete r.plan;\n  }\n  rows.sort((a, b) => a.rank - b.rank || b.projFinal - a.projFinal);\n\n  const byProj = [...rows].sort((a, b) => b.projFinal - a.projFinal);\n  byProj.forEach((r, i) => (r.projRank = i + 1));\n  const loser = [...rows].sort((a, b) => b.odds - a.odds || a.projFinal - b.projFinal)[0];\n  const safety = byProj.filter((r) => r.id !== loser?.id).at(-1);\n\n  return {\n    leagueName: league.name,\n    week: { ...week, label: weekLabel(pro, week), dayNumber: week.sps.filter((sp) => sp <= cur).length, days: week.sps.length },\n    currentSP: cur,\n    todayLabel: dayLabel(pro, cur),\n    rows,\n    loser,\n    safety,\n    gap: loser && safety ? r1(safety.projFinal - loser.projFinal) : 0,\n    recap: buildRecap({ league, pro, weeks, daily, dayDetail, cur: through + 1, teamById }),\n    recapLive: through < cur ? liveRecap({ league, pro, weeks, daily, dayDetail, cur, teamById }) : null,\n    shame: weeklyResults(league.teams, daily, weeks, through + 1, pro),\n    source,\n    simSeed: sim.seed,\n    simCache: sim.cache,\n    weeksSource: weeks.source || null,\n    weekStart: weeks.weekStart ?? null,\n  };\n}\n\n// `live`: the day is still being played, so these are points so far rather than results.\nexport function buildRecap({ league, pro, weeks, daily, dayDetail, cur, teamById, live = false }) {\n  const D = cur - 1;\n  const week = weekOf(weeks, D);\n  if (!week) return null;\n  const after = standings(league.teams, daily, week.sps, D);\n  const before = week.sps.includes(D - 1) ? standings(league.teams, daily, week.sps, D - 1) : null;\n\n  const rows = league.teams\n    .map((t) => {\n      const a = after.get(t.id);\n      const b = before?.get(t.id);\n      return {\n        id: t.id,\n        name: t.name,\n        owner: t.owner,\n        dayPts: r1(daily.get(t.id)?.get(D) ?? 0),\n        weekPts: a.pts,\n        rank: a.rank,\n        prevRank: b?.rank ?? null,\n        move: b ? b.rank - a.rank : 0,\n      };\n    })\n    .sort((x, y) => x.rank - y.rank);\n\n  let best = null;\n  let worst = null;\n  for (const [teamId, day] of dayDetail?.get(D) || []) {\n    for (const p of day.players) {\n      if (!p.active) continue;\n      const item = { ...p, team: teamById.get(teamId)?.name || '' };\n      if (!best || p.pts > best.pts) best = item;\n      if (!worst || p.pts < worst.pts) worst = item;\n    }\n  }\n\n  const byDay = [...rows].sort((a, b) => b.dayPts - a.dayPts);\n  const minWeek = Math.min(...rows.map((r) => r.weekPts));\n  return {\n    sp: D,\n    label: dayLabel(pro, D),\n    week: { ...week, label: weekLabel(pro, week) },\n    dayNumber: week.sps.indexOf(D) + 1,\n    final: !live && D === week.sps.at(-1),\n    live,\n    rows,\n    climbers: rows.filter((r) => r.move > 0).sort((a, b) => b.move - a.move),\n    fallers: rows.filter((r) => r.move < 0).sort((a, b) => a.move - b.move),\n    topDay: byDay[0],\n    lowDay: byDay[byDay.length - 1],\n    last: rows.filter((r) => r.weekPts === minWeek),\n    best,\n    worst,\n  };\n}\n\n// Today so far, once any team has scored: the recap for a day ESPN hasn't finished.\nfunction liveRecap(args) {\n  const r = buildRecap({ ...args, cur: args.cur + 1, live: true });\n  return r && r.rows.some((x) => x.dayPts > 0) ? r : null;\n}\n\nexport function weeklyResults(teams, daily, weeks, cur, pro) {\n  return weeks\n    .filter((w) => w.sps.at(-1) < cur && w.sps.some((sp) => teams.some((t) => daily.get(t.id)?.has(sp))))\n    .map((w) => {\n      const rows = [...standings(teams, daily, w.sps).values()].sort((a, b) => a.pts - b.pts);\n      const losers = rows.filter((r) => r.pts === rows[0].pts);\n      const next = rows.find((r) => r.pts > rows[0].pts);\n      return {\n        week: w.id,\n        label: weekLabel(pro, w),\n        losers: losers.map((r) => ({ id: r.id, pts: r.pts })),\n        margin: next ? r1(next.pts - rows[0].pts) : 0,\n        top: rows[rows.length - 1],\n      };\n    })\n    .reverse();\n}\n\n// Compare our day-by-day rebuild with ESPN's own season totals. ESPN's `points` only counts finished\n// days (`pointsLive` adds today's games in progress), so try each pairing and report the closest.\nexport function checkTotals(teams, daily, uptoSP) {\n  return teams.map((t) => {\n    let incl = 0;\n    let excl = 0;\n    for (const [sp, pts] of daily.get(t.id) || []) {\n      if (sp <= uptoSP) incl += pts;\n      if (sp < uptoSP) excl += pts;\n    }\n    const tries = [\n      { ours: excl, espn: t.seasonTotal, basis: 'finished days' },\n      { ours: incl, espn: t.seasonTotal, basis: 'including today' },\n      ...(t.seasonLive != null ? [{ ours: incl, espn: t.seasonLive, basis: 'including today' }] : []),\n    ];\n    const best = tries.reduce((a, b) => (Math.abs(b.ours - b.espn) < Math.abs(a.ours - a.espn) ? b : a));\n    return { id: t.id, name: t.name, espn: r1(best.espn), ours: r1(best.ours), basis: best.basis, ok: Math.abs(best.ours - best.espn) < 0.6 };\n  });\n}\n"],"/meters.js":["text/javascript; charset=utf-8","// Two plain-language gauges on top of the weekly odds. Both are 0-100 and pure (no page code), so they are tested.\n// They describe the race; they are not extra predictions. The odds themselves come from simulateWeek in logic.js.\nconst clamp = (v, lo = 0, hi = 1) => Math.min(hi, Math.max(lo, v));\nconst mean = (xs) => xs.reduce((a, b) => a + b, 0) / (xs.length || 1);\n\n// Share of the week's points the teams have already banked (0 at tip-off, 1 when every game is done).\nexport function bankedShare(rows) {\n  const final = mean(rows.map((r) => r.projFinal));\n  return final > 0 ? clamp(mean(rows.map((r) => r.weekPts)) / final) : 0;\n}\n\n// How concentrated the \"who finishes last\" odds are: 1 when one team has it all, 0 when it is a coin toss between everyone.\nexport function concentration(rows) {\n  const n = rows.length;\n  if (n < 2) return 1;\n  const h = rows.reduce((s, r) => s - (r.odds > 0 ? r.odds * Math.log(r.odds) : 0), 0);\n  return clamp(1 - h / Math.log(n));\n}\n\n// Confidence in the loser %: how settled the race is. Half is how much of the week is already banked\n// (late in the week the order rarely moves), half is how lopsided the odds are.\nexport function confidence(model) {\n  const rows = model?.rows || [];\n  if (rows.length < 2) return null;\n  const banked = bankedShare(rows);\n  const conc = concentration(rows);\n  const score = Math.round(100 * (0.5 * banked + 0.5 * conc));\n  const level = score >= 70 ? 'High' : score >= 40 ? 'Medium' : 'Low';\n  const why = `${Math.round(banked * 100)}% of the week’s points are already scored, and the odds are ${conc >= 0.6 ? 'concentrated on one team' : conc >= 0.3 ? 'spread over a few teams' : 'spread over most of the league'}.`;\n  return { score, level, banked, concentration: conc, why };\n}\n\n// The O-SHIT meter for one team: half its chance of finishing last, 30% how far behind the safest team it\n// projects (in standard deviations of its own week), 20% how much of the week is already locked in.\nexport function oshit(row, safety, banked) {\n  if (!row) return null;\n  const gap = safety ? Math.max(0, safety.projFinal - row.projFinal) : 0;\n  const behind = row.sd > 0 ? clamp(gap / (1.5 * row.sd)) : gap > 0 ? 1 : 0;\n  const score = Math.round(100 * (0.5 * clamp(row.odds) + 0.3 * behind + 0.2 * clamp(banked) * clamp(row.odds * 2)));\n  const [level, line] =\n    score >= 80 ? ['O-SHIT', 'It is happening. Check the lineup and find a miracle.']\n    : score >= 60 ? ['Panic', 'Deep trouble: a big night from someone is needed.']\n    : score >= 40 ? ['Sweating', 'On the wrong end of the board with time left to fix it.']\n    : score >= 20 ? ['Uneasy', 'Not safe yet, but not far behind.']\n    : ['Chill', 'Nowhere near the bottom.'];\n  return { score, level, line, gap, behind };\n}\n"],"/pages/dashboard.js":["text/javascript; charset=utf-8","// Dashboard: who is on track for the punishment, how sure we are, game-day times and the week at a glance.\nimport { bankedShare, confidence, oshit } from '../meters.js';\nimport { esc, fmt, moveBadge, names, panel, pct, plural } from '../ui/dom.js';\nimport { gameDayHtml } from '../ui/gameday.js';\nimport { link } from '../ui/router.js';\n\nconst segbar = (score, heat = false) => `<div class=\"segbar${heat ? ' heat' : ''}\" aria-hidden=\"true\">${Array.from({ length: 10 }, (_, i) => `<i class=\"${score > i * 10 ? 'on' : ''}\"></i>`).join('')}</div>`;\n\nfunction heroHtml(m) {\n  const L = m.loser;\n  if (!L) return '';\n  const r = m.recap;\n  const final = r?.final ? `<p class=\"final-banner\">Week ${r.week.id} final: ${esc(names(r.last))} ${r.last.length > 1 ? 'share' : 'cops'} the punishment on ${fmt(r.last[0].weekPts)}.</p>` : '';\n  const gap = m.safety ? `${fmt(m.gap)} behind ${esc(m.safety.name)} on projection.` : '';\n  const conf = confidence(m);\n  const hot = oshit(L, m.safety, bankedShare(m.rows));\n  return `${final}<section class=\"hero\" aria-label=\"Projected last place\">\n    <div>\n      <p class=\"kicker\">On track for the punishment</p>\n      <h2>${esc(L.name)}</h2>\n      ${L.owner ? `<p class=\"owner\">${esc(L.owner)}</p>` : ''}\n      <p class=\"line\">Sitting on ${fmt(L.weekPts)}, projected ${fmt(L.projFinal)}. ${gap} ${plural(L.gamesLeft, 'game')} left across ${plural(L.playersLeft, 'player')}.</p>\n    </div>\n    <div class=\"gauges\">\n      <div class=\"gauge\">\n        <div class=\"gauge-h\"><span>Chance of last place</span><b>${pct(L.odds)}</b></div>\n        ${conf ? `${segbar(conf.score)}<p class=\"why\"><b>Confidence: ${conf.level} (${conf.score})</b>. ${esc(conf.why)}</p>\n        <details><summary>What does confidence mean?</summary><p>It is not a margin of error. It shows how settled the race is: half is how much of the week’s points are already banked, half is how lopsided the odds are. Early in the week, or with several teams in the mix, the percentage can move a lot.</p></details>` : ''}\n      </div>\n      <div class=\"gauge\">\n        <div class=\"gauge-h\"><span>O-SHIT meter</span><b>${hot.score}<small>${esc(hot.level)}</small></b></div>\n        ${segbar(hot.score, true)}<p class=\"why\">${esc(hot.line)}</p>\n        <details><summary>How is this worked out?</summary><p>Half is ${esc(L.name)}’s chance of finishing last, 30% is how far behind the safest team it projects (against its own ups and downs), and 20% is how much of the week is already locked in. 0 is nowhere near trouble, 100 is the punishment looking certain.</p></details>\n      </div>\n    </div>\n  </section>`;\n}\n\nfunction boardHtml(m, app) {\n  const top = Math.max(1, ...m.rows.map((r) => r.weekPts));\n  const lastRank = Math.max(...m.rows.map((r) => r.rank));\n  const mine = app.account.team()?.id;\n  const banked = bankedShare(m.rows);\n  const rows = m.rows\n    .map((r) => {\n      const cls = [r.rank === lastRank && 'last', r.id === mine && 'me'].filter(Boolean).join(' ');\n      const o = oshit(r, m.safety, banked);\n      return `<tr class=\"${cls}\">\n        <td class=\"num strong\">${r.rank}${moveBadge(r.prevRank, r.rank)}</td>\n        <th scope=\"row\"><div class=\"who-cell\"><b>${esc(r.name)}</b>${r.owner ? `<small>${esc(r.owner)}</small>` : ''}</div></th>\n        <td class=\"num strong\">${fmt(r.weekPts)}${r.todayPts ? `<small class=\"muted\"> +${fmt(r.todayPts)}</small>` : ''}</td>\n        <td class=\"hide-sm\" style=\"min-width:110px\"><div class=\"meter ${r.rank === lastRank ? 'bad' : ''}\"><span style=\"width:${(r.weekPts / top) * 100}%\"></span></div></td>\n        <td class=\"num\">${fmt(r.projFinal)}</td>\n        <td class=\"num hide-sm\">${r.gamesLeft}<span class=\"muted\"> / ${r.playersLeft}</span></td>\n        <td class=\"num ${r.odds >= 0.1 ? 'risk-hot' : ''}\">${pct(r.odds)}</td>\n        <td class=\"hide-sm\" style=\"min-width:90px\"><div class=\"meter ${o.score >= 60 ? 'bad' : ''}\" title=\"O-SHIT ${o.score}: ${esc(o.level)}\"><span style=\"width:${o.score}%\"></span></div></td>\n      </tr>`;\n    })\n    .join('');\n  return panel('This week', `<div class=\"tbl-wrap\"><table class=\"tbl\">\n      <thead><tr><th class=\"num\">#</th><th>Team</th><th class=\"num\">Week pts</th><th class=\"hide-sm\"></th><th class=\"num\">Projected</th><th class=\"num hide-sm\">Games / players left</th><th class=\"num\">Last place</th><th class=\"hide-sm\">O-SHIT</th></tr></thead>\n      <tbody>${rows}</tbody></table></div>`, { cls: 'flush', tools: `<a class=\"btn sm\" href=\"${link('matchups')}\">Matchups</a>` });\n}\n\nexport default {\n  id: 'dashboard',\n  label: 'Dashboard',\n  render(app, el) {\n    const m = app.model;\n    const day = gameDayHtml(app);\n    el.innerHTML = `${heroHtml(m)}${day ? `<div class=\"grid main-side\">${boardHtml(m, app)}${day}</div>` : boardHtml(m, app)}`;\n  },\n};\n"],"/pages/index.js":["text/javascript; charset=utf-8","// The pages, in navigation order. A page is { id, label, tabs?, render(app, el, route) }.\nimport dashboard from './dashboard.js';\nimport league from './league.js';\nimport matchups from './matchups.js';\nimport transactions from './transactions.js';\n\nexport const PAGES = [dashboard, league, transactions, matchups];\n"],"/pages/league.js":["text/javascript; charset=utf-8","// League: the punishment history (standings, draft and more arrive in later phases).\nimport { esc, fmt, panel } from '../ui/dom.js';\n\nfunction punishmentsHtml(app) {\n  const m = app.model;\n  const weeks = m.shame;\n  const needsLoad = app.ctx.source === 'roster' && !app.seasonLoaded && m.week.id > 1;\n  if (needsLoad && !weeks.length) {\n    return panel('Punishments', `<p class=\"lede\">Past weeks are rebuilt from ESPN’s daily stats, one request per day.</p><button type=\"button\" class=\"btn primary\" data-action=\"season\">Load past weeks</button>`);\n  }\n  if (!weeks.length) return panel('Punishments', '<p class=\"empty\">No finished weeks yet. The first punishment is decided after the last game of week 1.</p>');\n\n  const tally = new Map();\n  for (const w of weeks) for (const l of w.losers) tally.set(l.id, (tally.get(l.id) || 0) + 1);\n  const nameOf = (id) => app.ctx.league.teams.find((t) => t.id === id)?.name || `Team ${id}`;\n  const counts = [...tally].sort((a, b) => b[1] - a[1]).map(([id, n]) => `<li><b>${esc(nameOf(id))}</b><span>${n}</span></li>`).join('');\n  const list = weeks\n    .map((w) => `<li>\n        <p class=\"wk\"><span>Week ${w.week}</span><span>${esc(w.label)}</span></p>\n        <p class=\"who-lost\">${esc(w.losers.map((l) => nameOf(l.id)).join(' and '))}</p>\n        <p class=\"note\">${fmt(w.losers[0].pts)} points${w.margin ? `, ${fmt(w.margin)} short of safety` : ''}. Top score ${fmt(w.top.pts)} by ${esc(nameOf(w.top.id))}.</p>\n      </li>`)\n    .join('');\n  const more = needsLoad ? '<button type=\"button\" class=\"btn primary\" data-action=\"season\">Load all past weeks</button>' : '';\n  return `<div class=\"grid\">${panel('Punishments so far', `<ol class=\"tally\">${counts}</ol>`)}${panel('Every week', `<ol class=\"shame\">${list}</ol>${more}`)}</div>`;\n}\n\nexport default {\n  id: 'league',\n  label: 'League',\n  render(app, el) {\n    el.innerHTML = punishmentsHtml(app);\n  },\n};\n"],"/pages/matchups.js":["text/javascript; charset=utf-8","// Matchups: the day recap (live \"so far\" and final) and the rest-of-week outlook.\nimport { esc, fmt, moveBadge, names, ordinal, panel, pct, segmented } from '../ui/dom.js';\n\nconst state = { view: 'live' };\n\nfunction recapHtml(app) {\n  const m = app.model;\n  const live = m.recapLive && state.view !== 'final' ? m.recapLive : null;\n  const r = live || m.recap;\n  if (!r) return panel('Day recap', '<p class=\"empty\">The first recap appears after the season’s opening night.</p>');\n\n  const lines = [];\n  if (r.final) lines.push(`<li><b>${esc(names(r.last))}</b> finished last for week ${r.week.id} on ${fmt(r.last[0].weekPts)}.</li>`);\n  for (const c of r.climbers.slice(0, 3)) lines.push(`<li><b>${esc(c.name)}</b> climbed ${c.move} to ${ordinal(c.rank)} with ${fmt(c.dayPts)} on the day.</li>`);\n  for (const f of r.fallers.slice(0, 3)) lines.push(`<li><b>${esc(f.name)}</b> dropped ${-f.move} to ${ordinal(f.rank)}.</li>`);\n  if (!r.climbers.length && !r.fallers.length) lines.push(`<li>${r.dayNumber === 1 ? 'First day of the week, so these are the starting positions.' : 'No change in the order.'}</li>`);\n  lines.push(`<li>Best day: <b>${esc(r.topDay.name)}</b> with ${fmt(r.topDay.dayPts)}. Worst: <b>${esc(r.lowDay.name)}</b> with ${fmt(r.lowDay.dayPts)}.</li>`);\n\n  const mine = app.account.team()?.id;\n  const table = r.rows\n    .map((x) => `<tr class=\"${[r.last.some((l) => l.id === x.id) && 'last', x.id === mine && 'me'].filter(Boolean).join(' ')}\">\n        <td class=\"num\">${x.rank}${moveBadge(x.prevRank, x.rank)}</td>\n        <th scope=\"row\">${esc(x.name)}</th>\n        <td class=\"num\">${fmt(x.dayPts)}</td>\n        <td class=\"num strong\">${fmt(x.weekPts)}</td>\n      </tr>`)\n    .join('');\n\n  const players = r.best\n    ? `<div class=\"duo\">\n        <p><span class=\"tag\">Player of the day</span><b>${esc(r.best.name)}</b> ${fmt(r.best.pts)} for ${esc(r.best.team)}</p>\n        <p><span class=\"tag\">Dud of the day</span><b>${esc(r.worst.name)}</b> ${fmt(r.worst.pts)} for ${esc(r.worst.team)}</p>\n      </div>`\n    : '';\n\n  const switcher = m.recapLive\n    ? segmented('recap', [{ id: 'live', label: `${esc(m.recapLive.label)}, so far` }, { id: 'final', label: `${esc(m.recap.label)}, final` }], live ? 'live' : 'final')\n    : '';\n  return panel(`${esc(r.label)}${live ? ' so far' : ''}`, `\n      <p class=\"lede\">${live ? 'Games are still being played, so these are points so far for' : 'Results for'} week ${r.week.id}, day ${r.dayNumber} of ${r.week.sps.length} (US date).</p>\n      <ul class=\"movers\">${lines.join('')}</ul>\n      <div class=\"tbl-wrap\"><table class=\"tbl\">\n        <thead><tr><th class=\"num\">Pos</th><th>Team</th><th class=\"num\">Day</th><th class=\"num\">Week</th></tr></thead>\n        <tbody>${table}</tbody></table></div>\n      ${players}`, { tools: switcher });\n}\n\nfunction outlookHtml(app) {\n  const m = app.model;\n  const r = m.recapLive || m.recap;\n  const sameWeek = !r || r.week.id === m.week.id;\n  const rest = [...m.rows]\n    .sort((a, b) => b.odds - a.odds || a.projFinal - b.projFinal)\n    .map((x) => `<tr class=\"${x.id === m.loser?.id ? 'last' : ''}\">\n        <th scope=\"row\">${esc(x.name)}</th>\n        <td class=\"num\">${x.gamesLeft}</td>\n        <td class=\"num\">${x.playersLeft}</td>\n        <td class=\"num\">${fmt(x.projFinal)}</td>\n        <td class=\"num strong\">${pct(x.odds)}</td>\n      </tr>`)\n    .join('');\n  return panel(sameWeek ? 'Rest of the week' : `Week ${m.week.id} outlook`, `\n      <p class=\"lede\">The rest of the week is simulated: today’s set lineup, then each team’s best players on later days. Injured players are discounted, healthy ones still sit out about 1 game in 12, and a close race stays close.</p>\n      <div class=\"tbl-wrap\"><table class=\"tbl\">\n        <thead><tr><th>Team</th><th class=\"num\">Games</th><th class=\"num\">Players</th><th class=\"num\">Projected</th><th class=\"num\">Last place</th></tr></thead>\n        <tbody>${rest}</tbody></table></div>`, { cls: 'flush' });\n}\n\nexport default {\n  id: 'matchups',\n  label: 'Matchups',\n  render(app, el) {\n    const draw = () => {\n      el.innerHTML = `<div class=\"grid cols-2\">${recapHtml(app)}${outlookHtml(app)}</div>`;\n    };\n    draw();\n    el.onclick = (e) => {\n      const b = e.target.closest('[data-seg=recap]');\n      if (!b) return;\n      state.view = b.dataset.id;\n      draw();\n    };\n  },\n};\n"],"/pages/transactions.js":["text/javascript; charset=utf-8","// Transactions: the trade workspace (rate, simulate and compare trades). More tabs arrive with the Trade Centre.\nexport default {\n  id: 'transactions',\n  label: 'Transactions',\n  render(app, el) {\n    el.replaceChildren(app.trade.panel);\n    app.trade.render();\n  },\n};\n"],"/pipeline.js":["text/javascript; charset=utf-8","// Loads a league through a data source and builds the inputs for buildModel. No DOM, so the browser,\n// the snapshot builder, the check CLI and the tests all run the same code.\n// A source is { config(), league(views, { sp, fresh, past }), pro(), now(), history?(), offline? } (see sources.js).\nimport {\n  parseLeague, parseProSchedule, parseWeekStart, injuryMap, buildWeeks, currentWeek, weekOf, dailyFromSchedule, scheduleCovers,\n  dayFromRoster, weeklyResults, checkTotals, finishedThrough,\n} from './logic.js';\n\nexport const LIVE_VIEWS = ['mSettings', 'mTeam', 'mRoster', 'mMatchupScore', 'mStatus'];\n\n// Finished days the page needs per-day rosters for: this week so far, plus the week yesterday\n// belongs to (on a Monday that is last week, for the recap). Days without games score nothing.\nexport function neededDays(weeks, cur, pro) {\n  const week = currentWeek(weeks, cur);\n  const yWeek = weekOf(weeks, cur - 1);\n  const sps = [...week.sps, ...(yWeek ? yWeek.sps : [])].filter((sp) => sp < cur && pro.spDate.has(sp));\n  return [...new Set(sps)].sort((a, b) => a - b);\n}\n\n// Days older than yesterday are final, so only those may come from `cache` ({ get(sp), set(sp, dayMap) }).\nexport async function fetchDays(src, season, sps, { cache, cur } = {}) {\n  const out = new Map();\n  const todo = [];\n  const cacheable = (sp) => cache && sp < cur - 1;\n  for (const sp of sps) {\n    const hit = cacheable(sp) ? cache.get(sp) : null;\n    if (hit) out.set(sp, hit);\n    else todo.push(sp);\n  }\n  let i = 0;\n  const worker = async () => {\n    while (i < todo.length) {\n      const sp = todo[i++];\n      const raw = await src.league(['mRoster'], { sp, past: sp < cur - 1 });\n      const day = dayFromRoster(raw, sp, season);\n      if (cacheable(sp)) cache.set(sp, day);\n      out.set(sp, day);\n    }\n  };\n  await Promise.all(Array.from({ length: Math.min(4, todo.length) }, worker));\n  return out;\n}\n\nexport async function loadLeague(src, { forceRoster = false, fresh = false, cache } = {}) {\n  const cfg = await src.config();\n  if (!cfg.configured) return { cfg, unconfigured: true };\n\n  // The injury report is a bonus: without it the model falls back to ESPN's status alone\n  const [leagueRaw, proRaw, injuryList] = await Promise.all([src.league(LIVE_VIEWS, { fresh }), src.pro(), src.injuries ? src.injuries().catch(() => []) : []]);\n  const league = parseLeague(leagueRaw, cfg.season);\n  const injuries = injuryMap(injuryList);\n  for (const t of league.teams) {\n    for (const p of t.roster) {\n      const info = injuries.get(p.playerId);\n      if (info) Object.assign(p, { returnMs: info.returnMs, returnGuess: info.guess, injuryType: info.type, injuryDetail: info.detail });\n    }\n  }\n  const hide = new Set((cfg.hideTeams || []).map((s) => String(s).toLowerCase()));\n  if (hide.size) league.teams = league.teams.filter((t) => ![String(t.id), t.abbrev.toLowerCase(), t.name.toLowerCase()].some((k) => hide.has(k)));\n  if (!league.teams.length) throw new Error('ESPN returned a league with no teams. Check LEAGUE_ID and SEASON.');\n  const pro = parseProSchedule(proRaw);\n  const weeks = buildWeeks(league, pro, { weekStart: parseWeekStart(cfg.weekStart) });\n  const cur = league.currentSP;\n  const needed = neededDays(weeks, cur, pro);\n\n  const today = dayFromRoster(leagueRaw, cur, cfg.season);\n  const dayDetail = new Map([[cur, today]]);\n  let daily = dailyFromSchedule(league);\n  let source = 'schedule';\n\n  if (forceRoster || !scheduleCovers(daily, league, pro, needed)) {\n    source = 'roster';\n    daily = new Map(league.teams.map((t) => [t.id, new Map()]));\n    for (const [sp, day] of await fetchDays(src, cfg.season, needed, { cache, cur })) {\n      dayDetail.set(sp, day);\n      for (const [tid, v] of day) daily.get(tid)?.set(sp, v.pts);\n    }\n  } else if (pro.spDate.has(cur - 1) && cur - 1 >= league.firstSP) {\n    for (const [sp, day] of await fetchDays(src, cfg.season, [cur - 1], { cache, cur })) dayDetail.set(sp, day);\n  }\n  // Today's points so far come from the live roster; ESPN's matchup feed may not have them yet.\n  for (const [tid, v] of today) {\n    if (!daily.has(tid)) daily.set(tid, new Map());\n    if (!daily.get(tid).has(cur)) daily.get(tid).set(cur, v.pts);\n  }\n  return { cfg, league, pro, weeks, daily, dayDetail, source, injuries };\n}\n\n// Fill in every finished day (roster method only) so Shame and the ESPN totals check have the whole season.\nexport async function loadSeasonDays(ctx, src, { cache } = {}) {\n  const { cfg, league, pro, daily } = ctx;\n  const cur = league.currentSP;\n  if (ctx.source === 'roster') {\n    const missing = [];\n    for (let sp = league.firstSP; sp < cur; sp++) {\n      if (pro.spDate.has(sp) && !league.teams.every((t) => daily.get(t.id).has(sp))) missing.push(sp);\n    }\n    const hist = src.history?.();\n    const still = [];\n    for (const sp of missing) {\n      const day = hist?.get(sp);\n      if (day) for (const t of league.teams) daily.get(t.id).set(sp, day.get(t.id) ?? 0);\n      else still.push(sp);\n    }\n    if (still.length && !src.offline) {\n      for (const [sp, day] of await fetchDays(src, cfg.season, still, { cache, cur })) for (const [tid, v] of day) daily.get(tid)?.set(sp, v.pts);\n    }\n  }\n  return {\n    shame: weeklyResults(league.teams, daily, ctx.weeks, finishedThrough(league, pro, src.now()) + 1, pro),\n    check: checkTotals(league.teams, daily, cur),\n  };\n}\n\n// sp -> { teamId: points } for every finished day, as stored in a snapshot's `history`.\nexport function historyOf(ctx) {\n  const out = {};\n  for (const [tid, days] of ctx.daily) {\n    for (const [sp, pts] of days) {\n      if (sp >= ctx.league.currentSP) continue;\n      (out[sp] ||= {})[tid] = pts;\n    }\n  }\n  return out;\n}\n"],"/projection.js":["text/javascript; charset=utf-8","// One player's fantasy point projection: game by game, this week, and for the rest of the season. Pure, no DOM.\n// It uses the same estimate as the trade rating (points a game when he plays, shrunk toward ESPN's preseason\n// projection) and the same availability model as the weekly odds (injury status or ESPN's return date), so the\n// numbers agree with the rest of the site. It does not adjust for the opponent or the pace of the game.\nimport { MODEL, expectedPerGame, missChance, spDay } from './logic.js';\nimport { OUT_STATUSES, rosterValue } from './trade.js';\n\nconst POSITIONS = ['PG', 'SG', 'SF', 'PF', 'C'];\nexport const positionsOf = (p) => POSITIONS.filter((_, slot) => p.eligibleSlots?.includes(slot));\n\n/**\n * @param {object} ctx   tradeContext(...)\n * @param {object} pro   parsed pro schedule\n * @param {object} p     a parsed roster/free-agent player\n * @param {object} o     { week (current week), currentSP, now (ms), games: how many upcoming games to list }\n */\nexport function playerProjection(ctx, pro, p, { week, currentSP, now, games = 10 }) {\n  const v = ctx.valueOf(p);\n  const ppg = expectedPerGame(p);\n  const returnMs = ctx.returnOf(p);\n  const status = String(p.injury || 'ACTIVE').toUpperCase();\n\n  // Upcoming games with the chance he plays each, as the weekly model sees it: known out before his return date,\n  // shaky just after it, otherwise a small chance of sitting that tends to repeat.\n  const list = [];\n  const sps = [...(pro.games.get(p.proTeamId)?.keys() || [])].filter((sp) => sp >= currentSP).sort((a, b) => a - b);\n  let miss = returnMs != null ? MODEL.returnMiss : missChance(status);\n  const persist = missChance(status) >= 1 && returnMs == null ? MODEL.outPersist : MODEL.persist;\n  for (const sp of sps) {\n    const g = pro.games.get(p.proTeamId).get(sp);\n    if (g.date <= now) continue; // already tipped off: its points are in the standings\n    const out = returnMs != null && spDay(pro, sp) < returnMs;\n    const chance = out ? 0 : 1 - miss;\n    list.push({\n      sp,\n      date: g.date,\n      opp: pro.abbrev.get(g.opp) || `#${g.opp}`,\n      home: Boolean(g.home),\n      inWeek: week.sps.includes(sp),\n      playChance: chance,\n      expected: ppg * chance,\n      out,\n    });\n    miss = out ? MODEL.returnMiss : miss * persist + (1 - miss) * MODEL.base;\n    if (list.length >= games + 30) break;\n  }\n  const inWeek = list.filter((g) => g.inWeek);\n  const next7 = list.filter((g) => g.date < now + 7 * 86_400_000);\n\n  // Rest of season, the way the trade rating counts it (his usual play rate, an injured player ramping back)\n  const days = ctx.days;\n  const alone = { ...ctx, slotIds: [11], r: 0, item: () => ({ v: v.perGame, slots: [11], outNow: OUT_STATUSES.has(status) || p.slot === 13, outUntil: returnMs }) };\n  const restPoints = rosterValue([p], days, alone);\n  const gamesLeft = days.filter((d) => ctx.plays(p, d)).length;\n\n  return {\n    name: p.name,\n    team: pro.abbrev.get(p.proTeamId) || '',\n    positions: positionsOf(p),\n    status,\n    returnMs,\n    returnGuess: ctx.guessOf(p),\n    season: { gp: p.seasonGP || 0, avg: p.seasonAvg || 0, last15: p.last15Avg || 0, preseason: p.projAvg || 0 },\n    estimate: { ppg, rate: v.rate, perGame: v.perGame },\n    games: list.slice(0, games),\n    thisWeek: { games: inWeek.length, expected: inWeek.reduce((s, g) => s + g.expected, 0) },\n    next7: { games: next7.length, expected: next7.reduce((s, g) => s + g.expected, 0) },\n    restOfSeason: { games: gamesLeft, missed: ctx.missed(p), expected: restPoints, perWeek: restPoints / Math.max(1, days.length / 7) },\n  };\n}\n"],"/sources.js":["text/javascript; charset=utf-8","// Where data comes from: the /api routes (local server or Cloudflare Worker) or a prebuilt snapshot\n// (GitHub Pages). Both give the pipeline the same interface.\n\n// `get(path, { fresh })` returns parsed JSON or throws an Error with a plain-language message.\nexport function createApiSource(get) {\n  return {\n    kind: 'api',\n    config: () => get('api/config'),\n    pro: () => get('api/pro-schedule'),\n    freeAgents: () => get('api/free-agents').then((b) => b.players),\n    injuries: () => get('api/injuries').then((b) => b.players),\n    league(views, { sp, fresh, past } = {}) {\n      const q = new URLSearchParams();\n      for (const v of views) q.append('view', v);\n      if (sp) q.set('scoringPeriodId', sp);\n      if (fresh) q.set('fresh', '1');\n      if (past) q.set('past', '1');\n      return get(`api/league?${q}`, { fresh });\n    },\n    now: () => Date.now(),\n  };\n}\n\n// ESPN's public scoreboard (open to browsers): which games are scheduled, in play or final on a US date.\n// Returns null when it can't be reached, and the page falls back to estimating from the clock.\nexport async function fetchScoreboard(sp, dateKey, fetchImpl = fetch) {\n  try {\n    const res = await fetchImpl(`https://site.api.espn.com/apis/site/v2/sports/basketball/nba/scoreboard?dates=${dateKey}`, { signal: AbortSignal.timeout(8000) });\n    if (!res.ok) return null;\n    const body = await res.json();\n    return { sp, games: (body.events || []).map((e) => ({ id: e.id, start: Date.parse(e.date), state: e.status?.type?.state, detail: e.status?.type?.detail })) };\n  } catch {\n    return null;\n  }\n}\n\nexport const SNAPSHOT_VERSION = 1;\n\nexport function createSnapshotSource(snap) {\n  const generated = Date.parse(snap.generatedAt);\n  return {\n    kind: 'static',\n    offline: true,\n    generatedAt: generated,\n    config: async () => snap.config,\n    pro: async () => snap.pro,\n    freeAgents: async () => snap.freeAgents || [],\n    injuries: async () => snap.injuries || [],\n    league: async (views, { sp } = {}) => {\n      if (!sp) return snap.league;\n      const day = snap.days?.[sp];\n      if (!day) throw new Error(`The snapshot doesn't include day ${sp}. Run the GitHub workflow again.`);\n      return day;\n    },\n    // Projections use the moment the snapshot was taken, so points and \"games left\" agree.\n    now: () => generated,\n    history: () => new Map(Object.entries(snap.history || {}).map(([sp, m]) => [Number(sp), new Map(Object.entries(m).map(([t, v]) => [Number(t), v]))])),\n  };\n}\n\nexport function checkSnapshot(snap) {\n  if (!snap || typeof snap !== 'object' || snap.version !== SNAPSHOT_VERSION || !snap.league || !snap.pro || !snap.config || !Number.isFinite(Date.parse(snap.generatedAt))) {\n    throw new Error('The data snapshot is missing or unreadable. Run the \"Build and deploy\" workflow again from the Actions tab.');\n  }\n  return snap;\n}\n"],"/suggest.js":["text/javascript; charset=utf-8","// Finds trades to offer. Pure and async-friendly (it yields to the page between stages), no DOM.\n//\n// Brute force is out (one exact check costs ~70 ms on a full season), so it works in stages:\n//   1. work out how much each candidate player adds to, or costs, each team (on a sample of days),\n//   2. rank thousands of combinations from those estimates (cheap arithmetic),\n//   3. check the best few exactly with the lineup engine,\n//   4. re-run the punishment odds for the finalists and drop any that move a team's chance of finishing last too far.\n// Both teams use the same player values, so a trade that truly helps both is rare and small: it can only come from\n// lineup fit. Most good offers are \"balanced\" (neither side loses more than a couple of points a week).\nimport { rosterValue, simulateTrade, starsFor, tradeBaseline, verdict } from './trade.js';\n\nexport const FINDER = {\n  balancedFloor: -1.5, // neither team may lose more than this many points a week (and at least one must gain)\n  winWin: 0.05, // both teams gain at least this much to count as a win-win\n  maxRisk: 0.06, // default most a team's chance of finishing last may move (6 percentage points)\n  sampleEvery: 4, // stage 1 looks at every 4th remaining game day\n  partnerPlayers: 12, // best this many players per partner team are considered\n  verify: 36, // candidates checked exactly\n  guard: 10, // finalists whose punishment odds are re-run\n};\n\nconst tick = () => new Promise((r) => setTimeout(r, 0));\nconst subsets = (items, max) => {\n  const out = items.map((x) => [x]);\n  if (max >= 2) for (let i = 0; i < items.length; i++) for (let j = i + 1; j < items.length; j++) out.push([items[i], items[j]]);\n  return out;\n};\n\n// ESPN lineup slot ids for the five positions, to match a team's \"looking for\" position\nexport const POSITION_SLOTS = { PG: 0, SG: 1, SF: 2, PF: 3, C: 4 };\n\n/**\n * @param {object} o\n *   ctx        tradeContext(...)\n *   teams      league.teams (with rosters)\n *   meId       the team doing the offering\n *   give       player ids on my team I would move (leave empty when `want` is given: then any of mine can be offered)\n *   want       player ids on other teams I want (optional)\n *   partnerId  only look at this team (optional)\n *   boards     Map(teamId -> { block, targets, untouchables, positions }) from the trade block (optional)\n *   baseline   () => tradeBaseline(input), for the punishment-odds guard (optional: without it the guard is skipped)\n *   maxRisk    see FINDER.maxRisk\n *   limit      how many ideas to return\n *   onProgress ({ stage, of, label }) => void\n *   signal     AbortSignal\n */\nexport async function suggestTrades(o) {\n  const { ctx, teams, meId, give = [], want = [], partnerId = null, boards = new Map(), baseline = null, maxRisk = FINDER.maxRisk, limit = 6, onProgress = () => {}, signal = null } = o;\n  const aborted = () => signal?.aborted;\n  const step = async (stage, label) => {\n    onProgress({ stage, of: 4, label });\n    await tick();\n  };\n  const me = teams.find((t) => t.id === meId);\n  const notes = [];\n  const myBoard = boards.get(meId) || { untouchables: [] };\n  const theirUntouchable = (tid) => new Set(boards.get(tid)?.untouchables || []);\n  const ownerOf = new Map();\n  for (const t of teams) for (const p of t.roster) ownerOf.set(p.playerId, t.id);\n\n  // ---- who could be offered, and who could be asked for\n  const myUntouchable = new Set(myBoard.untouchables || []);\n  // players on injured reserve are only offered if the manager picked them\n  let mine = me.roster.filter((p) => !myUntouchable.has(p.playerId) && (p.slot !== 13 || give.includes(p.playerId)));\n  if (give.length) {\n    const blocked = give.filter((id) => myUntouchable.has(id));\n    if (blocked.length) notes.push('Some of the players you picked are on your untouchables list, so they are not offered.');\n    mine = mine.filter((p) => give.includes(p.playerId));\n  }\n  const wanted = want.filter((id) => ownerOf.has(id) && ownerOf.get(id) !== meId);\n  const wantedUntouchable = wanted.filter((id) => theirUntouchable(ownerOf.get(id)).has(id));\n  if (wantedUntouchable.length) {\n    const names = wantedUntouchable.map((id) => teams.find((t) => t.id === ownerOf.get(id)).roster.find((p) => p.playerId === id).name);\n    return { ideas: [], notes: [`${names.join(' and ')} ${names.length > 1 ? 'are' : 'is'} on the other manager’s untouchables list, so offers for ${names.length > 1 ? 'them' : 'him'} are not suggested.`], tried: 0, blockedByUntouchable: true };\n  }\n  if (!mine.length) return { ideas: [], notes: [...notes, 'There are no players to offer. Pick some of yours to shop, or free some from your untouchables.'], tried: 0 };\n\n  const partners = teams.filter((t) => t.id !== meId && (partnerId == null || t.id === partnerId) && (!wanted.length || wanted.some((id) => ownerOf.get(id) === t.id)));\n  if (!partners.length) return { ideas: [], notes: [...notes, 'No other team to trade with.'], tried: 0 };\n\n  // ---- stage 1: what each player adds to or costs each team\n  await step(1, 'Working out what each player is worth to each team');\n  const days = ctx.days.filter((_, i) => i % FINDER.sampleEvery === 0);\n  const sample = { ...ctx, days: days.length ? days : ctx.days };\n  const weeks = Math.max(1, sample.days.length / 7);\n  const rv = (roster) => rosterValue(roster, sample.days, sample) / weeks;\n  const without = (team, p) => team.roster.filter((q) => q.playerId !== p.playerId);\n  const baseMe = rv(me.roster);\n  const loseMe = new Map(mine.map((p) => [p.playerId, baseMe - rv(without(me, p))]));\n  const pool = new Map(); // partner id -> candidate players (excluding their untouchables)\n  for (const t of partners) {\n    const locked = theirUntouchable(t.id);\n    let players = t.roster.filter((p) => !locked.has(p.playerId) && p.slot !== 13);\n    const mustHave = wanted.filter((id) => ownerOf.get(id) === t.id);\n    players = players.map((p) => ({ p, worth: ctx.valueOf(p).perGame })).sort((a, b) => b.worth - a.worth).slice(0, FINDER.partnerPlayers).map((x) => x.p);\n    for (const id of mustHave) if (!players.some((p) => p.playerId === id)) players.push(t.roster.find((p) => p.playerId === id));\n    pool.set(t.id, players);\n  }\n  const addMe = new Map();\n  const loseThem = new Map();\n  const addThem = new Map();\n  const baseThem = new Map();\n  for (const t of partners) {\n    if (aborted()) return { ideas: [], notes: [...notes, 'Cancelled.'], tried: 0, cancelled: true };\n    const base = rv(t.roster);\n    baseThem.set(t.id, base);\n    for (const p of pool.get(t.id)) {\n      addMe.set(p.playerId, rv([...me.roster, p]) - baseMe);\n      loseThem.set(p.playerId, base - rv(without(t, p)));\n    }\n    for (const p of mine) addThem.set(`${t.id}:${p.playerId}`, rv([...t.roster, p]) - base);\n    await tick();\n  }\n\n  // ---- stage 2: rank combinations from those estimates\n  await step(2, 'Trying combinations');\n  const candidates = [];\n  let tried = 0;\n  for (const t of partners) {\n    const theirBoard = boards.get(t.id) || {};\n    const block = new Set(theirBoard.block || []);\n    const targets = new Set(theirBoard.targets || []);\n    const needSlots = new Set((theirBoard.positions || []).map((pos) => POSITION_SLOTS[pos]).filter((x) => x != null));\n    const mustHave = wanted.filter((id) => ownerOf.get(id) === t.id);\n    const optional = pool.get(t.id).filter((p) => !mustHave.includes(p.playerId));\n    // what we ask for: the wanted players alone or with one extra, or (no `want`) one or two of their players\n    const asks = mustHave.length\n      ? [mustHave.map((id) => t.roster.find((p) => p.playerId === id)), ...optional.map((x) => [...mustHave.map((id) => t.roster.find((p) => p.playerId === id)), x])]\n      : subsets(optional, 2);\n    const offers = subsets(mine, 2);\n    const scored = [];\n    for (const S of offers) {\n      for (const H of asks) {\n        tried++;\n        const gainMe = H.reduce((s, p) => s + addMe.get(p.playerId), 0) - S.reduce((s, p) => s + loseMe.get(p.playerId), 0);\n        const gainThem = S.reduce((s, p) => s + addThem.get(`${t.id}:${p.playerId}`), 0) - H.reduce((s, p) => s + loseThem.get(p.playerId), 0);\n        if (gainMe < FINDER.balancedFloor - 1 || gainThem < FINDER.balancedFloor - 1 || Math.max(gainMe, gainThem) <= 0) continue;\n        let bonus = 0;\n        for (const p of H) if (block.has(p.playerId)) bonus += 1;\n        for (const p of S) {\n          if (targets.has(p.playerId)) bonus += 1;\n          if (p.eligibleSlots?.some((s) => needSlots.has(s))) bonus += 0.5;\n        }\n        scored.push({ t, S, H, est: { me: gainMe, them: gainThem }, score: Math.min(gainMe, gainThem) + 0.2 * Math.max(gainMe, gainThem) + bonus });\n      }\n    }\n    scored.sort((a, b) => b.score - a.score);\n    candidates.push(...scored.slice(0, Math.ceil(FINDER.verify * 0.6)));\n    await tick();\n  }\n  candidates.sort((a, b) => b.score - a.score);\n  const shortlist = candidates.slice(0, FINDER.verify);\n\n  // ---- stage 3: exact check of the best\n  await step(3, 'Checking the best ones against every remaining game day');\n  const weeksFull = Math.max(1, ctx.days.length / 7);\n  const full = (roster) => rosterValue(roster, ctx.days, ctx) / weeksFull;\n  const fullBase = new Map([[meId, full(me.roster)]]);\n  const verified = [];\n  const missed = []; // checked exactly but one side loses too much: kept to show the closest options if nothing fits\n  for (const c of shortlist) {\n    if (aborted()) return { ideas: [], notes: [...notes, 'Cancelled.'], tried, cancelled: true };\n    if (!fullBase.has(c.t.id)) fullBase.set(c.t.id, full(c.t.roster));\n    const giveIds = new Set(c.S.map((p) => p.playerId));\n    const getIds = new Set(c.H.map((p) => p.playerId));\n    const gainMe = full([...me.roster.filter((p) => !giveIds.has(p.playerId)), ...c.H]) - fullBase.get(meId);\n    const gainThem = full([...c.t.roster.filter((p) => !getIds.has(p.playerId)), ...c.S]) - fullBase.get(c.t.id);\n    if (gainMe < FINDER.balancedFloor || gainThem < FINDER.balancedFloor || Math.max(gainMe, gainThem) <= 0) {\n      missed.push({ ...c, gains: { me: gainMe, them: gainThem }, why: `${gainMe < gainThem ? 'You lose' : 'They lose'} ${Math.abs(Math.min(gainMe, gainThem)).toFixed(1)} points a week` });\n      continue;\n    }\n    verified.push({ ...c, gains: { me: gainMe, them: gainThem }, tier: gainMe > FINDER.winWin && gainThem > FINDER.winWin ? 'win-win' : 'balanced' });\n    if (verified.length % 6 === 0) await tick();\n  }\n  const rank = (x) => (x.tier === 'win-win' ? 1000 : 0) + Math.min(x.gains.me, x.gains.them) + 0.2 * Math.max(x.gains.me, x.gains.them) + (x.score - Math.min(x.est.me, x.est.them) - 0.2 * Math.max(x.est.me, x.est.them));\n  verified.sort((a, b) => rank(b) - rank(a));\n\n  // ---- stage 4: do the punishment odds stay put?\n  await step(4, 'Checking how each trade moves the chance of finishing last');\n  let finalists = verified.slice(0, FINDER.guard);\n  const guarded = [];\n  if (baseline) {\n    const base = baseline();\n    for (const c of finalists) {\n      if (aborted()) return { ideas: [], notes: [...notes, 'Cancelled.'], tried, cancelled: true };\n      const moves = [...c.S.map((p) => ({ playerId: p.playerId, from: meId, to: c.t.id })), ...c.H.map((p) => ({ playerId: p.playerId, from: c.t.id, to: meId }))];\n      const sim = simulateTrade(base, moves);\n      const move = (wk, id) => {\n        const r = wk?.rows.find((x) => x.id === id);\n        return r ? { before: r.risk0, after: r.risk1 } : null;\n      };\n      const risk = { me: { week: move(sim.thisWeek, meId), typical: move(sim.nextWeek, meId) }, them: { week: move(sim.thisWeek, c.t.id), typical: move(sim.nextWeek, c.t.id) } };\n      const worst = Math.max(...[risk.me.week, risk.me.typical, risk.them.week, risk.them.typical].filter(Boolean).map((r) => Math.abs(r.after - r.before)), 0);\n      if (worst <= maxRisk) guarded.push({ ...c, risk, moves });\n      else missed.push({ ...c, risk, moves, why: `It moves a team’s chance of finishing last by ${Math.round(worst * 100)} points` });\n      await tick();\n    }\n    if (finalists.length && !guarded.length) notes.push(`Every promising trade moved someone’s chance of finishing last by more than ${Math.round(maxRisk * 100)} points. The closest options are below, or raise the limit.`);\n  } else guarded.push(...finalists.map((c) => ({ ...c, risk: null, moves: [...c.S.map((p) => ({ playerId: p.playerId, from: meId, to: c.t.id })), ...c.H.map((p) => ({ playerId: p.playerId, from: c.t.id, to: meId }))] })));\n\n  const describe = (c) => {\n    const theirBoard = boards.get(c.t.id) || {};\n    const reasons = [];\n    for (const p of c.H) if ((theirBoard.block || []).includes(p.playerId)) reasons.push(`${p.name} is on ${c.t.name}’s trade block.`);\n    for (const p of c.S) {\n      if ((theirBoard.targets || []).includes(p.playerId)) reasons.push(`${c.t.name} is targeting ${p.name}.`);\n      const need = (theirBoard.positions || []).find((pos) => p.eligibleSlots?.includes(POSITION_SLOTS[pos]));\n      if (need) reasons.push(`${c.t.name} is looking for a ${need}, and ${p.name} plays there.`);\n    }\n    const moves = c.moves || [...c.S.map((p) => ({ playerId: p.playerId, from: meId, to: c.t.id })), ...c.H.map((p) => ({ playerId: p.playerId, from: c.t.id, to: meId }))];\n    const stars = starsFor(Math.abs(c.gains.me - c.gains.them), moves.length);\n    return {\n      stars,\n      label: verdict(stars),\n      partnerId: c.t.id,\n      partnerName: c.t.name,\n      give: c.S.map((p) => ({ playerId: p.playerId, name: p.name })),\n      get: c.H.map((p) => ({ playerId: p.playerId, name: p.name })),\n      moves,\n      gains: c.gains,\n      tier: c.tier ?? 'closest',\n      risk: c.risk ?? null,\n      why: c.why ?? null,\n      reasons,\n    };\n  };\n  const ideas = guarded.slice(0, limit).map(describe);\n  // Nothing fits: show the nearest misses, each with the reason it missed\n  const closest = ideas.length ? [] : [...missed].sort((a, b) => Math.min(b.gains.me, b.gains.them) - Math.min(a.gains.me, a.gains.them)).slice(0, 3).map(describe);\n  return { ideas, closest, notes, tried };\n}\n\nexport { tradeBaseline };\n"],"/trade-ui.js":["text/javascript; charset=utf-8","// The Trade tab. While you trade, the page is just the workspace: your team on the left and the team you are\n// trading with on the right, both lineups on one screen with no scrolling. Add more teams for a multi-way trade.\n// The maths is in trade.js.\nimport { evaluateMultiTrade, explainMoves, multiSummary, shortDate, simulateTrade, tradeBaseline, tradeContext, tradeSummary } from './trade.js';\nimport { signInHtml, bindSignIn, focusPin } from './ui/signin.js';\nimport { esc, pct, signed, starRow } from './ui/dom.js';\n\nconst MAX_TEAMS = 6;\nconst SHORT = { OUT: 'out', INJURY_RESERVE: 'IR', SUSPENSION: 'susp', DAY_TO_DAY: 'DTD', GTD: 'GTD', QUESTIONABLE: 'Q', DOUBTFUL: 'D' };\n\n// `data()` returns { ctx, src } for the league that is currently loaded.\nexport function createTradeUI({ data, account }) {\n  const panel = document.createElement('div');\n  panel.className = 'trade-ui';\n  const st = { view: 'browse', order: [], picks: new Map(), sheet: null, sim: false, simResult: null, simTimer: null, baseline: null, fa: undefined, tctx: null, last: null };\n  const league = () => data().ctx.league;\n  const teamOf = (id) => league().teams.find((t) => t.id === id);\n\n  /* ---------- Who you are (see account.js) ---------- */\n\n  function startOver() {\n    st.view = 'browse';\n    st.order = [];\n    st.picks.clear();\n    st.sheet = null;\n    st.sim = false;\n    st.simResult = null;\n    clearTimeout(st.simTimer);\n    st.last = null;\n  }\n\n  account.onChange(() => {\n    startOver();\n    if (panel.isConnected) render();\n  });\n  bindSignIn(panel, account);\n\n  // Called after every (re)load of the league. A trade in progress survives a refresh.\n  function reset() {\n    st.fa = undefined;\n    st.tctx = null;\n    st.baseline = null;\n    st.simResult = null;\n  }\n\n  // Free agents set the replacement level. Loaded once per refresh; without them a typical level is used.\n  async function prefetch() {\n    const { src } = data();\n    if (st.fa !== undefined || !src?.freeAgents) return;\n    st.fa = null;\n    try {\n      st.fa = await src.freeAgents();\n    } catch {\n      st.fa = [];\n    }\n    st.tctx = null;\n    render();\n  }\n\n  const ctxOf = () => (st.tctx ||= tradeContext({ league: league(), pro: data().ctx.pro, freeAgents: st.fa || [], injuries: data().ctx.injuries }));\n\n  /* ---------- Pieces ---------- */\n\n  // One flat list of one-line rows so every row can share the column's height.\n  function rosterList(team, ctx, { pickable }) {\n    const groups = [['Starting', (p) => p.slot <= 11], ['Bench', (p) => p.slot === 12], ['Injured reserve', (p) => p.slot >= 13]];\n    const n = st.order.length;\n    const rows = groups.flatMap(([title, test]) => {\n      const players = team.roster.filter(test).sort((a, b) => ctx.valueOf(b).ppg - ctx.valueOf(a).ppg);\n      if (!players.length) return [];\n      return [`<li class=\"grp\">${title}</li>`, ...players.map((p) => {\n        const v = ctx.valueOf(p);\n        const back = ctx.returnOf(p);\n        const status = p.injury && p.injury !== 'ACTIVE' ? SHORT[p.injury] || p.injury.replace(/_/g, ' ').toLowerCase() : back ? 'hurt' : '';\n        const full = [p.injury && p.injury !== 'ACTIVE' ? p.injury.replace(/_/g, ' ').toLowerCase() : '', back ? `back about ${shortDate(back)}` : ''].filter(Boolean).join(', ');\n        const chip = status ? `<span class=\"inj\" title=\"${esc(full)}\">${esc(status)}${back ? `<span class=\"when\"> ${shortDate(back)}</span>` : ''}</span>` : '';\n        const pick = st.picks.get(p.playerId);\n        const tip = `${p.name}: ${v.ppg.toFixed(1)} points a game when he plays, plays about ${Math.round(v.rate * 100)}% of games${full ? `; ${full}` : ''}`;\n        const body = `<span class=\"pn\">${esc(p.name)}</span>${chip}<span class=\"pv\">${v.ppg.toFixed(1)}<small class=\"pct\"> ×${Math.round(v.rate * 100)}%</small></span>`;\n        if (!pickable) return `<li class=\"prow\" title=\"${esc(tip)}\"><div class=\"pl static\">${body}</div></li>`;\n        const dest = pick && n > 2\n          ? `<label class=\"dest\">→ <select data-t=\"dest\" data-id=\"${p.playerId}\" aria-label=\"Where ${esc(p.name)} goes\">${st.order.filter((id) => id !== team.id).map((id) => `<option value=\"${id}\"${pick.to === id ? ' selected' : ''}>${esc(teamOf(id).name)}</option>`).join('')}</select></label>`\n          : '';\n        return `<li class=\"prow${pick ? ' picked' : ''}\" title=\"${esc(tip)}\"><label class=\"pl\"><input type=\"checkbox\" data-t=\"tick\" data-id=\"${p.playerId}\" data-team=\"${team.id}\"${pick ? ' checked' : ''}>${body}</label>${dest}</li>`;\n      })];\n    });\n    return `<ul class=\"rfit\">${rows.join('')}</ul>`;\n  }\n\n  const topPlayers = (team, ctx) => [...team.roster].sort((a, b) => ctx.valueOf(b).ppg - ctx.valueOf(a).ppg).slice(0, 3).map((p) => p.name.split(' ').slice(-1)[0]).join(', ');\n\n  /* ---------- Simulating the trade ---------- */\n\n  const baseline = () => {\n    const d = data();\n    if (!st.baseline || st.baseline.ctx !== d.ctx || st.baseline.now !== d.now || st.baseline.dayDone !== d.dayDone) {\n      st.baseline = { ctx: d.ctx, now: d.now, dayDone: d.dayDone, value: tradeBaseline({ ...d.ctx, now: d.now, dayDone: d.dayDone }) };\n    }\n    return st.baseline.value;\n  };\n\n  const movesKey = (moves) => JSON.stringify(moves.map((m) => [m.playerId, m.from, m.to]).sort());\n\n  // The result for these picks if it has been worked out, else null (and it is worked out a moment later so\n  // the screen does not freeze while you tick players)\n  function simFor(moves) {\n    const key = movesKey(moves);\n    if (st.simResult?.key === key && st.simResult.ctx === data().ctx && st.simResult.pf === st.baseline?.value) return st.simResult.value;\n    clearTimeout(st.simTimer);\n    st.simTimer = setTimeout(() => {\n      if (!st.sim || st.view !== 'build') return;\n      const b = baseline();\n      st.simResult = { key, ctx: data().ctx, pf: b, value: simulateTrade(b, moves) };\n      render();\n    }, 30);\n    return null;\n  }\n\n  const nameIn = (rows, id) => rows.find((r) => r.id === id)?.name ?? `Team ${id}`;\n  const riskIn = (rows, id, k) => rows.find((r) => r.id === id)?.[k] ?? 0;\n\n  // \"no worries city 53% → Hang Low 38%\": who is projected last place now and after the trade\n  function lastPlaceLine(wk, me) {\n    const who = (id) => (id === me ? 'You' : nameIn(wk.rows, id));\n    const from = `${esc(who(wk.loser0))} ${pct(riskIn(wk.rows, wk.loser0, 'risk0'))}`;\n    const to = `${esc(who(wk.loser1))} ${pct(riskIn(wk.rows, wk.loser1, 'risk1'))}`;\n    return wk.loser0 === wk.loser1 ? `${from} → ${pct(riskIn(wk.rows, wk.loser1, 'risk1'))}` : `${from} → <b>${to}</b>`;\n  }\n\n  function oddsTable(wk, me) {\n    const who = (r) => (r.id === me ? `${esc(r.name)} <span class=\"youtag\">you</span>` : esc(r.name));\n    const rows = [...wk.rows].sort((a, b) => b.risk1 - a.risk1).map((r) => {\n      const d = r.risk1 - r.risk0;\n      const move = d > 0.02 ? `<span class=\"up\">▲ ${Math.round(d * 100)}</span>` : d < -0.02 ? `<span class=\"down\">▼ ${Math.round(-d * 100)}</span>` : '<span class=\"flat\">–</span>';\n      const last = r.id === wk.loser1 ? ' <span class=\"lastchip\">last</span>' : '';\n      return `<tr class=\"${r.id === wk.loser1 ? 'last' : ''}\"><th scope=\"row\">${who(r)}${last}</th><td class=\"num\">${pct(r.risk0)}</td><td class=\"num strong\">${pct(r.risk1)}</td><td class=\"num\">${move}</td><td class=\"num dim\">${Math.round(r.final0).toLocaleString('en-AU')} → ${Math.round(r.final1).toLocaleString('en-AU')}</td></tr>`;\n    });\n    const headline = wk.loser0 === wk.loser1\n      ? `<b>${esc(nameIn(wk.rows, wk.loser1))}</b> stays the projected last place (${pct(riskIn(wk.rows, wk.loser0, 'risk0'))} → ${pct(riskIn(wk.rows, wk.loser1, 'risk1'))}).`\n      : `<b>${esc(nameIn(wk.rows, wk.loser0))}</b> is no longer projected last. <b>${esc(nameIn(wk.rows, wk.loser1))}</b> is now (${pct(riskIn(wk.rows, wk.loser1, 'risk1'))}).`;\n    return `<h4>${esc(wk.label)}</h4><p class=\"headline\">${headline}</p>\n      <div class=\"scroll\"><table class=\"odds\"><thead><tr><th scope=\"col\">Team</th><th scope=\"col\" class=\"num\">Last now</th><th scope=\"col\" class=\"num\">After</th><th scope=\"col\" class=\"num\"></th><th scope=\"col\" class=\"num\">Projected pts</th></tr></thead><tbody>${rows.join('')}</tbody></table></div>`;\n  }\n\n  function simSheet(result, me) {\n    if (!result) return '<div class=\"verdict sim\"><h3>If this trade happens</h3><p class=\"note\">Simulating…</p></div>';\n    const parts = [result.thisWeek, result.nextWeek].filter(Boolean);\n    return `<div class=\"verdict sim\"><h3>If this trade happens</h3>\n      <p class=\"lede\">Each team’s chance of finishing last, before and after the trade. “After” has the trade done: points already scored this week stay with the team that scored them, and players who move start on the new team’s bench today.</p>\n      ${parts.map((wk) => oddsTable(wk, me)).join('')}\n    </div>`;\n  }\n\n  /* ---------- Views ---------- */\n\n  function signInView() {\n    panel.innerHTML = signInHtml(account, league().teams);\n    focusPin(panel);\n  }\n\n  function browseView(me) {\n    const ctx = ctxOf();\n    const others = league().teams.filter((t) => t.id !== me.id);\n    panel.innerHTML = `<div class=\"fit\">\n      <p class=\"who\">Signed in as <b>${esc(me.name)}</b>${me.owner ? ` (${esc(me.owner)})` : ''}. <button type=\"button\" class=\"link\" data-t=\"signout\">Not you? Switch team</button></p>\n      <div class=\"split\">\n        <section class=\"col mine\"><h3>${esc(me.name)} <span class=\"youtag\">you</span></h3>${rosterList(me, ctx, { pickable: false })}</section>\n        <aside class=\"col\"><h3>Trade with…</h3>\n          <div class=\"cards\" style=\"--rows:${others.length}\">${others.map((t) => `<button type=\"button\" class=\"team-card\" data-t=\"open\" data-id=\"${t.id}\"><b>${esc(t.name)}</b><span>${esc(t.owner)}</span><small>${esc(topPlayers(t, ctx))}</small></button>`).join('')}</div>\n        </aside>\n      </div>\n    </div>`;\n  }\n\n  // The result for the picks so far: the pinned bar, the details panel and the text to copy\n  function resultFor(me, teams, ctx) {\n    const moves = [...st.picks].map(([playerId, m]) => ({ playerId, ...m }));\n    const senders = new Set(moves.map((m) => m.from));\n    if (moves.length < 2 || senders.size < 2) {\n      const hint = st.order.length > 2 ? 'Tick players from at least two teams, and say where each one goes.' : 'Tick at least one player from each team to rate the trade.';\n      return { line: `<span class=\"hint\">${hint}</span>`, sheet: '', summary: '', notes: 0 };\n    }\n    const r = evaluateMultiTrade(ctx, teams, moves);\n    const youGain = r.teams.find((t) => t.id === me.id)?.gain ?? 0;\n    const active = r.teams.filter((t) => t.involved).sort((a, b) => b.gain - a.gain);\n    const cls = (g) => (g < -2 ? 'neg' : 'pos');\n    const name = (id) => (id === me.id ? 'You' : teamOf(id).name);\n    const line = `${starRow(r.stars)} <b>${r.stars}</b> <span class=\"vlabel\">${esc(r.label)}</span><span class=\"vgain\">${active.map((t) => `${esc(name(t.id))} <b class=\"${cls(t.gain)}\">${signed(t.gain)}</b>`).join(' · ')} <small>pts/week</small> <button type=\"button\" class=\"link why\" data-t=\"sheet\">why?</button></span>`;\n\n    const head = r.winnerId == null ? 'Dead even.' : teams.length > 2 ? `${esc(name(r.winnerId))} gain${r.winnerId === me.id ? '' : 's'} the most and ${esc(name(r.loserId))} ${r.loserId === me.id ? 'gain' : 'gains'} the least.` : r.winnerId === me.id ? 'You come out ahead.' : `${esc(name(r.winnerId))} comes out ahead.`;\n    const lines = [];\n    if (youGain < -2) lines.push(`<p class=\"warn\">This costs you about ${Math.abs(youGain).toFixed(0)} points a week.</p>`);\n    else if (active.length && active.every((t) => t.gain > 2)) lines.push('<p class=\"ok\">Every team gains, so this helps everyone.</p>');\n    for (const t of r.teams) if (t.mustDrop) lines.push(`<p class=\"warn\">${esc(name(t.id))} would have ${t.mustDrop} too many players and have to drop ${t.mustDrop === 1 ? 'one' : t.mustDrop}.</p>`);\n    for (const id of r.idle) lines.push(`<p class=\"note\">${esc(teamOf(id).name)} isn’t in any swap yet. Tick a player to send to them, or remove the team.</p>`);\n    for (const n of r.notes) lines.push(`<p class=\"note\">${esc(n)}</p>`);\n\n    const named = moves.map((m) => ({ ...m, name: teamOf(m.from).roster.find((p) => p.playerId === m.playerId)?.name ?? '?' }));\n    const summary = teams.length === 2\n      ? tradeSummary({ stars: r.stars, label: r.label, winner: r.winnerId == null ? null : r.winnerId === me.id ? 'a' : 'b', a: { gain: youGain }, b: { gain: r.teams.find((t) => t.id === teams[1].id).gain } }, { a: me.name, b: teams[1].name, give: named.filter((m) => m.from === me.id).map((m) => m.name), get: named.filter((m) => m.from === teams[1].id).map((m) => m.name) })\n      : multiSummary(r, named);\n\n    const leagueId = data().ctx.cfg.leagueId;\n    const espn = leagueId ? `<a class=\"link\" href=\"https://fantasy.espn.com/basketball/league?leagueId=${encodeURIComponent(leagueId)}\" target=\"_blank\" rel=\"noopener\">Open the league in ESPN to make the trade</a>` : '';\n    const why = explainMoves(ctx, teams, moves);\n    const whyRows = why.rows.map((w) => `<tr><th scope=\"row\">${esc(w.name)}<small>${esc(w.fromName === me.name ? 'yours' : w.fromName)} → ${esc(teamOf(w.to).name === me.name ? 'you' : teamOf(w.to).name)}</small></th><td class=\"num\">${w.ppg.toFixed(1)}</td><td class=\"num\">${Math.round(w.rate * 100)}%</td><td class=\"num strong\">${w.perGame.toFixed(1)}</td><td class=\"num\">${w.canPlay}${w.missed ? `<small>${w.gamesLeft} − ${w.missed} out</small>` : ''}</td><td class=\"num strong ${w.perWeek < 0 ? 'neg' : ''}\">${w.perWeek >= 0 ? '+' : '−'}${Math.abs(w.perWeek).toFixed(1)}</td></tr>`).join('');\n    const sheet = `<div class=\"verdict\">\n        <h3>${esc(r.label)}</h3>\n        <p>${head}</p>\n        <div class=\"gains\">${active.map((t) => `<p><span>${esc(name(t.id))}</span><b class=\"${cls(t.gain)}\">${signed(t.gain)}</b> points a week</p>`).join('')}</div>\n        ${lines.join('')}\n        <h4>Where the numbers come from</h4>\n        <div class=\"why\">${why.story.map((t) => `<p>${esc(t)}</p>`).join('')}</div>\n        <div class=\"split-gain\">${active.map((t) => {\n          const swap = why.swaps[t.id] ?? 0;\n          const fit = t.gain - swap;\n          return `<p><b>${esc(name(t.id))}</b> ${signed(t.gain)} a week = players ${signed(swap)}, lineup fit ${signed(fit)}</p>`;\n        }).join('')}</div>\n        <div class=\"scroll\"><table class=\"odds whytable\"><thead><tr><th scope=\"col\">Player</th><th scope=\"col\" class=\"num\">Points a game when he plays</th><th scope=\"col\" class=\"num\">Plays</th><th scope=\"col\" class=\"num\">Per team game</th><th scope=\"col\" class=\"num\">Games he can play</th><th scope=\"col\" class=\"num\">Worth a week above a free agent</th></tr></thead><tbody>${whyRows}</tbody></table></div>\n        <p class=\"note\">A free agent is worth about ${why.replacement.toFixed(1)} points per team game${why.replacementFromData ? ' (the 6th best healthy free agent right now)' : ' (a typical level)'}.</p>\n        <p class=\"actions\">${espn}</p>\n        <details><summary>How the stars are worked out</summary>\n          <p class=\"note\">Each player is valued by the points he is expected to score when he plays (his games so far, pulled toward ESPN’s preseason projection) times how often he plays. Each team’s best lineup is then compared for every remaining game day, before and after the trade, against what a free agent could give you${ctx.replacementFromData ? ' (using the real free-agent list)' : ' (a typical free agent)'}. The star rating is how unsure we are who really wins: 5 stars means it is too close to call, and fewer stars mean one side clearly wins. In a multi-way trade it compares the team that gains most with the one that gains least. Injuries can swing any trade, so these are odds, not a promise. This tool only judges a trade; make the real one in ESPN.</p>\n        </details>\n      </div>`;\n    return { line, sheet, summary, notes: lines.filter((l) => /warn|note/.test(l)).length };\n  }\n\n  function builderView(me) {\n    const ctx = ctxOf();\n    const teams = st.order.map(teamOf).filter(Boolean);\n    const n = teams.length;\n    const result = resultFor(me, teams, ctx);\n    st.last = result.summary;\n    const valid = Boolean(result.summary);\n    const moves = [...st.picks].map(([playerId, m]) => ({ playerId, ...m }));\n    // Simulating: the odds with the trade done, shown in the bar and in full in the panel\n    const sim = st.sim && valid ? simFor(moves) : null;\n    const simLine = sim\n      ? `<div class=\"simline\">If traded, last place: ${[sim.thisWeek && `this week ${lastPlaceLine(sim.thisWeek, me.id)}`, sim.nextWeek && `a typical week ${lastPlaceLine(sim.nextWeek, me.id)}`].filter(Boolean).join(' · ')}</div>`\n      : st.sim && valid ? '<div class=\"simline\">Simulating…</div>' : '';\n    const sheet = st.sheet === 'details' && result.sheet ? result.sheet : st.sheet === 'sim' && st.sim && valid ? simSheet(sim, me.id) : '';\n    const spare = league().teams.filter((t) => !st.order.includes(t.id));\n    const partnerChoices = league().teams.filter((t) => t.id !== me.id);\n    const cols = teams\n      .map((t, i) => {\n        const head = i === 0\n          ? `<h3>${esc(t.name)} <span class=\"youtag\">you</span></h3>`\n          : n === 2\n            ? `<h3><select data-t=\"partner\" aria-label=\"Team to trade with\">${partnerChoices.map((o) => `<option value=\"${o.id}\"${o.id === t.id ? ' selected' : ''}>${esc(o.name)}</option>`).join('')}</select></h3>`\n            : `<h3>${esc(t.name)} <button type=\"button\" class=\"link\" data-t=\"remove\" data-id=\"${t.id}\">Remove</button></h3>`;\n        return `<section class=\"tcol${i === 0 ? ' mine' : ''}\">${head}${rosterList(t, ctx, { pickable: true })}</section>`;\n      })\n      .join('');\n    panel.innerHTML = `<div class=\"fit build\">\n      <div class=\"tbar\">\n        <div class=\"topline\">\n          <button type=\"button\" class=\"action ghost\" data-t=\"cancel\">✕ Cancel</button>\n          <button type=\"button\" class=\"action\" data-t=\"copy\"${result.summary ? '' : ' disabled'}>Copy summary</button>\n          ${spare.length && n < MAX_TEAMS ? `<select class=\"multi\" data-t=\"add\" aria-label=\"Add a team for a multi-way trade\"><option value=\"\">${n === 2 ? '＋ Multi-way' : '＋ Add team'}</option>${spare.map((t) => `<option value=\"${t.id}\">${esc(t.name)}</option>`).join('')}</select>` : ''}\n          <button type=\"button\" class=\"action${st.sim ? ' on' : ''}\" data-t=\"simulate\" aria-pressed=\"${st.sim}\"${valid ? '' : ' disabled'}>Simulate</button>\n          ${st.sim && valid ? `<button type=\"button\" class=\"action ghost\" data-t=\"odds\" aria-expanded=\"${st.sheet === 'sim'}\">Odds ${st.sheet === 'sim' ? '▴' : '▾'}</button>` : ''}\n          ${result.sheet ? `<button type=\"button\" class=\"action ghost\" data-t=\"sheet\" aria-expanded=\"${st.sheet === 'details'}\">Why &amp; details${result.notes ? ` (${result.notes})` : ''} ${st.sheet === 'details' ? '▴' : '▾'}</button>` : ''}\n        </div>\n        <div class=\"vline\" aria-live=\"polite\">${result.line}</div>\n        ${simLine}\n      </div>\n      <div class=\"cols${n > 2 ? ' many' : ''}\" style=\"--n:${n}\">${cols}</div>\n    </div>\n    ${sheet ? `<div class=\"sheet\" role=\"dialog\" aria-label=\"${st.sheet === 'details' ? 'Trade details' : 'Simulated trade'}\"><button type=\"button\" class=\"closer\" data-t=\"closesheet\" aria-label=\"Close\">✕ Close</button>${sheet}</div>` : ''}`;\n  }\n\n  function render() {\n    if (!data().ctx) return;\n    const me = account.team();\n    const building = Boolean(me) && st.view === 'build' && st.order.length >= 2 && st.order.every(teamOf);\n    document.body.classList.toggle('trading', building);\n    if (!me) signInView();\n    else if (building) builderView(me);\n    else {\n      st.view = 'browse';\n      browseView(me);\n    }\n    fit();\n  }\n\n  // Make the workspace exactly as tall as the space left on screen, so nothing needs scrolling\n  function fit() {\n    const el = panel.querySelector('.fit');\n    if (!el) return;\n    const top = el.getBoundingClientRect().top + window.scrollY;\n    const height = window.visualViewport?.height ?? window.innerHeight;\n    el.style.setProperty('--fit', `${Math.max(340, height - top - 8)}px`);\n    const bar = panel.querySelector('.tbar');\n    panel.style.setProperty('--bar-bottom', `${bar ? bar.getBoundingClientRect().bottom + 6 : 120}px`);\n  }\n  window.addEventListener(\"resize\", () => panel.isConnected && fit());\n\n  /* ---------- Actions ---------- */\n\n  const defaultDest = (from) => {\n    const i = st.order.indexOf(from);\n    const n = st.order.length;\n    return n === 2 ? st.order[1 - i] : st.order[(i + 1) % n];\n  };\n\n  // Re-render after a change, keeping keyboard focus where it was\n  function redraw(focus) {\n    render();\n    if (focus) panel.querySelector(focus)?.focus({ preventScroll: true });\n  }\n\n  panel.addEventListener('click', (e) => {\n    const btn = e.target.closest('[data-t]');\n    if (!btn || !data().ctx) return;\n    const act = btn.dataset.t;\n    const id = Number(btn.dataset.id);\n    if (act === 'signout') account.signOut();\n    else if (act === 'open') {\n      st.order = [account.team().id, id];\n      st.picks.clear();\n      st.view = 'build';\n      render();\n      window.scrollTo(0, 0);\n      fit();\n    } else if (act === 'cancel') {\n      startOver();\n      render();\n    } else if (act === 'sheet') {\n      st.sheet = st.sheet === 'details' ? (st.sim ? 'sim' : null) : 'details';\n      redraw();\n    } else if (act === 'closesheet') {\n      st.sheet = null;\n      redraw();\n    } else if (act === 'odds') {\n      st.sheet = st.sheet === 'sim' ? null : 'sim';\n      redraw();\n    } else if (act === 'simulate') {\n      st.sim = !st.sim;\n      st.sheet = st.sim ? 'sim' : st.sheet === 'sim' ? null : st.sheet;\n      if (!st.sim) clearTimeout(st.simTimer);\n      redraw();\n    } else if (act === 'remove') {\n      st.sheet = null;\n      st.order = st.order.filter((x) => x !== id);\n      for (const [pid, m] of st.picks) {\n        if (m.from === id) st.picks.delete(pid);\n        else if (m.to === id) st.picks.set(pid, { ...m, to: defaultDest(m.from) });\n      }\n      redraw();\n    } else if (act === 'copy') copy(btn);\n  });\n\n  panel.addEventListener('change', (e) => {\n    const el = e.target.closest('[data-t]');\n    if (!el || !data().ctx) return;\n    const act = el.dataset.t;\n    st.sheet = null; // any change to the trade puts the lineups back in reach; the bar keeps showing the result\n    if (act === 'tick') {\n      const pid = Number(el.dataset.id);\n      if (el.checked) st.picks.set(pid, { from: Number(el.dataset.team), to: defaultDest(Number(el.dataset.team)) });\n      else st.picks.delete(pid);\n      redraw(`[data-t=\"tick\"][data-id=\"${pid}\"]`);\n    } else if (act === 'dest') {\n      const pid = Number(el.dataset.id);\n      st.picks.set(pid, { ...st.picks.get(pid), to: Number(el.value) });\n      redraw(`[data-t=\"dest\"][data-id=\"${pid}\"]`);\n    } else if (act === 'partner') {\n      const old = st.order[1];\n      st.order[1] = Number(el.value);\n      for (const [pid, m] of st.picks) if (m.from === old || m.to === old) st.picks.delete(pid);\n      redraw('[data-t=\"partner\"]');\n    } else if (act === 'add' && el.value) {\n      st.order.push(Number(el.value));\n      redraw();\n    }\n  });\n\n  async function copy(btn) {\n    if (!st.last) return;\n    try {\n      await navigator.clipboard.writeText(st.last);\n    } catch {\n      const box = Object.assign(document.createElement('textarea'), { value: st.last });\n      document.body.append(box);\n      box.select();\n      document.execCommand('copy');\n      box.remove();\n    }\n    const before = btn.textContent;\n    btn.textContent = 'Copied!';\n    setTimeout(() => (btn.textContent = before), 1800);\n  }\n\n  return { panel, render, reset, prefetch, state: st };\n}\n"],"/trade.js":["text/javascript; charset=utf-8","// Trade analyser: what a trade is worth to each team over the rest of the season, and how fair it is.\n// Pure functions, no DOM. Method (and why) is in the README under \"Trade tab and the star rating\".\nimport { buildModel, currentWeek, projectTeam, simulateWeek, spDay } from './logic.js';\n\nexport const TRADE = {\n  prior: 16, // games of weight given to ESPN's preseason projection (fitted on last season: best of 8-24)\n  availPrior: 20, // games of weight given to the league-wide play rate when judging how often a player plays\n  baseRate: 0.705, // share of team games a top-owned player actually plays over a season (measured, 311 players)\n  recover: 0.9, // how slowly a player who is out with no known return date drifts back to his usual play rate, per game\n  returnRecover: 0.5, // after a known return date he is back at his usual rate within a few games (an assumption: not testable yet)\n};\n\n/* ---------- One player ---------- */\n\n// Expected points per team game for the rest of the season: points when he plays (shrunk toward ESPN's\n// projection) times how often he plays (shrunk toward the league rate). `p.seasonGP` games played so far\n// out of `teamGames` that his team has played.\nexport function playerValue(p, teamGames, { prior = TRADE.prior, availPrior = TRADE.availPrior, baseRate = TRADE.baseRate } = {}) {\n  const gp = p.seasonGP || 0;\n  const proj = p.projAvg || p.seasonAvg || 0;\n  const ppg = (gp * (p.seasonAvg || 0) + prior * proj) / (gp + prior || 1);\n  const rate = (gp + availPrior * baseRate) / (Math.max(teamGames, gp) + availPrior);\n  return { ppg, rate, perGame: ppg * rate };\n}\n\n// Chance he plays his n-th game from now (n = 0 is the next one): a player who is out starts at 0 and\n// drifts back to his usual rate; a player who is not listed as out just plays at his usual rate.\nexport function playChance(rate, outNow, n, recover = TRADE.recover) {\n  return outNow ? rate * (1 - recover ** (n + 1)) : rate;\n}\n\n/* ---------- One lineup ---------- */\n\n// Best matching (each row used once, each column once), weights >= 0: { total, pairs: [[row, col], ...] }\n// with only the pairs that add value. Hungarian algorithm; the matrix is padded with zeros to a square.\nexport function assign(w) {\n  const rows = w.length;\n  const cols = rows ? w[0].length : 0;\n  const n = Math.max(rows, cols);\n  if (!n) return { total: 0, pairs: [] };\n  const a = Array.from({ length: n + 1 }, (_, i) => Array.from({ length: n + 1 }, (_, j) => (i && j && i <= rows && j <= cols ? -w[i - 1][j - 1] : 0)));\n  const u = Array(n + 1).fill(0);\n  const v = Array(n + 1).fill(0);\n  const p = Array(n + 1).fill(0);\n  const way = Array(n + 1).fill(0);\n  for (let i = 1; i <= n; i++) {\n    p[0] = i;\n    let j0 = 0;\n    const minv = Array(n + 1).fill(Infinity);\n    const used = Array(n + 1).fill(false);\n    do {\n      used[j0] = true;\n      const i0 = p[j0];\n      let delta = Infinity;\n      let j1 = 0;\n      for (let j = 1; j <= n; j++) {\n        if (used[j]) continue;\n        const cur = a[i0][j] - u[i0] - v[j];\n        if (cur < minv[j]) (minv[j] = cur), (way[j] = j0);\n        if (minv[j] < delta) (delta = minv[j]), (j1 = j);\n      }\n      for (let j = 0; j <= n; j++) {\n        if (used[j]) (u[p[j]] += delta), (v[j] -= delta);\n        else minv[j] -= delta;\n      }\n      j0 = j1;\n    } while (p[j0] !== 0);\n    do {\n      const j1 = way[j0];\n      p[j0] = p[j1];\n      j0 = j1;\n    } while (j0);\n  }\n  let total = 0;\n  const pairs = [];\n  for (let j = 1; j <= cols; j++) {\n    if (p[j] && p[j] <= rows && w[p[j] - 1][j - 1] > 0) {\n      total += w[p[j] - 1][j - 1];\n      pairs.push([p[j] - 1, j - 1]);\n    }\n  }\n  return { total, pairs };\n}\n\nexport const maxMatching = (w) => assign(w).total;\n\n// Expected points from one day's lineup. `players` = [{ v, slots }] who have a game that day (v = expected\n// points, slots = lineup slot ids he may fill); `slotIds` = the starting slots; `r` = what a free agent\n// is worth in any slot. A slot nobody beats r for is filled by a free agent.\nexport function dayValue(players, slotIds, r) {\n  return r * slotIds.length + assign(surplus(players, slotIds, r)).total;\n}\n\nconst surplus = (players, slotIds, r) => players.map((p) => slotIds.map((s) => (p.v > r && p.slots.includes(s) ? p.v - r : 0)));\n\n// Which of `players` (by index) start that day.\nexport const dayPicks = (players, slotIds, r) => assign(surplus(players, slotIds, r)).pairs.map(([i]) => i);\n\n/* ---------- One team, rest of season ---------- */\n\n// Expected points over `days` for a roster. `plays(p, day)` says whether his team has a game that day,\n// `item(p)` gives { v, slots, outNow } for him. Games count from now, so an injured player's value ramps up.\nexport function rosterValue(roster, days, { slotIds, r, plays, item, dayMs }) {\n  const items = roster.map((p) => ({ p, ...item(p), seen: 0 }));\n  let total = 0;\n  for (const day of days) {\n    const today = [];\n    for (const it of items) {\n      if (!plays(it.p, day)) continue;\n      let v = it.v;\n      if (it.outUntil != null && dayMs) {\n        // ESPN gives a return date: nothing before it, then a short ramp back to his usual rate\n        if (dayMs(day) < it.outUntil) continue;\n        v *= playChance(1, true, it.seen, TRADE.returnRecover);\n        it.seen += 1;\n      } else if (it.outNow) {\n        v *= playChance(1, true, it.seen);\n        it.seen += 1;\n      }\n      today.push({ v, slots: it.slots });\n    }\n    total += dayValue(today, slotIds, r);\n  }\n  return total;\n}\n\n/* ---------- A trade ---------- */\n\n// Points per week each team gains (negative = loses) from swapping `give` (from A) for `get` (from B).\nexport function tradeGains(rosterA, rosterB, giveIds, getIds, ctx) {\n  const weeks = Math.max(1, ctx.days.length / 7);\n  const key = (p) => p.playerId;\n  const moveA = rosterA.filter((p) => giveIds.includes(key(p)));\n  const moveB = rosterB.filter((p) => getIds.includes(key(p)));\n  const afterA = [...rosterA.filter((p) => !giveIds.includes(key(p))), ...moveB];\n  const afterB = [...rosterB.filter((p) => !getIds.includes(key(p))), ...moveA];\n  const val = (roster) => rosterValue(roster, ctx.days, ctx);\n  return {\n    a: (val(afterA) - val(rosterA)) / weeks,\n    b: (val(afterB) - val(rosterB)) / weeks,\n    rosterA: afterA.length,\n    rosterB: afterB.length,\n  };\n}\n\n/* ---------- Stars ---------- */\n\nexport const STARS = {\n  sigma: 60, // spread of a trade's real outcome per sqrt(player moved), in points a week (fitted: 50-60)\n  replacementRank: 6, // replacement level = the 6th best healthy free agent (about one per team in the league)\n  fallbackReplacement: 20, // expected points per team game of that free agent, when the free-agent list is not available\n};\n\n// Standard normal CDF (Abramowitz-Stegun 26.2.17).\nexport function normalCdf(z) {\n  const t = 1 / (1 + 0.2316419 * Math.abs(z));\n  const d = 0.3989423 * Math.exp((-z * z) / 2);\n  const p = d * t * (0.3193815 + t * (-0.3565638 + t * (1.781478 + t * (-1.821256 + t * 1.330274))));\n  return z > 0 ? 1 - p : p;\n}\n\n// How sure we are the side we picked really comes out ahead (0.5 = coin flip). Real outcomes of a trade are\n// noisy (injuries above all) and noisier the more players move, so the same gap means less in a big trade.\nexport const winnerConfidence = (gap, players) => normalCdf(Math.abs(gap) / (STARS.sigma * Math.sqrt(Math.max(1, players))));\n\n// 5 stars = we can't tell who wins (fair), 0.5 = one side wins almost surely. Steps of half a star.\nexport function starsFor(gap, players) {\n  const lopsided = 2 * winnerConfidence(gap, players) - 1;\n  return Math.min(5, Math.max(0.5, Math.round((5 - 4.5 * lopsided) * 2) / 2));\n}\n\nexport function verdict(stars) {\n  if (stars >= 4.5) return 'Fair deal';\n  if (stars >= 3.5) return 'Slightly lopsided';\n  if (stars >= 2.5) return 'Lopsided';\n  if (stars >= 1.5) return 'Very one-sided';\n  return 'Daylight robbery';\n}\n\n/* ---------- From the league's data ---------- */\n\nexport const OUT_STATUSES = new Set(['OUT', 'SUSPENSION', 'INJURY_RESERVE']);\n\n// Games a pro team has played up to and including scoring period `sp`.\nexport function teamGamesThrough(pro, proTeamId, sp) {\n  let n = 0;\n  for (const g of pro.games.get(proTeamId)?.keys() || []) if (g <= sp) n++;\n  return n;\n}\n\n// Short date, UTC (the dates here are calendar days): \"20 Nov\".\nexport const shortDate = (ms) => new Intl.DateTimeFormat('en-AU', { timeZone: 'UTC', day: 'numeric', month: 'short' }).format(ms);\n\n// Everything the engine needs, from a parsed league. `freeAgents`: parsed free-agent players (any order; without\n// them the replacement level falls back to a typical value). `injuries`: ESPN's injury report as a map by\n// player id (see injuryMap); players it lists get a known return date instead of a guessed recovery.\nexport function tradeContext({ league, pro, freeAgents = [], injuries = new Map() }) {\n  const cur = league.currentSP;\n  const days = [...pro.spSlate.keys()].filter((sp) => sp > cur).sort((a, b) => a - b);\n  const through = cur - 1; // games finished before today\n  const dayMs = (sp) => spDay(pro, sp);\n  const firstDay = days.length ? dayMs(days[0]) : 0;\n  const valueOf = (p) => playerValue(p, teamGamesThrough(pro, p.proTeamId, through));\n  // Expected return date, if ESPN gives one that is still ahead\n  const returnOf = (p) => {\n    const ms = p.returnMs ?? injuries.get(p.playerId)?.returnMs ?? null;\n    return ms != null && ms > firstDay ? ms : null;\n  };\n  const isOut = (p) => OUT_STATUSES.has(String(p.injury || '').toUpperCase());\n  const healthy = freeAgents.filter((p) => returnOf(p) == null && !isOut(p)).map((p) => valueOf(p).perGame).sort((a, b) => b - a);\n  const r = healthy.length >= STARS.replacementRank ? healthy[STARS.replacementRank - 1] : STARS.fallbackReplacement;\n  return {\n    days,\n    slotIds: league.slotIds,\n    r,\n    replacementFromData: healthy.length >= STARS.replacementRank,\n    rosterLimit: league.rosterLimit,\n    valueOf,\n    teamGames: (p) => teamGamesThrough(pro, p.proTeamId, through),\n    dayMs,\n    returnOf,\n    guessOf: (p) => Boolean(p.returnGuess ?? injuries.get(p.playerId)?.guess),\n    plays: (p, sp) => pro.games.get(p.proTeamId)?.has(sp),\n    item: (p) => ({ v: valueOf(p).perGame, slots: p.eligibleSlots?.length ? p.eligibleSlots : [11], outNow: isOut(p) || p.slot === 13, outUntil: returnOf(p) }),\n    // games he will miss before the return date, for the notes\n    missed: (p) => {\n      const ms = returnOf(p);\n      return ms == null ? 0 : days.filter((d) => pro.games.get(p.proTeamId)?.has(d) && dayMs(d) < ms).length;\n    },\n    seasonEnd: days.length ? dayMs(days.at(-1)) : 0,\n    injuries,\n  };\n}\n\n// The working behind a trade's numbers, player by player, in plain language. `rows` has one entry per player who\n// moves: points a game when he plays, how often he plays, the product, games left and what he is worth a week\n// above a free agent. `story` explains in words why two players who score about the same can rate differently.\nexport function explainMoves(ctx, teams, moves) {\n  const owner = new Map();\n  for (const t of teams) for (const p of t.roster) owner.set(p.playerId, { team: t, player: p });\n  const weeks = Math.max(1, ctx.days.length / 7);\n  const rows = moves\n    .filter((m) => owner.get(m.playerId)?.team.id === m.from)\n    .map((m) => {\n      const { team, player: p } = owner.get(m.playerId);\n      const v = ctx.valueOf(p);\n      const gamesLeft = ctx.days.filter((d) => ctx.plays(p, d)).length;\n      const missed = ctx.missed(p);\n      const canPlay = Math.max(0, gamesLeft - missed);\n      return {\n        playerId: p.playerId, name: p.name, from: m.from, to: m.to, fromName: team.name,\n        ppg: v.ppg, rate: v.rate, perGame: v.perGame, gp: p.seasonGP || 0, teamGames: Math.max(ctx.teamGames(p), p.seasonGP || 0),\n        gamesLeft, missed, canPlay,\n        aboveFa: v.perGame - ctx.r,\n        perWeek: ((v.perGame - ctx.r) * canPlay) / weeks,\n      };\n    });\n  // What each team's trade is worth if every player simply played every game he can: what comes in minus what goes out.\n  // A team's real gain differs by the \"lineup fit\" (positions, and who else would start).\n  const swaps = {};\n  for (const r of rows) {\n    swaps[r.to] = (swaps[r.to] ?? 0) + r.perWeek;\n    swaps[r.from] = (swaps[r.from] ?? 0) - r.perWeek;\n  }\n  const one = (n) => n.toFixed(1);\n  const story = [];\n  const out = rows.filter((r) => r.from === rows[0]?.from);\n  const back = rows.filter((r) => r.from !== rows[0]?.from);\n  if (out.length === 1 && back.length === 1) {\n    const [a, b] = [out[0], back[0]];\n    const [hi, lo] = a.ppg >= b.ppg ? [a, b] : [b, a];\n    const better = a.perWeek >= b.perWeek ? a : b;\n    const worse = better === a ? b : a;\n    const same = Math.abs(a.ppg - b.ppg) < 3;\n    story.push(\n      `${hi.name} scores ${one(hi.ppg)} a game when he plays and ${lo.name} ${one(lo.ppg)}${same ? ', which is close' : ''}. But a player only scores when he plays, so the rating uses points a game times how often he plays.`,\n      `${a.name} has played ${a.gp} of his team’s ${a.teamGames} games and ${b.name} ${b.gp} of ${b.teamGames}. Blended with the typical player (about ${Math.round(TRADE.baseRate * 100)}% of games) that is ${Math.round(a.rate * 100)}% and ${Math.round(b.rate * 100)}%, which makes ${one(a.perGame)} and ${one(b.perGame)} points per team game.`,\n    );\n    if (better.name !== hi.name || Math.abs(a.perWeek - b.perWeek) > 1) {\n      story.push(\n        `${better.name} comes out ${one(Math.abs(better.perGame - worse.perGame))} points a game ahead${better.canPlay === worse.canPlay ? ` over the ${better.canPlay} games left (about ${one(better.canPlay / weeks)} a week)` : ''}, which is about ${one(Math.abs(a.perWeek - b.perWeek))} points a week.`,\n      );\n    }\n  }\n  story.push(\n    `Each team’s gain below is that swap, then adjusted for lineup fit: a team can only start players in certain slots (a center can’t fill a guard spot) and a player only helps if he would actually start, so the same swap can be worth more to one team than the other.`,\n  );\n  story.push(\n    `In general: a player’s worth is points a game when he plays × how often he plays × games left, and only the part above what a free agent would give you (about ${one(ctx.r)} points per team game) counts, because you could always pick that player up for nothing. Injured players add nothing until they are back.`,\n  );\n  return { rows, swaps, story, replacement: ctx.r, weeks, replacementFromData: ctx.replacementFromData };\n}\n\n// A message ready to paste into the group chat. `give`/`get` are lists of player names from A's side.\nexport function tradeSummary(result, { a, b, give, get }) {\n  const gain = (v) => `${v < -0.05 ? '−' : '+'}${Math.abs(v).toFixed(1)}`;\n  const edge = result.winner === null ? 'Dead even.' : `Edge to ${result.winner === 'a' ? a : b}.`;\n  return [\n    'Trade idea (from Punishment Watch)',\n    `${a} gives: ${give.join(', ')}`,\n    `${b} gives: ${get.join(', ')}`,\n    `Rating: ${result.stars} out of 5 stars, ${result.label.toLowerCase()}. ${edge}`,\n    `${a} ${gain(result.a.gain)} points a week, ${b} ${gain(result.b.gain)} points a week.`,\n    'Expected lineup points over the rest of the season; injuries can swing any trade.',\n  ].join('\\n');\n}\n\n// Plain-language warnings about injured players who are changing teams.\nfunction injuryNotes(ctx, moving) {\n  const notes = [];\n  for (const p of moving) {\n    const s = String(p.injury || 'ACTIVE').toUpperCase();\n    const ret = ctx.returnOf(p);\n    const what = [p.injuryType, p.injuryDetail].filter((x) => x && !/not specified|unknown/i.test(x)).join(' ').toLowerCase();\n    if (ret != null && ctx.seasonEnd && ret > ctx.seasonEnd) notes.push(`${p.name} is out for the rest of the season${what ? ` (${what})` : ''}.`);\n    else if (ret != null) {\n      const n = ctx.missed(p);\n      notes.push(`${p.name} is out until about ${shortDate(ret)}${what ? ` (${what})` : ''}${n > 0 ? `, so he misses about ${n} ${n === 1 ? 'game' : 'games'}` : ''}.${ctx.guessOf(p) ? ' ESPN has no firm timetable, so that date is a guess.' : ''}`);\n    } else if (OUT_STATUSES.has(s)) notes.push(`${p.name} is out right now, so he adds nothing until he returns.`);\n    else if (s !== 'ACTIVE') notes.push(`${p.name} is listed as ${s.replace(/_/g, ' ').toLowerCase()}.`);\n  }\n  return notes;\n}\n\n// Judge a trade: A gives `giveIds` and gets `getIds` from B. Returns each side's gain in points a week,\n// the winner, the stars and plain-language notes.\nexport function evaluateTrade(ctx, teamA, teamB, giveIds, getIds) {\n  const g = tradeGains(teamA.roster, teamB.roster, giveIds, getIds, ctx);\n  const players = giveIds.length + getIds.length;\n  const gap = g.a - g.b;\n  const stars = starsFor(gap, players);\n  const side = (team, rosterSize, gain) => ({ id: team.id, name: team.name, gain, rosterAfter: rosterSize, mustDrop: Math.max(0, rosterSize - ctx.rosterLimit) });\n  const notes = injuryNotes(ctx, [...teamA.roster.filter((p) => giveIds.includes(p.playerId)), ...teamB.roster.filter((p) => getIds.includes(p.playerId))]);\n  return {\n    a: side(teamA, g.rosterA, g.a),\n    b: side(teamB, g.rosterB, g.b),\n    gap,\n    winner: Math.abs(gap) < 2 ? null : gap > 0 ? 'a' : 'b', // under 2 points a week is dead even\n    stars,\n    label: verdict(stars),\n    players,\n    notes,\n  };\n}\n\n// A trade between two or more teams. `teams`: [{ id, name, roster }]; `moves`: [{ playerId, from, to }] with team ids.\n// Each team's gain is its change in points a week; the rating comes from the spread between the team that gains\n// most and the team that gains least (for two teams that is exactly the gap used by evaluateTrade).\nexport function evaluateMultiTrade(ctx, teams, moves) {\n  const byId = new Map(teams.map((t) => [t.id, t]));\n  const owner = new Map();\n  for (const t of teams) for (const p of t.roster) owner.set(p.playerId, { team: t.id, player: p });\n  const valid = moves.filter((m) => owner.get(m.playerId)?.team === m.from && byId.has(m.to) && m.to !== m.from);\n  const weeks = Math.max(1, ctx.days.length / 7);\n  const involved = new Set(valid.flatMap((m) => [m.from, m.to]));\n  const rows = teams.map((t) => {\n    const leaving = new Set(valid.filter((m) => m.from === t.id).map((m) => m.playerId));\n    const arriving = valid.filter((m) => m.to === t.id).map((m) => owner.get(m.playerId).player);\n    const after = [...t.roster.filter((p) => !leaving.has(p.playerId)), ...arriving];\n    const gain = involved.has(t.id) ? (rosterValue(after, ctx.days, ctx) - rosterValue(t.roster, ctx.days, ctx)) / weeks : 0;\n    return { id: t.id, name: t.name, gain, involved: involved.has(t.id), rosterAfter: after.length, mustDrop: Math.max(0, after.length - ctx.rosterLimit) };\n  });\n  const active = rows.filter((r) => r.involved);\n  const hi = active.reduce((a, b) => (b.gain > a.gain ? b : a), active[0] || { gain: 0 });\n  const lo = active.reduce((a, b) => (b.gain < a.gain ? b : a), active[0] || { gain: 0 });\n  const spread = active.length ? hi.gain - lo.gain : 0;\n  const stars = starsFor(spread, valid.length);\n  return {\n    teams: rows,\n    spread,\n    stars,\n    label: verdict(stars),\n    players: valid.length,\n    winnerId: spread < 2 ? null : hi.id,\n    loserId: spread < 2 ? null : lo.id,\n    notes: injuryNotes(ctx, valid.map((m) => owner.get(m.playerId).player)),\n    idle: rows.filter((r) => !r.involved).map((r) => r.id),\n  };\n}\n\n// Group-chat text for a multi-way trade: who sends which players where, and how it rates.\nexport function multiSummary(result, moves) {\n  const name = (id) => result.teams.find((t) => t.id === id)?.name ?? `Team ${id}`;\n  const gain = (v) => `${v < -0.05 ? '−' : '+'}${Math.abs(v).toFixed(1)}`;\n  const lines = ['Trade idea (from Punishment Watch)'];\n  for (const t of result.teams.filter((r) => r.involved)) {\n    const sent = moves.filter((m) => m.from === t.id);\n    if (sent.length) lines.push(`${t.name} sends: ${sent.map((m) => `${m.name} to ${name(m.to)}`).join(', ')}`);\n  }\n  const edge = result.winnerId == null ? 'Dead even.' : `Biggest winner: ${name(result.winnerId)}. Biggest loser: ${name(result.loserId)}.`;\n  lines.push(`Rating: ${result.stars} out of 5 stars, ${result.label.toLowerCase()}. ${edge}`);\n  lines.push(result.teams.filter((r) => r.involved).map((t) => `${t.name} ${gain(t.gain)}`).join(', ') + ' points a week.');\n  lines.push('Expected lineup points over the rest of the season; injuries can swing any trade.');\n  return lines.join('\\n');\n}\n\n/* ---------- What if the trade happens? ---------- */\n\n// The league with the trade done. Players who move go on the new team's bench for today (his new manager has not\n// set him in a lineup yet); points already scored this week stay with the team that scored them.\nexport function applyMoves(league, moves) {\n  const owner = new Map();\n  for (const t of league.teams) for (const p of t.roster) owner.set(p.playerId, { team: t.id, player: p });\n  const valid = moves.filter((m) => owner.get(m.playerId)?.team === m.from && m.to !== m.from && league.teams.some((t) => t.id === m.to));\n  const leaving = new Set(valid.map((m) => m.playerId));\n  return {\n    ...league,\n    teams: league.teams.map((t) => ({\n      ...t,\n      roster: [...t.roster.filter((p) => !leaving.has(p.playerId)), ...valid.filter((m) => m.to === t.id).map((m) => ({ ...owner.get(m.playerId).player, slot: 12 }))],\n    })),\n  };\n}\n\n// What the odds are right now, worked out once so every trade you try only has to re-run the teams it changes.\n// `input` is what buildModel takes.\nexport function tradeBaseline(input) {\n  const { league, pro, weeks } = input;\n  const before = buildModel(input);\n  const week = currentWeek(weeks, league.currentSP);\n  const upcoming = weeks.find((w) => w.sps[0] > week.sps.at(-1)) || null;\n  const typical = upcoming ? typicalWeek(league, pro, upcoming, null, null) : null;\n  return { input, before, upcoming, typical };\n}\n\n// A full week with nothing scored yet, from the best starters each team could field every day.\nfunction typicalWeek(league, pro, upcoming, seed, reuse) {\n  const rows = league.teams.map((t) => {\n    // currentSP one day before the week, so every day uses the best starters rather than today's set lineup\n    const p = projectTeam(t, { week: upcoming, currentSP: upcoming.sps[0] - 1, pro, now: 0, activeSlots: league.activeSlots });\n    return { id: t.id, current: 0, mean: p.mean, plan: p.plan };\n  });\n  return simulateWeek(rows, 4000, seed, reuse);\n}\n\n// The weekly punishment odds with the trade done, next to the odds now: for this week's remaining games and for a\n// typical full week from here on. Teams the trade does not touch get identical random numbers and are not re-run,\n// so any change shown is from the trade, not luck.\nexport function simulateTrade(baseline, moves) {\n  const { input, before, upcoming, typical } = baseline;\n  const { league, pro } = input;\n  const after = applyMoves(league, moves);\n  const nameOf = (id) => league.teams.find((t) => t.id === id)?.name ?? `Team ${id}`;\n  const ownerOf = (id) => league.teams.find((t) => t.id === id)?.owner ?? '';\n\n  let thisWeek = null;\n  if (before.rows.some((r) => r.gamesLeft > 0)) {\n    const next = buildModel({ ...input, league: after, seed: before.simSeed, reuse: before.simCache });\n    const post = new Map(next.rows.map((r) => [r.id, r]));\n    thisWeek = {\n      label: `Rest of week ${before.week.id}`,\n      rows: before.rows.map((r) => ({ id: r.id, name: r.name, owner: r.owner, current: r.weekPts, risk0: r.odds, risk1: post.get(r.id).odds, final0: r.projFinal, final1: post.get(r.id).projFinal })),\n      loser0: before.loser?.id ?? null,\n      loser1: next.loser?.id ?? null,\n    };\n  }\n\n  let nextWeek = null;\n  if (upcoming && typical) {\n    const b = typicalWeek(after, pro, upcoming, typical.seed, typical.cache);\n    const top = (m) => [...m].sort((x, y) => y[1].odds - x[1].odds)[0]?.[0] ?? null;\n    nextWeek = {\n      label: `A typical week from here on (week ${upcoming.id})`,\n      rows: league.teams.map((t) => ({ id: t.id, name: nameOf(t.id), owner: ownerOf(t.id), current: 0, risk0: typical.get(t.id).odds, risk1: b.get(t.id).odds, final0: typical.get(t.id).mean, final1: b.get(t.id).mean })),\n      loser0: top(typical),\n      loser1: top(b),\n    };\n  }\n  return { thisWeek, nextWeek };\n}\n"],"/ui/dom.js":["text/javascript; charset=utf-8","// Small helpers every page shares: escaping, number formats, and a few bits of markup.\nexport const esc = (s) => String(s ?? '').replace(/[&<>\"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' })[c]);\nexport const fmt = (v, digits = 1) => Number(v || 0).toLocaleString('en-AU', { maximumFractionDigits: digits });\nexport const fmt1 = (v) => (v == null || !Number.isFinite(v) ? '–' : Number(v).toLocaleString('en-AU', { minimumFractionDigits: 1, maximumFractionDigits: 1 }));\nexport const pct = (p) => (p < 0.005 ? '<1%' : p > 0.995 ? '>99%' : `${Math.round(p * 100)}%`);\nexport const signed = (v, digits = 1) => `${v < -(10 ** -digits) / 2 ? '−' : '+'}${Math.abs(v).toFixed(digits)}`;\nexport const plural = (n, word) => `${n} ${word}${n === 1 ? '' : 's'}`;\nexport const names = (rows) => rows.map((r) => r.name).join(' and ');\nexport const ordinal = (n) => {\n  const s = ['th', 'st', 'nd', 'rd'];\n  const v = n % 100;\n  return n + (s[(v - 20) % 10] || s[v] || s[0]);\n};\nexport const stamp = (ms) => new Date(ms).toLocaleString('en-AU', { weekday: 'short', day: 'numeric', month: 'short', hour: 'numeric', minute: '2-digit' });\nexport const clock = (ms) => new Date(ms).toLocaleTimeString('en-AU', { hour: 'numeric', minute: '2-digit' });\nexport const ago = (ms) => {\n  const m = Math.max(0, Math.round((Date.now() - ms) / 60_000));\n  return m < 1 ? 'just now' : m < 90 ? `${m} min ago` : `${Math.round(m / 60)} hours ago`;\n};\n\nexport const starRow = (n) => `<span class=\"stars\" role=\"img\" aria-label=\"${n} out of 5 stars\">${[1, 2, 3, 4, 5].map((i) => `<span class=\"star ${n >= i ? 'on' : n >= i - 0.5 ? 'half' : ''}\">★</span>`).join('')}</span>`;\n\nexport const moveBadge = (prev, rank) => {\n  if (prev == null) return '';\n  const d = prev - rank;\n  if (!d) return '<span class=\"move flat\" aria-label=\"no change\">–</span>';\n  return d > 0 ? `<span class=\"move up\" aria-label=\"up ${d}\">▲${d}</span>` : `<span class=\"move down\" aria-label=\"down ${-d}\">▼${-d}</span>`;\n};\n\n// A panel: titled box with optional right-hand tools. `body` is trusted markup.\nexport const panel = (title, body, { tools = '', cls = '' } = {}) =>\n  `<section class=\"panel ${cls}\"><header class=\"panel-h\"><h2>${title}</h2>${tools ? `<div class=\"panel-tools\">${tools}</div>` : ''}</header><div class=\"panel-b\">${body}</div></section>`;\n\nexport const empty = (text) => `<p class=\"empty\">${text}</p>`;\n\n// Segmented control. items = [{id,label}]\nexport const segmented = (name, items, active) =>\n  `<div class=\"seg\" role=\"group\" aria-label=\"${esc(name)}\">${items.map((i) => `<button type=\"button\" data-seg=\"${esc(name)}\" data-id=\"${esc(i.id)}\" aria-pressed=\"${i.id === active}\">${i.label}</button>`).join('')}</div>`;\n"],"/ui/gameday.js":["text/javascript; charset=utf-8","// The game-day card: when play starts and likely ends in the viewer's time zone, and whether it is finished.\nimport { dayLabel, duration, gameDays, localTime, zoneName } from '../logic.js';\nimport { esc, panel, plural } from './dom.js';\n\nexport function gameDayHtml(app) {\n  if (!app.ctx || app.demo) return '';\n  const { tz, board } = app;\n  const now = Date.now();\n  const when = (ms) => `${localTime(ms, tz)} ${zoneName(ms, tz)}`;\n  const { today, next } = gameDays(app.ctx.pro, app.ctx.league.currentSP, now, board);\n\n  const line = (d, { isNext = false } = {}) => {\n    const label = `${dayLabel(app.ctx.pro, d.sp)} (US)`;\n    const slate = `${plural(d.games, 'game')}, first game ${when(d.firstTip)}, likely finished by ${localTime(d.likelyEnd, tz)}.`;\n    const tag = d.estimated ? ' <span class=\"est\">estimated</span>' : '';\n    if (isNext) return `<p><b>Next: ${esc(label)}:</b> ${esc(slate)}</p>`;\n    let status;\n    if (d.state === 'done') status = '<span class=\"chip done\">Finished for the day</span>';\n    else if (d.state === 'live') {\n      const left = d.likelyEnd - now;\n      const progress = d.final == null ? '' : `${d.final} of ${d.games} games final. `;\n      status = `<span class=\"chip live\">In progress</span> ${progress}${left > 0 ? `About ${duration(left)} to go.` : 'Should be wrapping up.'}`;\n    } else status = `<span class=\"chip soon\">${d.firstTip - now > 60_000 ? `Starts in ${duration(d.firstTip - now)}` : 'Starting now'}</span>`;\n    return `<p><b>${esc(label)}</b> ${status}${tag}</p><p class=\"times\">${d.state === 'done' ? `Played from ${when(d.firstTip)}.` : esc(slate)}</p>`;\n  };\n\n  const over = !today || today.state === 'done';\n  const parts = [today && line(today), over && next && line(next, { isNext: true })].filter(Boolean);\n  if (!parts.length) return '';\n  return panel(`Game day · ${esc(tz.replace('_', ' '))}`, `<div class=\"gameday-b\">${parts.join('')}</div>`, { cls: 'gameday' });\n}\n"],"/ui/router.js":["text/javascript; charset=utf-8","// Hash router. Routes look like #/players/123?pos=PG. Old links (#week, #recap, #shame, #trade) still work.\nconst LEGACY = { week: '/dashboard', recap: '/matchups/recap', shame: '/league/punishments', trade: '/transactions/trade' };\n\nexport function parseHash(hash = location.hash) {\n  let h = hash.replace(/^#/, '');\n  if (LEGACY[h]) h = LEGACY[h];\n  if (!h.startsWith('/')) h = `/${h}`;\n  const [path, query = ''] = h.split('?');\n  const [section = '', tab = '', ...rest] = path.split('/').filter(Boolean);\n  return { section: section || 'dashboard', tab, rest, query: new URLSearchParams(query), path };\n}\n\nexport const link = (section, tab = '', rest = '') => `#/${[section, tab, rest].filter(Boolean).join('/')}`;\n\nexport function onRoute(fn) {\n  const go = () => fn(parseHash());\n  window.addEventListener('hashchange', go);\n  return go;\n}\n\nexport function navigate(path) {\n  if (location.hash === path) window.dispatchEvent(new HashChangeEvent('hashchange'));\n  else location.hash = path;\n}\n\n// Update the query part (filters) without adding history entries or re-rendering the page\nexport function setQuery(route, values) {\n  const q = new URLSearchParams(route.query);\n  for (const [k, v] of Object.entries(values)) v == null || v === '' ? q.delete(k) : q.set(k, v);\n  const s = q.toString();\n  history.replaceState(null, '', `${location.pathname}${location.search}#${route.path}${s ? `?${s}` : ''}`);\n}\n"],"/ui/shell.js":["text/javascript; charset=utf-8","// The frame around every page: main navigation, contextual tabs, account chip, refresh button, banner, footer.\nimport { esc } from './dom.js';\nimport { link } from './router.js';\n\nexport function renderNav(pages, route, el) {\n  el.innerHTML = pages.map((p) => `<a href=\"${link(p.id)}\"${p.id === route.section ? ' aria-current=\"page\"' : ''}>${esc(p.label)}</a>`).join('');\n}\n\nexport function renderSubnav(page, route, nav, inner) {\n  const tabs = page?.tabs;\n  nav.hidden = !tabs?.length;\n  if (!tabs?.length) return;\n  const cur = route.tab || tabs[0].id;\n  inner.innerHTML = tabs.map((t) => `<a href=\"${link(page.id, t.id)}\"${t.id === cur ? ' aria-current=\"page\"' : ''}>${esc(t.label)}</a>`).join('');\n}\n\nexport function renderAccount(btn, team) {\n  btn.hidden = false;\n  btn.innerHTML = team ? `<i>Team</i><b>${esc(team.name)}</b>` : '<b>Sign in</b>';\n  btn.title = team ? 'Your team' : 'Pick your team';\n}\n"],"/ui/signin.js":["text/javascript; charset=utf-8","// \"Who are you?\" panel, used by My Team and the Trade Centre.\nimport { esc } from './dom.js';\n\nexport function signInHtml(account, teams, why = 'to see your players and test trades') {\n  const { pins, pending: pid, pinError } = account.state;\n  const pending = pins ? teams.find((t) => t.id === pid) : null;\n  const intro = pins\n    ? `Pick your team and enter its PIN ${why}. Ask the league organiser if you don’t know it.`\n    : `Pick your team ${why}. This just remembers your team on this device. Everything here is already visible to the whole league, so there is no password.`;\n  const form = pending\n    ? `<form class=\"pin\" data-a=\"pinform\">\n        <label for=\"pin-input\">PIN for <b>${esc(pending.name)}</b></label>\n        <input id=\"pin-input\" type=\"password\" inputmode=\"numeric\" autocomplete=\"off\" maxlength=\"12\" required>\n        <button type=\"submit\" class=\"btn primary\">Sign in</button>\n        ${pinError ? `<p class=\"warn\" role=\"alert\">${esc(pinError)}</p>` : ''}\n      </form>`\n    : '';\n  return `<section class=\"panel signin\"><header class=\"panel-h\"><h2>Who are you?</h2></header><div class=\"panel-b\">\n      <p class=\"lede\">${intro}</p>\n      <div class=\"picks\">${teams.map((t) => `<button type=\"button\" class=\"team-pick${pending?.id === t.id ? ' picked' : ''}\" data-a=\"signin\" data-id=\"${t.id}\"><b>${esc(t.name)}</b><span>${esc(t.owner)}</span></button>`).join('')}</div>\n      ${form}\n    </div></section>`;\n}\n\n// Wire clicks and the PIN form inside `root` to the account. Call once per root element.\nexport function bindSignIn(root, account) {\n  root.addEventListener('click', (e) => {\n    const b = e.target.closest('[data-a=signin]');\n    if (b) account.choose(Number(b.dataset.id));\n  });\n  root.addEventListener('submit', (e) => {\n    const f = e.target.closest('[data-a=pinform]');\n    if (!f || account.state.pending == null) return;\n    e.preventDefault();\n    account.signInWithPin(account.state.pending, f.querySelector('input').value);\n  });\n}\n\nexport function focusPin(root) {\n  root.querySelector('#pin-input')?.focus({ preventScroll: true });\n}\n"]};

export default {
  async fetch(request, env, ctx) {
    const { pathname } = new URL(request.url);
    if (pathname.startsWith('/api/')) return handleApi(request, env, ctx);
    const file = FILES[pathname === '/' ? '/index.html' : pathname];
    if (!file) return new Response('Not found', { status: 404 });
    return new Response(file[1], { headers: { 'content-type': file[0], 'cache-control': 'public, max-age=300' } });
  },
};
